-- RID=84 | MENU=3 | ITEM=1 | RQUERY=1 | NAME=Daftar Penawaran Penjualan (SQ) Detail | FILE=listsalesquotation
SELECT    	sq.sqid ,   	sq.sqnotransaksi ,   	sq.sqtgl,   	kc.knama AS sqcustomer,   	ks.knama AS sqbagianpenjualan ,   	st.nama AS sqstatus ,   	sq.sqmatauang ,   	sq.sqkurs ,   	sq.sqdiskonpersen , sq.sqjmldiskon ,   	sq.sqbiayalain ,   	sq.sqtotalpajak1detail,     	b.bkode , sqd.namabarang , sqd.catatan ,   	sqd.jml ,   	sqd.satuan ,   	sqd.diskon ,   	sqd.harga ,   	((sqd.jml * sqd.harga) - sqd.jmldiskon) AS total FROM m5_sq sq   JOIN m1_contact kc ON sq.sqcustomer = kc.kid  JOIN m1_contact ks ON sq.sqbagianpenjualan = ks.kid  JOIN m0_status st ON sq.sqstatus = st.kode    JOIN m5_sq_detail sqd ON sq.sqid = sqd.idsq  JOIN m1_item b ON sqd.idbarang = b.bid ORDER BY sq.sqtgl , sq.sqid , sq.sqnotransaksi , sqd.urutan;

-- RID=331 | MENU=3 | ITEM=2 | RQUERY=1 | NAME=List Penawaran Penjualan (SQ) Outstanding | FILE=listsalesquotationoutstanding
SELECT    sq.sqid ,   sq.sqnotransaksi ,   sq.sqtgl,   kc.knama AS sqcustomer ,   ks.knama AS sqbagianpenjualan ,   sq.squraian ,     b.bkode ,   sqd.namabarang ,   sqd.catatan ,   sqd.jml,   sqd.satuan ,   (sqd.jmlrealisasi / sqd.nilaisatuan) AS jmlrealisasi ,   (sqd.jml - (sqd.jmlrealisasi / sqd.nilaisatuan)) AS jmlsisa FROM m5_sq sq   JOIN m1_contact kc ON sq.sqcustomer = kc.kid  JOIN m1_contact ks ON sq.sqbagianpenjualan = ks.kid    JOIN m5_sq_detail sqd ON sq.sqid = sqd.idsq  JOIN m1_item b ON sqd.idbarang = b.bid ORDER BY sq.sqtgl , sq.sqid , sq.sqnotransaksi , sqd.urutan;

