-- RID=327 | MENU=3 | ITEM=7 | RQUERY=1 | NAME=SQ Terkait SO dan DO | FILE=sqterkaitsodo
SELECT  	sqd.idsqdetail,  	sod.idsqdetail AS so,  	sq.sqnotransaksi,  	sq.sqtgl,  	b.bkode,  	sqd.namabarang,  	sqd.tipebarang,  	sqd.jml,  	sqd.satuan,  	sq.squraian,  	ks.knama,  	so.sonotransaksi,  	so.sotgl,  	sod.jml AS asjmlso,  	sod.satuan AS assatuanso,  	ddo.donotransaksi,  	ddo.dotgl,  	dod.jml as asjmldo,  	dod.satuan AS assatuando FROM m5_sq sq  JOIN m5_sq_detail sqd ON sqd.idsq = sq.sqid  JOIN m1_contact ks ON ks.kid = sq.sqbagianpenjualan  JOIN m1_item b ON sqd.idbarang = b.bid  LEFT JOIN m5_so_detail sod ON sqd.idsqdetail = sod.idsqdetail  JOIN m5_so so ON so.soid = sod.idso  LEFT JOIN m5_do_detail dod ON dod.idsodetail = sod.idsodetail AND sod.idbarang  JOIN m5_do ddo ON dod.iddo = ddo.doid   GROUP BY sq.sqnotransaksi, so.sonotransaksi, ddo.donotransaksi ORDER BY sq.sqnotransaksi, so.sonotransaksi, ddo.donotransaksi, sqd.urutan;

-- RID=227 | MENU=3 | ITEM=8 | RQUERY=1 | NAME=Penawaran Penjualan (SQ) Valas 1/2 Letter | FILE=salesquotationdetail_valas1
SELECT    	sq.sqid ,   	sq.sqnotransaksi ,   	sq.sqtgl,   	kc.knama AS sqcustomer,   	ks.knama AS sqbagianpenjualan ,   	st.nama AS sqstatus ,   	sq.squraian ,   	sq.sqmatauang ,   	sq.sqkurs ,   	sq.sqdiskonpersen , sq.sqjmldiskon ,   	sq.sqbiayalain ,   	sq.sqtotalpajak1detail,     	b.bkode , sqd.namabarang , sqd.catatan ,   	sqd.jml ,   	sqd.satuan ,   	sqd.diskon ,   	sqd.harga ,   (sqd.harga * sqd.kurs) AS hargavalas ,   	((sqd.jml * sqd.harga) - sqd.jmldiskon) AS total ,   ((sqd.jml * (sqd.harga * sqd.kurs)) - (sqd.jmldiskon * sqd.kurs)) AS totalvalas FROM m5_sq sq   JOIN m1_contact kc ON sq.sqcustomer = kc.kid  JOIN m1_contact ks ON sq.sqbagianpenjualan = ks.kid  JOIN m0_status st ON sq.sqstatus = st.kode    JOIN m5_sq_detail sqd ON sq.sqid = sqd.idsq  JOIN m1_item b ON sqd.idbarang = b.bid WHERE (sq.sqmatauang <> "IDR") AND (sq.sqmatauang <> "RP") ORDER BY sq.sqtgl , sq.sqid , sq.sqnotransaksi , sqd.urutan;

-- RID=328 | MENU=3 | ITEM=9 | RQUERY=1 | NAME=SQ Terkait SO dan PL | FILE=sqterkaitsopl
SELECT  	sqd.idsqdetail,  	sod.idsqdetail AS so,  	sq.sqnotransaksi,  	sq.sqtgl,  	b.bkode,  	sqd.namabarang,  	sqd.tipebarang,  	sqd.jml,  	sqd.satuan,  	sq.squraian,  	ks.knama,  	so.sonotransaksi,  	so.sotgl,  	sod.jml AS asjmlso,  	sod.satuan AS assatuanso,  	pl.plnotransaksi,  	pl.pltgl,  	pld.jml AS asjmlpl,  	pld.satuan AS assatuanpl FROM m5_sq sq  JOIN m5_sq_detail sqd ON sqd.idsq = sq.sqid  JOIN m1_contact ks ON ks.kid = sq.sqbagianpenjualan  JOIN m1_item b ON sqd.idbarang = b.bid  LEFT JOIN m5_so_detail sod ON sqd.idsqdetail = sod.idsqdetail  JOIN m5_so so ON so.soid = sod.idso  LEFT JOIN m5_pl_detail pld ON pld.idsodetail = sod.idsodetail AND sod.idbarang  JOIN m5_pl pl ON pld.idpl = pl.plid   GROUP BY sq.sqnotransaksi, so.sonotransaksi, pl.plnotransaksi ORDER BY sq.sqnotransaksi, so.sonotransaksi, pl.plnotransaksi, sqd.urutan;

-- RID=342 | MENU=3 | ITEM=10 | RQUERY=1 | NAME=Penawaran Penjualan (SQ) Outstanding Sisa | FILE=listsalesquotationoutstandingsisa
SELECT  	sq.sqnotransaksi,  	sq.sqtgl,  	sqd.namabarang,  	sqd.tipebarang,  	b.bkode,  	kc.knama AS customer,  	ks.knama AS salesman,  	sqd.jml,  	sqd.satuan,  	((sqd.jml) - IFNULL(sqd.jmlso,0)) AS jmlso,  	((sqd.jml) - IFNULL(sqd.jmlpl,0)) AS jmlpl,  	((sqd.jml) - IFNULL(sqd.jmldo,0)) AS jmldo,  	((sqd.jml) - IFNULL(sqd.jmldr,0)) AS jmldr,  	((sqd.jml) - IFNULL(sqd.jmlpi,0)) AS jmlpi,  	((sqd.jml) - IFNULL(sqd.jmlsi,0)) AS jmlsi,  	((sqd.jml) - IFNULL(sqd.jmlrnr,0)) AS jmlrnr,  	((sqd.jml) - IFNULL(sqd.jmlsr,0)) AS jmlsr,  	g.wnama,  	(CASE sq.sqstatus  	WHEN 0 THEN 'Draft'  	WHEN 1 THEN 'Minta Approve'  	WHEN 2 THEN 'Approved'  	WHEN 3 THEN 'Inprogress'  	WHEN 4 THEN 'Complete'  	WHEN 5 THEN 'Revisi'  	WHEN 6 THEN 'Reject'  	WHEN 7 THEN 'Close'  	WHEN 8 THEN 'Approve1'  	WHEN 9 THEN 'Approve2'  	WHEN 10 THEN 'Approve3'  	WHEN 11 THEN 'Approve4'  	WHEN 12 THEN 'Hapus'  	END) AS statussq FROM m5_sq sq  JOIN m5_sq_detail sqd ON sq.sqid = sqd.idsq  JOIN m1_item b ON sqd.idbarang = b.bid  JOIN m1_contact kc ON sq.sqcustomer = kc.kid  JOIN m1_contact ks ON sq.sqbagianpenjualan = ks.kid  JOIN m1_warehouse g ON sqd.gudang = g.wkode   ORDER BY sq.sqnotransaksi, sqd.urutan;

