SELECT    	sq.sqid ,   	sq.sqnotransaksi ,   	sq.sqtgl,   	kc.knama AS sqcustomer,   	ks.knama AS sqbagianpenjualan ,   	st.nama AS sqstatus ,   	sq.squraian ,   	sq.sqmatauang ,   	sq.sqkurs ,   	sq.sqdiskonpersen , sq.sqjmldiskon ,   	sq.sqbiayalain ,   	sq.sqtotalpajak1detail,    u.unama,  	b.bkode , sqd.namabarang , sqd.catatan ,   	sqd.jml ,   	sqd.satuan ,   	sqd.harga ,   	(sqd.jml * sqd.harga) AS total ,   	  sq.sqtermin ,   terms.trharijatuhtempo ,     sq.sqcustomtext1 , sq.sqcustomtext2 , sq.sqcustomtext3 FROM m5_sq sq   JOIN m1_contact kc ON sq.sqcustomer = kc.kid  JOIN m1_contact ks ON sq.sqbagianpenjualan = ks.kid  JOIN m0_status st ON sq.sqstatus = st.kode    JOIN m5_sq_detail sqd ON sq.sqid = sqd.idsq  JOIN m1_item b ON sqd.idbarang = b.bid    LEFT JOIN m1_terms terms ON sq.sqtermin = terms.trkode  LEFT JOIN m0_user u ON sq.sqinputuser = u.userid ORDER BY sq.sqtgl , sq.sqid , sq.sqnotransaksi , sqd.urutan;

-- RID=1027 | MENU=3 | ITEM=13 | RQUERY=1 | NAME=Daftar Penawaran Penjualan (SQ) Per Produk  | FILE=listsalesquotation_perproduct
SELECT    b.bid, b.bkode , sqd.namabarang ,    sq.sqnotransaksi , sq.sqtgl , kc.knama AS sqcustomer , ks.knama AS sqbagianpenjualan ,   SUM(sqd.jml) AS jml ,   	sqd.satuan ,   	sqd.diskon ,   	sqd.harga ,   	SUM((sqd.jml * sqd.harga) - sqd.jmldiskon) AS total FROM m5_sq sq   JOIN m1_contact kc ON sq.sqcustomer = kc.kid  JOIN m1_contact ks ON sq.sqbagianpenjualan = ks.kid  JOIN m0_status st ON sq.sqstatus = st.kode    JOIN m5_sq_detail sqd ON sq.sqid = sqd.idsq  JOIN m1_item b ON sqd.idbarang = b.bid GROUP BY sqd.idbarang, b.bid, b.bkode, sqd.namabarang, sqd.satuan, sqd.harga, sqd.idsq ORDER BY sqd.idbarang , b.bid, b.bkode , sqd.namabarang;

-- RID=1170 | MENU=3 | ITEM=14 | RQUERY=1 | NAME=TEST | FILE=TEST
SELECT  a.aid,  a.akode,  a.anama,  a.akategori,  a.atglbeli,  a.ajml,  a.asatuan,  a.amatauang,  a.akurs,  a.aharga,  a.ahargabeli,  a.anilairesidu,  a.aumurekonomis,  a.abebanperbln,  a.aakumulasibeban - IFNULL(SUM(dad.nilaipenyusutan),0) as aakumulasibeban,  a.ahargabeli - (a.aakumulasibeban - IFNULL(SUM(dad.nilaipenyusutan),0)) as anilaibuku FROM m7_da da  JOIN m7_da_detail dad ON da.daid = dad.idda AND da.dastatus IN(2,3,4,7)   AND ((YEAR(da.datgl) = 2014 AND MONTH(da.datgl) > 1) OR (YEAR(da.datgl) > 2014))  RIGHT JOIN m7_asset a ON dad.idaset = a.aid WHERE a.akategori = 'LRD'  AND  ((YEAR(a.atglbeli) = 2014 AND MONTH(a.atglbeli) <= 1) OR (YEAR(a.atglbeli) < 2014)) GROUP BY a.aid ORDER BY a.akategori, a.atglbeli, a.akode, da.datgl;

