sqid,sqcabang,sqlokasi,sqgudang,sqasalbarang,sqasalbarangkategori,sqjenispenjualan,sqjenispenjualankategori,sqcarabayar,  sqsumber,sqautonotransaksi,sqnotransaksi,sqtgl,sqkodepa,sqcustomer,sqcustomerkontak,sq1alamat1,sq1alamat2,sq1alamat3,  sq2alamat1,sq2alamat2,sq2alamat3,sqbagianpenjualan,sqtglkirim,sqtermin,sqtgljatuhtempo,squraian,sqcatatan,sqnoref,sqtglnoref,  sqtglpenutupan,sqmatauang,sqkurs,sqhargatermasukpajak,sqtotal,sqdiskonpersen,sqjmldiskon,sqtotalpajak1detail,sqtotalpajak2detail,  sqbiayalain,sqtotaltransaksi,sqidpr,sqstatuspr,sqstatusso,sqstatuspi,sqstatuspl,sqstatusdo,sqstatusdr,sqstatussi,sqstatusrnr,  sqstatussr,sqstatusrealisasi,sqstatus,sqstatussebelumnya,sqjmlrevisi,sqcetakanke,sqinputuser,sqinputtgl,sqmodifikasiuser,  sqmodifikasitgl,sqposting,sqpostingtgl,sqisclose,sqcustomtext1,sqcustomtext2,sqcustomtext3,sqcustomtext4,sqcustomtext5,  sqcustomint1,sqcustomint2,sqcustomint3,sqcustomdbl1,sqcustomdbl2,sqcustomdbl3,sqcustomdate1,sqcustomdate2,sqcustomdate3,  idsqdetail,idsq,idbarang,namabarang,tipebarang,jml,satuan,nilaisatuan,jmlbarang,satuanbarang,matauang,kurs,harga,diskon,  jmldiskon,pajak1,jmlpajak1,pajak2,jmlpajak2,cabang,lokasi,gudang,costcenter,divisi,subdivisi,proyek,catatan,urutan,idprdetail,jmlpr,  statuspr,jmlso,statusso,jmlpi,statuspi,jmlpl,statuspl,jmldo,statusdo,jmldr,statusdr,jmlsi,statussi,jmlrnr,statusrnr,jmlsr,statussr,  jmlrealisasi,isclose FROM m5_sq sq  JOIN m5_sq_detail sqd ON sq.sqid = sqd.idsq ORDER BY sq.sqtgl ASC,sq.sqtgl ASC, sqd.idsqdetail ASC;

