SELECT    	sq.sqid ,   	sq.sqnotransaksi ,   	sq.sqtgl,   	kc.knama AS sqcustomer,   	kc.k1alamat1 AS sqalamat1customer,  	kc.k1alamat2 AS sqalamat2customer,  	kc.k1notelp1 AS sqnotelpcustomer,  	kc.k1nofax AS sqnofaxcustomer,  	ks.knama AS sqbagianpenjualan ,   	sq.sqcustomerkontak AS sqkontakperson,  	"" AS sqproject,  	sq.sqnoref,  	sq.sqtermin,  	sq.sqcustomtext2 AS sqdeliveryterm,  	sq.sqcustomtext3 AS sqdeliverytime,  	sq.sqcustomtext4 AS sqvalidity,  	CASE sq.sqhargatermasukpajak  		WHEN 0 THEN "Exclude"  		WHEN 1 THEN "Include"  	END AS "caption" ,   	  	st.nama AS sqstatus ,   	sq.squraian ,   	sq.sqcatatan,  	sq.sqmatauang ,   	sq.sqkurs ,   	sq.sqdiskonpersen , sq.sqjmldiskon ,   	sq.sqbiayalain ,   	sq.sqtotalpajak1detail,   	    	b.bkode , sqd.namabarang , sqd.catatan ,   	sqd.jml ,   	sqd.satuan ,   	sqd.diskon ,   	sqd.harga ,   	((sqd.jml * sqd.harga) - sqd.jmldiskon) AS total FROM m5_sq sq   JOIN m1_contact kc ON sq.sqcustomer = kc.kid  JOIN m1_contact ks ON sq.sqbagianpenjualan = ks.kid  JOIN m0_status st ON sq.sqstatus = st.kode    JOIN m5_sq_detail sqd ON sq.sqid = sqd.idsq  JOIN m1_item b ON sqd.idbarang = b.bid ORDER BY sq.sqtgl , sq.sqid , sq.sqnotransaksi , sqd.urutan;

-- RID=86 | MENU=4 | ITEM=1 | RQUERY=1 | NAME=Daftar Order Penjualan (SO) Detail | FILE=listsalesorder
SELECT    	so.soid,   	so.sonotransaksi ,   	so.sotgl ,   	kc.knama AS socustomer ,   	ks.knama AS sobagianpenjualan ,   	st.nama AS sostatus ,   	so.somatauang ,   	so.sokurs ,   	so.sodiskonpersen ,   	so.sojmldiskon ,   	so.sobiayalain ,   	so.sototalpajak1detail ,     	b.bkode ,   	sod.namabarang ,   	sq.sqnotransaksi ,   	sod.catatan,   	sod.jml,   	sod.satuan ,   b.bjmllapangan as kgpcs,  sod.jml / b.bjmllapangan as jmlpcs,  	sod.diskon,   	sod.harga ,   	((sod.jml * sod.harga) - sod.jmldiskon) AS total ,  b.baukuran,  b.bamodel as banozzle,  b2.bkode as bmaterial,  b2.bnama as bmaterialnama,  b2.bstok as bmaterialstok,  IFNULL(SUM(bp.jmlbooking),0) AS bmaterialonorder ,  sod.customdbl3 as maxqtyrc,  so.sojenispenjualankategori as proyeksiprofit FROM m5_so so   JOIN m1_contact kc ON so.socustomer = kc.kid   JOIN m1_contact ks ON so.sobagianpenjualan = ks.kid  JOIN m0_status st ON so.sostatus = st.kode    JOIN m5_so_detail sod on so.soid = sod.idso   JOIN m1_item b ON sod.idbarang = b.bid   LEFT JOIN m5_sq_detail sqd ON sod.idsqdetail = sqd.idsqdetail  LEFT JOIN m5_sq sq ON sqd.idsq = sq.sqid     LEFT JOIN m1_item b2 ON b.bmaterial = b2.bkode  LEFT JOIN m1_item_booking_po bp ON b2.bid = bp.idbarang GROUP BY so.sotgl , so.soid , so.sonotransaksi , sod.urutan, sod.idsodetail ORDER BY so.sotgl , so.soid , so.sonotransaksi , sod.urutan, sod.idsodetail;

-- RID=87 | MENU=4 | ITEM=2 | RQUERY=1 | NAME=Daftar Order Penjualan (SO) Outstanding | FILE=listsalesorderoutstanding
SELECT  so.soid ,   so.sonotransaksi ,  so.sonoref,   so.sotgl ,   kc.knama AS socustomer ,   ks.knama AS sobagianpenjualan ,   so.souraian ,   so.sotglkirim,  b.bkode ,   sod.namabarang ,   sod.catatan ,   sod.jml ,   sod.satuan,   (sod.jmlrealisasi / sod.nilaisatuan) AS jmlrealisasi ,   (sod.jml - (sod.jmlrealisasi / sod.nilaisatuan)) AS jmlsisa,  kc.kcatatan as kcatatan, sod.customdbl3 ,  sod.idsodetail,  ic.icnama as bkategori,  b.bapanjang,  oem.onama as baoem,  b.baukuran,  b.bamodel as banozzle,  b.bjmllapangan as bakonversikgpcs,  so.sonoref as sorefpo,  b.bnamaalias5 as notesrc,  b.bavolume,  b2.bkode as bmaterial,  b2.bnama as bmaterialnama,  b2.bstok as bmaterialstok,  IFNULL(SUM(bp.jmlbooking),0) AS bmaterialonorder ,  sod.jmlrnr as toleransi,  b.bcustom1 as bmin1,  b.bcustom2 as bmax1,  b.bcustom3 as bmin2,  b.bcustom4 as bmax2,  sf.sfnotransaksi as nokontrak,  CASE   WHEN b.baukuran LIKE '%BMW%' THEN RIGHT(b.baukuran, LENGTH(b.baukuran)-8)  WHEN b.baukuran LIKE '%BW%' THEN RIGHT(b.baukuran, LENGTH(b.baukuran)-7)  ELSE b.baukuran  END ukuran,  so.sojenispenjualankategori as proyeksiprofit FROM m5_so so   JOIN m5_so_detail sod on so.soid = sod.idso   JOIN m1_item b ON sod.idbarang = b.bid   JOIN m1_item_category ic ON b.bkategori = ic.ickode  JOIN m1_contact kc ON so.socustomer = kc.kid   JOIN m1_contact ks ON so.sobagianpenjualan = ks.kid  LEFT JOIN m1_oem oem ON b.baoem = oem.okode  LEFT JOIN m1_item b2 ON b.bmaterial = b2.bkode  LEFT JOIN m1_item_booking_po bp ON b2.bid = bp.idbarang   LEFT JOIN m5_sf sf ON so.socustomdbl1 = sf.sfid WHERE so.sostatus in(2,3) AND sod.jml > sod.jmlrealisasi GROUP BY so.sotgl , so.soid , so.sonotransaksi , sod.urutan, sod.idsodetail ORDER BY so.sotgl , so.soid , so.sonotransaksi , sod.urutan, sod.idsodetail;

-- RID=92 | MENU=4 | ITEM=3 | RQUERY=1 | NAME=Order Penjualan (SO) Dengan Harga 1/2 Letter | FILE=salesorderdetail1
SELECT    f_nominal(so.sototaltransaksi, so.somatauang) as terbilang,     so.sohargatermasukpajak ,   	CASE so.sohargatermasukpajak  	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS "caption" ,     	so.soid,   	so.sonotransaksi ,   	so.sotgl ,   	kc.knama AS socustomer ,   	kc.k1alamat1 ,   	ks.knama AS sobagianpenjualan ,   	st.nama AS sostatus ,   	so.somatauang ,   	so.sotermin,  	so.sokurs ,   	so.souraian ,   	so.sodiskonpersen ,   	so.sojmldiskon ,   	so.sobiayalain ,   	so.sototalpajak1detail ,     	b.bkode ,   	sod.namabarang ,   	sod.catatan,   	sod.jml,   	sod.jmldiskon,   	sod.satuan ,   	sod.diskon,   	sod.harga ,   	((sod.jml * sod.harga) - sod.jmldiskon) AS total ,   usr.unama ,   so.sonoref    FROM m5_so so   JOIN m1_contact kc ON so.socustomer = kc.kid   JOIN m1_contact ks ON so.sobagianpenjualan = ks.kid  JOIN m0_status st ON so.sostatus = st.kode    JOIN m5_so_detail sod on so.soid = sod.idso   JOIN m1_item b ON sod.idbarang = b.bid     JOIN m0_user usr ON so.soinputuser = usr.userid ORDER BY so.sotgl , so.soid , so.sonotransaksi , sod.urutan;

-- RID=506 | MENU=4 | ITEM=4 | RQUERY=1 | NAME=Order Penjualan (SO) Dengan Harga 1 Letter | FILE=salesorderdetail2
SELECT    f_nominal(so.sototaltransaksi, so.somatauang) as terbilang,     so.sohargatermasukpajak ,   	CASE so.sohargatermasukpajak  	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS "caption" ,     	so.soid,   	so.sonotransaksi ,   	so.sotgl ,   	kc.knama AS socustomer ,   	kc.k1alamat1 ,   	ks.knama AS sobagianpenjualan ,   	st.nama AS sostatus ,   	so.somatauang ,   	so.sotermin,  	so.sokurs ,   	so.souraian ,   	so.sodiskonpersen ,   	so.sojmldiskon ,   	so.sobiayalain ,   	so.sototalpajak1detail ,     	b.bkode ,   	sod.namabarang ,   	sod.catatan,   	sod.jml,   	sod.jmldiskon,   	sod.satuan ,   	sod.diskon,   	sod.harga ,   	((sod.jml * sod.harga) - sod.jmldiskon) AS total ,   usr.unama ,   so.sonoref    FROM m5_so so   JOIN m1_contact kc ON so.socustomer = kc.kid   JOIN m1_contact ks ON so.sobagianpenjualan = ks.kid  JOIN m0_status st ON so.sostatus = st.kode    JOIN m5_so_detail sod on so.soid = sod.idso   JOIN m1_item b ON sod.idbarang = b.bid     JOIN m0_user usr ON so.soinputuser = usr.userid ORDER BY so.sotgl , so.soid , so.sonotransaksi , sod.urutan;

-- RID=533 | MENU=4 | ITEM=5 | RQUERY=1 | NAME=Order Penjualan (SO), UD | FILE=salesorderdetail1_UD
SELECT    	so.soid,   	so.sonotransaksi ,   	so.sotgl ,   	kc.knama AS socustomer ,   	ks.knama AS sobagianpenjualan ,   	st.nama AS sostatus ,   	so.somatauang ,   	so.sokurs ,   	so.souraian ,   	so.sodiskonpersen ,   	so.sojmldiskon ,   	so.sobiayalain ,   	so.sototalpajak1detail ,     	b.bkode ,   	sod.namabarang ,   	sq.sqnotransaksi ,   	sod.catatan,   	sod.jml,   	sod.satuan ,   	sod.diskon,   	sod.harga ,   	((sod.jml * sod.harga) - sod.jmldiskon) AS total FROM m5_so so   JOIN m1_contact kc ON so.socustomer = kc.kid   JOIN m1_contact ks ON so.sobagianpenjualan = ks.kid  JOIN m0_status st ON so.sostatus = st.kode    JOIN m5_so_detail sod on so.soid = sod.idso   JOIN m1_item b ON sod.idbarang = b.bid   LEFT JOIN m5_sq_detail sqd ON sod.idsqdetail = sqd.idsqdetail  LEFT JOIN m5_sq sq ON sqd.idsq = sq.sqid ORDER BY so.sotgl , so.soid , so.sonotransaksi , sod.urutan;

-- RID=324 | MENU=4 | ITEM=6 | RQUERY=1 | NAME=SO Terkait DO dan PI | FILE=soterkaidopi
SELECT  	sod.idsodetail,  	dod.idsodetail AS ddo,  	so.sonotransaksi,  	so.sotgl,  	sod.jml,  	sod.satuan,  	b.bkode,  	sod.namabarang,  	sod.tipebarang,  	ks.knama,  	ddo.donotransaksi,  	ddo.dotgl,  	dod.jml AS asjmldo,  	dod.satuan AS assatuando,  	pi.pinotransaksi,  	pi.pitgl,  	pid.jml AS asjmlpi,  	pid.satuan AS assatuanpi FROM m5_so so  JOIN m5_so_detail sod ON sod.idso = so.soid  JOIN m1_contact ks ON ks.kid = so.sobagianpenjualan  JOIN m1_item b ON sod.idbarang = b.bid    LEFT JOIN m5_do_detail dod ON sod.idsodetail = dod.idsodetail  JOIN m5_do ddo ON dod.iddo = ddo.doid    LEFT JOIN m5_pi_detail pid ON pid.idpidetail = dod.idpidetail AND dod.idbarang  JOIN m5_pi pi ON pid.idpi = pi.piid     GROUP BY so.sonotransaksi, ddo.donotransaksi, pi.pinotransaksi ORDER BY so.sonotransaksi, ddo.donotransaksi, pi.pinotransaksi, sod.urutan;

-- RID=325 | MENU=4 | ITEM=7 | RQUERY=1 | NAME=SO Terkait DO dan SI | FILE=soterkaidosi
SELECT  	sod.idsodetail,  	dod.idsodetail AS ddo,  	so.sonotransaksi,  	so.sotgl,  	sod.jml,  	sod.satuan,  	b.bkode,  	sod.namabarang,  	sod.tipebarang,  	ks.knama,  	ddo.donotransaksi,  	ddo.dotgl,  	dod.jml AS asjmldo,  	dod.satuan AS assatuando,  	si.sinotransaksi,  	si.sitgl,  	sid.jml AS asjmlsi,  	sid.satuan AS assatuansi   FROM m5_so so  JOIN m5_so_detail sod ON sod.idso = so.soid  JOIN m1_contact ks ON ks.kid = so.sobagianpenjualan  JOIN m1_item b ON sod.idbarang = b.bid  LEFT JOIN m5_do_detail dod ON sod.idsodetail = dod.idsodetail  JOIN m5_do ddo ON dod.iddo = ddo.doid  LEFT JOIN m5_si_detail sid ON sid.iddodetail = dod.iddodetail AND dod.idbarang  JOIN m5_si si ON sid.idsi = si.siid     GROUP BY so.sonotransaksi, ddo.donotransaksi, si.sinotransaksi ORDER BY so.sonotransaksi, ddo.donotransaksi, si.sinotransaksi, sod.urutan;

-- RID=326 | MENU=4 | ITEM=8 | RQUERY=1 | NAME=SO Terkait PL dan DO | FILE=soterkaitpldo
SELECT  	sod.idsodetail,  	pld.idsodetail AS pl,  	so.sonotransaksi,  	so.sotgl,  	sod.jml,  	sod.satuan,  	b.bkode,  	sod.namabarang,  	sod.tipebarang,  	ks.knama,  	pl.plnotransaksi,  	pl.pltgl,  	pld.jml AS asjmlpl,  	pld.satuan AS assatuanpl,  	ddo.donotransaksi,  	ddo.dotgl,  	dod.jml AS asjmldo,  	dod.satuan AS assatuando   FROM m5_so so  JOIN m5_so_detail sod ON sod.idso = so.soid  JOIN m1_contact ks ON ks.kid = so.sobagianpenjualan  JOIN m1_item b ON sod.idbarang = b.bid  LEFT JOIN m5_pl_detail pld ON sod.idsodetail = pld.idsodetail  JOIN m5_pl pl ON pl.plid = pld.idpl  LEFT JOIN m5_do_detail dod ON dod.idpldetail = pld.idpldetail AND pld.idbarang  JOIN m5_do ddo ON dod.iddo = ddo.doid   GROUP BY so.sonotransaksi, pl.plnotransaksi, ddo.donotransaksi ORDER BY so.sonotransaksi, pl.plnotransaksi, ddo.donotransaksi, sod.urutan;

-- RID=88 | MENU=4 | ITEM=9 | RQUERY=1 | NAME=Daftar Order Penjualan (SO) Oustanding Sisa | FILE=listsalesorderoutstandingsisa
SELECT    so.soid ,   so.sonotransaksi ,   so.sotgl ,   kc.knama AS socustomer ,   ks.knama AS sobagianpenjualan ,   so.souraian ,     b.bkode ,   sod.namabarang ,   sod.catatan ,   sod.jml ,   sod.satuan,   (sod.jmlrealisasi / sod.nilaisatuan) AS jmlrealisasi ,   (sod.jml - (sod.jmlrealisasi / sod.nilaisatuan)) AS jmlsisa FROM m5_so so   JOIN m5_so_detail sod on so.soid = sod.idso   JOIN m1_item b ON sod.idbarang = b.bid     LEFT JOIN m1_contact kc ON so.socustomer = kc.kid   LEFT JOIN m1_contact ks ON so.sobagianpenjualan = ks.kid ORDER BY so.sotgl , so.soid , so.sonotransaksi , sod.urutan;

-- RID=89 | MENU=4 | ITEM=10 | RQUERY=1 | NAME=Daftar Order Penjualan (SO) Per Produk | FILE=listsalesorder_perproduk
SELECT     b.bid , b.bkode , sod.namabarang ,   so.sonotransaksi , so.sotgl , kc.knama AS socustomer , ks.knama AS sobagianpenjualan , SUM(sod.jml) AS jml,   	sod.satuan ,   	sod.diskon,   	sod.harga ,   	sum((sod.jml * sod.harga) - sod.jmldiskon) AS total ,  so.sojenispenjualankategori as proyeksiprofit FROM m5_so so   JOIN m1_contact kc ON so.socustomer = kc.kid   JOIN m1_contact ks ON so.sobagianpenjualan = ks.kid  JOIN m0_status st ON so.sostatus = st.kode    JOIN m5_so_detail sod on so.soid = sod.idso   JOIN m1_item b ON sod.idbarang = b.bid GROUP BY sod.idbarang, b.bid, b.bkode, sod.namabarang, sod.satuan, sod.harga, sod.idso ORDER BY sod.idbarang , b.bid, b.bkode , sod.namabarang;

-- RID=323 | MENU=4 | ITEM=11 | RQUERY=1 | NAME=SO Terkait DO dan DR | FILE=soterkaidodr
SELECT  	sod.idsodetail,  	dod.idsodetail AS ddo,  	so.sonotransaksi,  	so.sotgl,  	sod.jml,  	sod.satuan,  	b.bkode,  	sod.namabarang,  	sod.tipebarang,  	ks.knama,  	ddo.donotransaksi,  	ddo.dotgl,  	dod.jml AS asjmldo,  	dod.satuan AS assatuando,  	dr.drnotransaksi,  	dr.drtgl,  	drd.jml AS asjmldr,  	drd.satuan AS asstuandr   FROM m5_so so  JOIN m5_so_detail sod ON sod.idso = so.soid  JOIN m1_contact ks ON ks.kid = so.sobagianpenjualan  JOIN m1_item b ON sod.idbarang = b.bid  LEFT JOIN m5_do_detail dod ON sod.idsodetail = dod.idsodetail  JOIN m5_do ddo ON dod.iddo = ddo.doid    LEFT JOIN m5_dr_detail drd ON drd.iddodetail = dod.iddodetail AND dod.idbarang  JOIN m5_dr dr ON drd.iddr = dr.drid     GROUP BY so.sonotransaksi, ddo.donotransaksi, dr.drnotransaksi ORDER BY so.sonotransaksi, ddo.donotransaksi, dr.drnotransaksi, sod.urutan;

-- RID=90 | MENU=4 | ITEM=12 | RQUERY=1 | NAME=Order Penjualan (SO) Per Lokasi | FILE=salesorderperlocation1
SELECT  so.sonotransaksi,  sod.urutan,  so.sotgl,  kc.knama,  so.so1alamat1 AS soalamat,   so.socatatan,  (CASE so.solokasi   WHEN "R" THEN IFNULL(SUBSTR((SELECT blg.blgkodelokasi   															FROM m0_setting s   															JOIN m1_item_location_warehouse AS blg ON s.snilai = blg.blggudang   															WHERE s.skode = 'GudangSOLokasi' AND blgidbarang = sod.idbarang) FROM 1 FOR 3),'-')   WHEN "B" THEN IFNULL(SUBSTR((SELECT blg.blgkodelokasi   															FROM m0_setting s   															JOIN m1_item_location_warehouse AS blg ON s.snilai = blg.blggudang   															WHERE s.skode = 'GudangSOLokasiToko' AND blgidbarang = sod.idbarang) FROM 1 FOR 3),'-')   END) AS aslokasi,  IFNULL(blg.blgkodelokasi,"") AS asblgkodelokasi,  sod.idsodetail,  b.bid,  b.bkode,  sod.tipebarang,  sod.namabarang,  SUM(sod.jml) AS asjml,  sod.satuan,  sod.catatan,  so.solokasi,  (SELECT blg.blgkodelokasi FROM m0_setting s JOIN m1_item_location_warehouse AS blg ON s.snilai = blg.blggudang WHERE s.skode = 'GudangSOLokasi' AND blgidbarang = sod.idbarang) AS gudanglokasi,  (SELECT SUM(bpg.stok) FROM m0_setting s JOIN m1_item_stock_warehouse bpg ON s.snilai = bpg.kgudang WHERE s.skode = 'GudangSOLokasi' AND bpg.idbarang = sod.idbarang) AS gudangsaldo,  (SELECT blg.blgkodelokasi FROM m0_setting s JOIN m1_item_location_warehouse AS blg ON s.snilai = blg.blggudang WHERE s.skode = 'GudangSOLokasiToko' AND blgidbarang = sod.idbarang) AS tokolokasi,  (SELECT SUM(bpg.stok) FROM m0_setting s JOIN m1_item_stock_warehouse bpg ON s.snilai = bpg.kgudang WHERE s.skode = 'GudangSOLokasiToko' AND bpg.idbarang = sod.idbarang) AS tokosaldo FROM m5_so_detail sod  JOIN m5_so so ON so.soid = sod.idso  JOIN m1_item b ON sod.idbarang = b.bid  JOIN m1_contact kc ON so.socustomer = kc.kid  JOIN m1_contact ks ON so.sobagianpenjualan = ks.kid  LEFT JOIN m1_item_location_warehouse blg ON (sod.lokasi = blg.blgidlokasi AND blg.blgidbarang = sod.idbarang AND sod.gudang = blg.blggudang)   GROUP BY so.soid, b.bkode, sod.tipebarang, sod.namabarang, sod.satuan, blg.blgnamalokasi ORDER BY so.soid, aslokasi, tokolokasi, sod.urutan;

-- RID=1043 | MENU=4 | ITEM=14 | RQUERY=1 | NAME=Order Penjualan (SO) Kategori  | FILE=salesorderdetail_resto_makanan
SELECT    	so.sonotransaksi , so.sotgl , so.somatauang , so.sokurs ,   	st.nama AS sostatus  , kc.knama AS socustomer , ks.knama AS sobagianpenjualan,   	so.souraian ,     	b.bkode , sod.namabarang , sod.catatan , sod.jml , b.bsatuan  , ic.icnama AS bkategori FROM m5_so so   JOIN m0_status st ON so.sostatus = st.kode  JOIN m1_contact ks ON so.sobagianpenjualan = ks.kid  JOIN m5_so_detail sod ON so.soid = sod.idso   JOIN m1_item b ON sod.idbarang = b.bid   JOIN m1_item_category ic ON b.bkategori = ic.ickode   LEFT JOIN m1_contact kc ON so.socustomer = kc.kid ORDER BY so.sonotransaksi , b.bkategori , sod.urutan;

-- RID=1663 | MENU=4 | ITEM=15 | RQUERY=1 | NAME=Daftar Order Penjualan (SO) Global | FILE=listsalesorder_2
SELECT    	so.soid,   	so.sonotransaksi ,   	so.sotgl ,   	kc.knama AS socustomer ,   	ks.knama AS sobagianpenjualan ,   	st.nama AS sostatus ,   	so.somatauang ,   	so.sokurs ,   	so.sodiskonpersen ,   	so.sojmldiskon ,   	so.sobiayalain ,   	so.sototalpajak1detail ,     	b.bkode ,   	sod.namabarang ,   	sq.sqnotransaksi ,   	sod.catatan,   	sod.jml,   	sod.satuan ,   	sod.diskon,   	sod.harga ,   	((sod.jml * sod.harga) - sod.jmldiskon) AS total ,  so.sojenispenjualankategori as proyeksiprofit FROM m5_so so   JOIN m1_contact kc ON so.socustomer = kc.kid   JOIN m1_contact ks ON so.sobagianpenjualan = ks.kid  JOIN m0_status st ON so.sostatus = st.kode    JOIN m5_so_detail sod on so.soid = sod.idso   JOIN m1_item b ON sod.idbarang = b.bid   LEFT JOIN m5_sq_detail sqd ON sod.idsqdetail = sqd.idsqdetail  LEFT JOIN m5_sq sq ON sqd.idsq = sq.sqid ORDER BY so.sotgl , so.soid , so.sonotransaksi , sod.urutan;

-- RID=1690 | MENU=4 | ITEM=16 | RQUERY=1 | NAME=Order Penjualan (SO) Harga 1/2 Letter | FILE=salesorderdetail3
SELECT    	f_nominal(so.sototaltransaksi, so.somatauang) as terbilang,     	so.sohargatermasukpajak ,   	CASE so.sohargatermasukpajak  	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS "caption" ,     	so.soid,   	so.sonotransaksi ,   	so.sotgl ,   	kc.knama AS socustomer ,   	kc.k1alamat1 ,   	ks.knama AS sobagianpenjualan ,   	st.nama AS sostatus ,   	so.somatauang ,   	so.sotermin,  	so.sokurs ,   	so.souraian ,   	so.sodiskonpersen ,   	so.sojmldiskon ,   	so.sobiayalain ,   	so.sototalpajak1detail ,     	b.bkode ,   	sod.namabarang ,   	sq.sqnotransaksi ,   	sod.catatan,   	sod.jml,   	sod.satuan ,   	sod.diskon,   	sod.jmldiskon,  	sod.harga ,   	((sod.jml * sod.harga) - sod.jmldiskon) AS total ,   usr.unama FROM m5_so so   JOIN m1_contact kc ON so.socustomer = kc.kid   JOIN m1_contact ks ON so.sobagianpenjualan = ks.kid  JOIN m0_status st ON so.sostatus = st.kode    JOIN m5_so_detail sod on so.soid = sod.idso   JOIN m1_item b ON sod.idbarang = b.bid   LEFT JOIN m5_sq_detail sqd ON sod.idsqdetail = sqd.idsqdetail  LEFT JOIN m5_sq sq ON sqd.idsq = sq.sqid     JOIN m0_user usr ON so.soinputuser = usr.userid ORDER BY so.sotgl , so.soid , so.sonotransaksi , sod.urutan;

-- RID=1691 | MENU=4 | ITEM=17 | RQUERY=1 | NAME=Order Penjualan (SO) Harga 1 Letter | FILE=salesorderdetail4
SELECT    	f_nominal(so.sototaltransaksi, so.somatauang) as terbilang,     	so.sohargatermasukpajak ,   	CASE so.sohargatermasukpajak  	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS "caption" ,     	so.soid,   	so.sonotransaksi ,   	so.sotgl ,   	kc.knama AS socustomer ,   	kc.k1alamat1 ,   	ks.knama AS sobagianpenjualan ,   	st.nama AS sostatus ,   	so.somatauang ,   	so.sotermin,  	so.sokurs ,   	so.souraian ,   	so.sodiskonpersen ,   	so.sojmldiskon ,   	so.sobiayalain ,   	so.sototalpajak1detail ,     	b.bkode ,   	sod.namabarang ,   	sq.sqnotransaksi ,   	sod.catatan,   	sod.jml,   	sod.satuan ,   	sod.diskon,   	sod.jmldiskon,  	sod.harga ,   	((sod.jml * sod.harga) - sod.jmldiskon) AS total ,   usr.unama ,     user1.unama as poinputuser ,   so.soinputtgl ,   user2.unama AS pomodifikasiuser ,   so.somodifikasitgl	 FROM m5_so so   JOIN m1_contact kc ON so.socustomer = kc.kid   JOIN m1_contact ks ON so.sobagianpenjualan = ks.kid  JOIN m0_status st ON so.sostatus = st.kode    JOIN m5_so_detail sod on so.soid = sod.idso   JOIN m1_item b ON sod.idbarang = b.bid   LEFT JOIN m5_sq_detail sqd ON sod.idsqdetail = sqd.idsqdetail  LEFT JOIN m5_sq sq ON sqd.idsq = sq.sqid     JOIN m0_user usr ON so.soinputuser = usr.userid  LEFT JOIN m0_user user1 on so.soinputuser = user1.userid  LEFT JOIN m0_user user2 on so.somodifikasiuser = user2.userid   ORDER BY so.sotgl , so.soid , so.sonotransaksi , sod.urutan;

-- RID=1694 | MENU=4 | ITEM=18 | RQUERY=1 | NAME=Order Penjualan (SO) Valas 1/2 Letter | FILE=salesorderdetail_valas1
SELECT    	so.soid,   	so.sonotransaksi ,   	so.sotgl ,   	kc.knama AS socustomer ,   	kc.k1alamat1 ,   	ks.knama AS sobagianpenjualan ,   	st.nama AS sostatus ,   	so.somatauang ,   	so.sotermin,  	so.sokurs ,   	so.souraian ,   	so.sodiskonpersen ,   	so.sojmldiskon ,   	so.sobiayalain ,   	so.sototalpajak1detail ,     	b.bkode ,   	sod.namabarang ,   	sq.sqnotransaksi ,   	sod.catatan,   	sod.jml,   	sod.jmldiskon,   	sod.satuan ,   	sod.diskon,   	sod.harga ,   	(sod.harga * sod.kurs) AS hargavalas ,   	((sod.jml * sod.harga) - sod.jmldiskon) AS total ,   	((sod.jml * (sod.harga * sod.harga)) - (sod.jmldiskon * sod.harga)) AS totalvalas,   usr.unama FROM m5_so so   JOIN m1_contact kc ON so.socustomer = kc.kid   JOIN m1_contact ks ON so.sobagianpenjualan = ks.kid  JOIN m0_status st ON so.sostatus = st.kode    JOIN m5_so_detail sod on so.soid = sod.idso   JOIN m1_item b ON sod.idbarang = b.bid   LEFT JOIN m5_sq_detail sqd ON sod.idsqdetail = sqd.idsqdetail  LEFT JOIN m5_sq sq ON sqd.idsq = sq.sqid     JOIN m0_user usr ON so.soinputuser = usr.userid ORDER BY so.sotgl , so.soid , so.sonotransaksi , sod.urutan;

-- RID=1699 | MENU=4 | ITEM=19 | RQUERY=1 | NAME=Order Penjualan (SO) Valas 1 Letter | FILE=salesorderdetail_valas2
SELECT    	so.soid,   	so.sonotransaksi ,   	so.sotgl ,   	kc.knama AS socustomer ,   	kc.k1alamat1 ,   	ks.knama AS sobagianpenjualan ,   	st.nama AS sostatus ,   	so.somatauang ,   	so.sotermin,  	so.sokurs ,   	so.souraian ,   	so.sodiskonpersen ,   	so.sojmldiskon ,   	so.sobiayalain ,   	so.sototalpajak1detail ,     	b.bkode ,   	sod.namabarang ,   	sq.sqnotransaksi ,   	sod.catatan,   	sod.jml,   	sod.jmldiskon,   	sod.satuan ,   	sod.diskon,   	sod.harga ,   	(sod.harga * sod.kurs) AS hargavalas ,   	((sod.jml * sod.harga) - sod.jmldiskon) AS total ,   	((sod.jml * (sod.harga * sod.harga)) - (sod.jmldiskon * sod.harga)) AS totalvalas,   usr.unama FROM m5_so so   JOIN m1_contact kc ON so.socustomer = kc.kid   JOIN m1_contact ks ON so.sobagianpenjualan = ks.kid  JOIN m0_status st ON so.sostatus = st.kode    JOIN m5_so_detail sod on so.soid = sod.idso   JOIN m1_item b ON sod.idbarang = b.bid   LEFT JOIN m5_sq_detail sqd ON sod.idsqdetail = sqd.idsqdetail  LEFT JOIN m5_sq sq ON sqd.idsq = sq.sqid     JOIN m0_user usr ON so.soinputuser = usr.userid ORDER BY so.sotgl , so.soid , so.sonotransaksi , sod.urutan;

-- RID=1700 | MENU=4 | ITEM=20 | RQUERY=1 | NAME=Order Penjualan (SO) Per Lokasi 1/2 Letter | FILE=salesorderdetail5
SELECT    LEFT(blg.blgnamalokasi,3) as grup ,   blg.blgnamalokasi ,     	so.soid,   	so.sonotransaksi ,   	so.sotgl ,   	kc.knama AS socustomer ,   	kc.k1alamat1 ,   	ks.knama AS sobagianpenjualan ,   	st.nama AS sostatus ,   	so.somatauang ,   	so.sotermin,  	so.sokurs ,   	so.souraian ,   	so.sodiskonpersen ,   	so.sojmldiskon ,   	so.sobiayalain ,   	so.sototalpajak1detail ,     	b.bkode ,   	sod.namabarang ,   	sq.sqnotransaksi ,   	sod.catatan,   	sod.jml,   	sod.jmldiskon,   	sod.satuan ,   	sod.diskon,   	sod.harga ,   	((sod.jml * sod.harga) - sod.jmldiskon) AS total ,   usr.unama FROM m5_so so   JOIN m1_contact kc ON so.socustomer = kc.kid   JOIN m1_contact ks ON so.sobagianpenjualan = ks.kid  JOIN m0_status st ON so.sostatus = st.kode    JOIN m5_so_detail sod on so.soid = sod.idso   JOIN m1_item b ON sod.idbarang = b.bid   LEFT JOIN m5_sq_detail sqd ON sod.idsqdetail = sqd.idsqdetail  LEFT JOIN m5_sq sq ON sqd.idsq = sq.sqid     JOIN m0_user usr ON so.soinputuser = usr.userid    LEFT JOIN m1_item_location_warehouse blg ON (so.sogudang = blg.blggudang AND sod.idbarang = blg.blgidbarang) ORDER BY so.sotgl , so.soid , so.sonotransaksi , LEFT(blg.blgnamalokasi,3) , sod.urutan;

