-- RID=50000571 | MENU=4 | ITEM=22 | RQUERY=1 | NAME=Struk Order Pembelian (SO) | FILE=struk_so
SELECT    so.sotgl ,   k.knama AS sobagianpenjualan ,   so.sototaltransaksi ,   kc.knama AS socustomer ,     so.sonotransaksi      FROM m5_so so  LEFT JOIN m1_contact k ON so.sobagianpenjualan = k.kid  LEFT JOIN m1_contact kc ON so.socustomer = kc.kid ORDER BY so.sotgl ASC , so.soid ASC;

