SELECT  	so.sototaltransaksi ,   	ks.k1alamat1 AS alamatsales ,   	so.sotglkirim ,   so.sotermin ,   	f_nominal(so.sototaltransaksi, so.somatauang) as terbilang,     	so.sohargatermasukpajak ,   	CASE so.sohargatermasukpajak  	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS "caption" ,     	so.soid,   	so.sonotransaksi ,   	so.sotgl ,   	kc.knama AS socustomer ,   	kc.k1alamat1 ,   	ks.knama AS sobagianpenjualan ,   	st.nama AS sostatus ,   	so.somatauang ,   	so.sokurs ,   	so.souraian ,   	so.sodiskonpersen ,   	so.sojmldiskon ,   	so.sobiayalain ,   	so.sototalpajak1detail ,     	b.bkode ,   	sod.namabarang ,   	sq.sqnotransaksi ,   	sod.catatan,   	sod.jml,   	sod.satuan ,   	sod.diskon,   	sod.harga ,   	((sod.jml * sod.harga) - sod.jmldiskon) AS total ,   usr.unama FROM m5_so so   JOIN m1_contact kc ON so.socustomer = kc.kid   JOIN m1_contact ks ON so.sobagianpenjualan = ks.kid  JOIN m0_status st ON so.sostatus = st.kode    JOIN m5_so_detail sod on so.soid = sod.idso   JOIN m1_item b ON sod.idbarang = b.bid   LEFT JOIN m5_sq_detail sqd ON sod.idsqdetail = sqd.idsqdetail  LEFT JOIN m5_sq sq ON sqd.idsq = sq.sqid     JOIN m0_user usr ON so.soinputuser = usr.userid ORDER BY so.sotgl , so.soid , so.sonotransaksi , sod.urutan;

-- RID=50001762 | MENU=4 | ITEM=24 | RQUERY=1 | NAME=SALES ORDER (PO) | FILE=salesorderdetail1_PCI
SELECT    k.knama AS socustomer ,   so.so1alamat1 ,   so.sotgl , so.sonotransaksi ,   so.souraian ,   so.sotermin,   b.bkode ,   b.bnama AS namabarang ,   sod.jml ,   sod.satuan ,   sod.harga ,   sod.diskon ,   ((sod.jml * sod.harga) - sod.jmldiskon ) AS total ,   so.sototaltransaksi,   f_nominal(so.sototaltransaksi, so.somatauang) AS terbilang ,   so.sotglkirim ,   so.sonoref,  k.kcatatan FROM m5_so so   JOIN m5_so_detail sod ON so.soid = sod.idso   JOIN m1_contact k ON so.socustomer = k.kid  JOIN m1_item b ON sod.idbarang = b.bid  LEFT JOIN m1_contact ks ON so.sobagianpenjualan = ks.kid ORDER BY so.sotgl ASC , so.soid ASC , sod.urutan ASC;

-- RID=50001771 | MENU=4 | ITEM=25 | RQUERY=1 | NAME=PROFORMA INVOICE | FILE=SC_PCI
SELECT  	so.soid,  	so.sonotransaksi ,   	so.sotgl ,   	so.socustomtext1 as vessel,  	so.socustomtext2 as originport,  	so.socustomtext3 as destinationport,  	so.socustomtext4 as bundleno,  	so.socustomtext5 as marking,  	so.socustomdbl2 as freight,  	so.socustomdbl3 as insurance,  	so.souraian,   	k.knama AS socustomer ,   	so.so1alamat1 ,   	so.so2alamat1 ,   	so.souraian as uraian,	  	so.socustomdate1 as etd,  	k.k1notelp1 as telp,  	k.k1nofax as fax,   	b.bkode ,  	sod.namabarang ,   	sod.jml ,   	sod.harga ,   	sod.jml * sod.harga AS total,   	sod.customdbl4 as jmlbundle,  	sod.customtext4 as satuanbundle,  	sod.customdbl5 as grossweight,  	sod.customtext5 as measurement,  	  	sod.matauang ,     	so.somatauang ,   	so.sototalpajak1detail ,   	so.sobiayalain ,  	so.sojmldiskon ,   	so.sototaltransaksi ,   	so.socatatan as catatan ,   	sf.sfnotransaksi, cr.csimbol,  	f_nominal_english(sototaltransaksi, somatauang) AS terbilang,  	case so.socustomint1  		when 0 then "SEA"  		when 1 then "AIR"  	END as shipmentby,  	so.sonoref,  	so.socustomerkontak,  	sod.catatan as catatandetail,  	k.kcatatan as catatanmaster  	 FROM m5_so so   JOIN m5_so_detail sod ON so.soid = sod.idso   JOIN m1_contact k ON so.socustomer = k.kid   JOIN m1_item b ON sod.idbarang = b.bid   LEFT JOIN m5_sf sf on so.socustomdbl1 = sf.sfid  left join m1_currency cr on so.somatauang = cr.ckode ORDER BY so.sotgl ASC, so.soid ASC, sod.urutan ASC;

-- RID=50001772 | MENU=4 | ITEM=26 | RQUERY=1 | NAME=PROFORMA INVOICE | FILE=PROFORMA INVOICE
SELECT    so.soid ,   so.sonotransaksi ,   so.sotgl ,   k.knama AS socustomer ,   k.k1alamat1 ,     b.bkode ,   b.bnama AS namabarang ,   sod.jml ,   sod.satuan ,   sod.harga ,   sod.diskon ,   sod.jmldiskon ,   (sod.jml * sod.harga) - sod.jmldiskon AS total ,     so.socatatan ,     f_nominal(so.sototaltransaksi, so.somatauang) AS terbilang FROM m5_so so   JOIN m5_so_detail sod ON so.soid = sod.idso   JOIN m1_item b ON sod.idbarang = b.bid   JOIN m1_contact k ON so.socustomer = k.kid ORDER BY so.sotgl ASC, so.soid ASC, sod.urutan ASC;

-- RID=50001779 | MENU=4 | ITEM=45 | RQUERY=1 | NAME=Back Order | FILE=backorder
SELECT    so.soid ,   so.sonotransaksi ,  so.sonoref,   so.sotgl ,   kc.knama AS socustomer ,   ks.knama AS sobagianpenjualan ,   so.souraian ,     b.bkode ,   sod.namabarang ,   sod.catatan ,   sod.jml ,   sod.satuan,   (sod.jmlrealisasi / sod.nilaisatuan) AS jmlrealisasi ,   (sod.jml - (sod.jmlrealisasi / sod.nilaisatuan)) AS jmlsisa,  sod.harga as harga,   (sod.jml - (sod.jmlrealisasi / sod.nilaisatuan))  * sod.harga as total FROM m5_so so   JOIN m5_so_detail sod on so.soid = sod.idso   JOIN m1_item b ON sod.idbarang = b.bid     LEFT JOIN m1_contact kc ON so.socustomer = kc.kid   LEFT JOIN m1_contact ks ON so.sobagianpenjualan = ks.kid WHERE so.sostatus in(2,3) AND sod.jml > sod.jmlrealisasi ORDER BY so.sotgl , so.soid , so.sonotransaksi , sod.urutan;

-- RID=50003769 | MENU=4 | ITEM=46 | RQUERY=1 | NAME=Laporan Gudang FG per SO | FILE=FG_SO
SELECT    kc.kkode AS kodecustomer,   kc.knama AS namacustomer,   ks.kkode AS kodesalesman,   ks.knama AS namasalesman,     so.sonotransaksi ,     b.bkode ,   sod.jml ,   sum(nbi.nbijmlmasuk * 1) AS stock ,   (sod.jml - (nbi.nbijmlmasuk  * 1))  AS balance FROM m5_so so     JOIN m1_contact kc ON so.socustomer = kc.kid  JOIN m1_contact ks ON so.sobagianpenjualan = ks.kid     JOIN m5_so_detail sod ON so.soid = sod.idso   JOIN m1_item b ON sod.idbarang = b.bid     LEFT JOIN m1_no_batch_in nbi ON sod.idbarang = nbi.nbiidbarang and so.sonotransaksi = nbi.nbikode GROUP BY idbarang,sonotransaksi ORDER BY kc.knama ASC , so.sonotransaksi ASC , sod.urutan ASC;

-- RID=50003772 | MENU=4 | ITEM=47 | RQUERY=1 | NAME=Sales Backorder Report | FILE=so_backorder
SELECT so.soid, 	   c.kkode as socustomerkode, 	   c.knama as socustomernama, 	   c.kcatatan, 	   c2.kkode as sobagianpenjualankode, 	   c2.knama as sobagianpenjualannama, 	   so.sotgl, 	   so.sonotransaksi, 	 so.sotglkirim, 	   so.sonoref, 	 i.bkode, 	 i.bnama, 	   i.bsatuan, 	   SUM(sod.jmlbarang) as jmlbarang, 	   SUM(sod.jmlrealisasi) as jmlrealisasi, 	  (CASE WHEN ROUND(SUM(sod.jmlbarang - sod.jmlrealisasi),5) > 0  THEN ROUND(SUM(sod.jmlbarang - sod.jmlrealisasi),5)   ELSE 0 END) as jmloutstanding, 	   (IFNULL(nbi.nbijmlsisa,0)) as stok,   	(IFNULL(nbi.nbicustomdbl1 - nbi.nbicustomdbl2,0)) as jmlbatang, 	   pdp.tglawal AS tglawal,   pdp.tglakhir AS tglakhir,  sf.sfnotransaksi, bdivisi,  bsubkelas as kelompokpd FROM m5_so so JOIN m5_so_detail sod ON so.soid = sod.idso AND so.sostatus IN(2,3)      JOIN m1_item i ON sod.idbarang = i.bid   JOIN m1_contact c ON so.socustomer = c.kid   JOIN m1_contact c2 ON so.sobagianpenjualan = c2.kid   LEFT JOIN (SELECT nbigudang, nbiidbatchin, nbiidbarang, nbikode, SUM(nbijmlsisa) as nbijmlsisa,  SUM(nbicustomdbl1) as nbicustomdbl1,     SUM(nbicustomdbl2) as nbicustomdbl2 	FROM m1_no_batch_in where nbigudang in ("FG", "FGBW") GROUP BY nbiidbarang, nbikode)  as nbi ON sod.idbarang = nbi.nbiidbarang   AND so.sonotransaksi = nbi.nbikode    LEFT JOIN  (SELECT MIN(tgl) AS tglawal, MAX(tgl) AS tglakhir, m6_pdp_detail.* from m6_pdp_detail GROUP BY idsodetail ORDER BY tgl ASC) as pdp ON pdp.idsodetail = so.soid   left join m5_sf sf on so.socustomdbl1 = sf.sfid GROUP BY c.kkode, so.sotgl, so.soid, i.bkode HAVING (jmloutstanding > 0 OR stok > 0);

-- RID=50003773 | MENU=4 | ITEM=48 | RQUERY=1 | NAME=Warehouse Backorder Report | FILE=so_whbackorder
SELECT  c.kkode as socustomerkode,  c.knama as socustomernama,  c2.kkode as sobagianpenjualankode,  c2.knama as sobagianpenjualannama,  so.sotgl,  so.sonotransaksi,  so.sotglkirim,  i.bkode,  i.bnama,  i.bsatuan,  SUM(sod.jmlbarang) as jmlbarang,  SUM(sod.jmlrealisasi) as jmlrealisasi,  ROUND(SUM(sod.jmlbarang - sod.jmlrealisasi),5) as jmloutstanding,  (IFNULL(nbi.nbijmlsisa,0)) as stok FROM m5_so so  JOIN m5_so_detail sod ON so.soid = sod.idso AND so.sostatus IN(2,3) AND sod.jmlrealisasi < sod.jmlbarang  JOIN m1_item i ON sod.idbarang = i.bid  JOIN m1_contact c ON so.socustomer = c.kid  JOIN m1_contact c2 ON so.sobagianpenjualan = c2.kid  LEFT JOIN (SELECT nbiidbatchin, nbiidbarang, nbikode, SUM(nbijmlsisa) as nbijmlsisa   FROM m1_no_batch_in GROUP BY nbiidbarang, nbikode)   as nbi ON sod.idbarang = nbi.nbiidbarang AND so.sonotransaksi = nbi.nbikode   GROUP BY i.bkode, c.kkode, so.sotgl, so.soid ORDER BY i.bkode, c.kkode, so.sotgl, so.soid;

-- RID=50003775 | MENU=4 | ITEM=50 | RQUERY=1 | NAME=SO Delivery Report | FILE=so delivery report
SELECT    so.sonotransaksi ,   so.sotgl ,   so.sotglkirim ,   kc.knama AS namacustomer ,   ks.knama AS namasalesman ,   si.sinoref ,   b.bkode ,   b.bnama,   sod.jml AS jmlso ,  sod.satuan AS satuanso,   sid.idsodetail,   si.sinotransaksi ,   si.sitgl,   case WHEN si.sistatus in(2,3,4,7) then sid.jml else 0 end AS jmlsi,  sid.satuan AS satuansi FROM m5_so so   JOIN m5_so_detail sod ON so.soid = sod.idso AND so.sostatus  IN(2,3,4,7)  JOIN m1_contact kc ON so.socustomer = kc.kid   JOIN m1_contact ks ON so.sobagianpenjualan = ks.kid   JOIN m1_item b ON sod.idbarang = b.bid      JOIN m5_si_detail sid ON sod.idsodetail = sid.idsodetail   JOIN m5_si si ON sid.idsi = si.siid AND si.sistatus  IN(2,3,4,7) ORDER BY so.sotgl ASC , so.sonotransaksi ASC , sod.urutan  ASC , b.bkode ASC , si.sitgl ASC , si.sinotransaksi ASC , sid.urutan ASC;

-- RID=50003776 | MENU=4 | ITEM=51 | RQUERY=1 | NAME=SO Approved Report | FILE=so approved
SELECT    so.sonotransaksi ,   so.sotgl ,   so.sotglkirim ,   kc.knama AS namacustomer ,   ks.knama AS namasalesman ,   b.bkode ,   b.bnama,   sod.jml AS jmlso ,  sod.satuan AS satuanso,  kc.kcatatan as catatan     FROM m5_so so   JOIN m5_so_detail sod ON so.soid = sod.idso  JOIN m1_contact kc ON so.socustomer = kc.kid   JOIN m1_contact ks ON so.sobagianpenjualan = ks.kid   JOIN m1_item b ON sod.idbarang = b.bid WHERE so.sostatus = 2 ORDER BY so.sonotransaksi asc;

-- RID=50003778 | MENU=4 | ITEM=53 | RQUERY=1 | NAME=FG Stock Report by Customer | FILE=StockBackorderReportGlobal
SELECT   fg.bdivisi,  fg.kodecustomer, fg.namacustomer, fg.kodesalesman, fg.namasalesman, fg.wnama, fg.bkode, fg.bnama,    SUM(fg.st) AS stok,  fg.bhppaverage,  SUM(fg.amt) AS amount  FROM (  SELECT  'FG' as bdivisi ,  c.kkode AS kodecustomer ,  c.knama AS namacustomer ,  c2.kkode as kodesalesman ,  c2.knama AS  namasalesman,    'FG' as wnama ,  i.bkode ,  i.bnama ,    ((IFNULL(nbi.nbijmlsisa,0))) AS st ,    (i.bhppaverage) AS bhppaverage ,   ((IFNULL(nbi.nbijmlsisa,0)) * i.bhppaverage) AS amt     FROM m5_so so   JOIN m5_so_detail sod ON so.soid = sod.idso AND so.sostatus IN(2,3) AND sod.jmlrealisasi < sod.jmlbarang   JOIN m1_item i ON sod.idbarang = i.bid   JOIN m1_contact c ON so.socustomer = c.kid   JOIN m1_contact c2 ON so.sobagianpenjualan = c2.kid   LEFT JOIN (SELECT nbigudang, nbiidbatchin, nbiidbarang, nbikode, SUM(nbijmlsisa) as nbijmlsisa    FROM m1_no_batch_in GROUP BY nbiidbarang, nbikode)  as nbi ON sod.idbarang = nbi.nbiidbarang AND so.sonotransaksi = nbi.nbikode      GROUP BY c.kkode, so.sotgl, so.soid, i.bkode   ORDER BY c.kkode, so.sotgl, so.soid, i.bkode  ) as fg  GROUP BY fg.kodecustomer ASC  HAVING stok <> 0  ORDER BY fg.kodecustomer ASC;

-- RID=50003782 | MENU=4 | ITEM=54 | RQUERY=1 | NAME=Sales Backorder Report Summary | FILE=so_backorder_global
SELECT  c.kkode as socustomerkode,  c.knama as socustomernama,  c2.kkode as sobagianpenjualankode,  c2.knama as sobagianpenjualannama,  so.sotgl,  so.sonotransaksi,  so.sotglkirim,  i.bkode,  i.bnama,  i.bsatuan,  SUM(sod.jmlbarang) as jmlbarang,  SUM(sod.jmlrealisasi) as jmlrealisasi,  ROUND(SUM(sod.jmlbarang - sod.jmlrealisasi),5) as jmloutstanding,  ROUND(SUM((IFNULL(nbi.nbijmlsisa,0))),5) as stok FROM m5_so so  JOIN m5_so_detail sod ON so.soid = sod.idso AND so.sostatus IN(2,3) AND sod.jmlrealisasi < sod.jmlbarang  JOIN m1_item i ON sod.idbarang = i.bid  JOIN m1_contact c ON so.socustomer = c.kid  JOIN m1_contact c2 ON so.sobagianpenjualan = c2.kid  LEFT JOIN (SELECT nbigudang, nbiidbatchin, nbiidbarang, nbikode, SUM(nbijmlsisa) as nbijmlsisa   FROM m1_no_batch_in GROUP BY nbiidbarang, nbikode)   as nbi ON sod.idbarang = nbi.nbiidbarang AND so.sonotransaksi = nbi.nbikode GROUP BY c.kkode ORDER BY c.kkode, so.sotgl, so.soid, i.bkode;

-- RID=50003794 | MENU=4 | ITEM=55 | RQUERY=1 | NAME=Biaya Salesman | FILE=Laporan Biaya Salesman
SELECT    ks.kkode ,   ks.knama ,   si.sinotransaksi ,   si.sitgl ,   si.sitotaltransaksi ,   soc.jumlah ,   soc.customdbl2 FROM m5_si_cost soc   JOIN m1_contact ks ON soc.kontak = ks.kid   JOIN m5_si si ON soc.idsi = si.siid WHERE sistatus in(2,3,4,7) ORDER BY soc.kontak ASC , si.sitgl ASC , si.sinotransaksi ASC;

-- RID=50003795 | MENU=4 | ITEM=56 | RQUERY=1 | NAME=Production Backorder Report | FILE=pd_backorder
SELECT  c.kkode as socustomerkode,  c.kcatatan,  c.knama as socustomernama,  c2.kkode as sobagianpenjualankode,  c2.knama as sobagianpenjualannama,  so.sotgl,  so.sonotransaksi,  sf.sfnotransaksi as nopi,  so.sotglkirim,  so.sonoref,  so.souraian,  i.bkode,  i.bnama,  i.bkelasproduk,  i.bsatuan,  SUM(sod.jmlbarang) as jmlbarang,  (IFNULL(nbi.nbijmlpd,0)) - (IFNULL(nbo.nbojmlpd,0)) as jmlpd,  ROUND(SUM(sod.jmlbarang) - ((IFNULL(nbi.nbijmlpd,0)) - (IFNULL(nbo.nbojmlpd,0))),5) as jmloutstandingpd,  sod.customdate3 as tglplanpd,  (IFNULL(nbi.nbijmlsisa,0)) as stok,  sod.customdbl3,  i.bmaterial,  m.mnama as bmaterialnama,  b2.bstok as bmaterialstok,  b2.bjmlorderbeli as bmaterialonorder,  i.bjmllapangan as kgpcs,  sod.jmlbarang / i.bjmllapangan as jmlpcs FROM m5_so so   JOIN m5_so_detail sod ON so.soid = sod.idso AND so.sostatus IN(2,3)  AND sod.jmlrealisasi < sod.jmlbarang   AND so.sogudang NOT IN ('SP', 'SPHPK', 'RM', 'RMHPK', 'RMBW')  JOIN m1_item i ON sod.idbarang = i.bid   JOIN m1_contact c ON so.socustomer = c.kid   JOIN m1_contact c2 ON so.sobagianpenjualan = c2.kid   LEFT JOIN m1_material m ON i.bmaterial = m.mkode  LEFT JOIN m1_item b2 ON i.bmaterial = b2.bkode  LEFT JOIN (SELECT nbigudang, nbiidbatchin, nbiidbarang, nbikode, SUM(nbijmlsisa) as nbijmlsisa,   SUM(nbijmlmasuk) as nbijmlpd    FROM m1_no_batch_in WHERE nbisumber NOT IN("DO", "TS") GROUP BY nbiidbarang, nbikode)  as nbi ON sod.idbarang = nbi.nbiidbarang AND so.sonotransaksi = nbi.nbikode   LEFT JOIN (SELECT nbogudang, nboidbatchin, nboidbarang, nbokode, SUM(nbojmlkeluar) as nbojmlpd      FROM m1_no_batch_out where nbosumber IN("SA") AND nboidbatchin <> 0   GROUP BY nboidbarang, nbokode)  as nbo ON sod.idbarang = nbo.nboidbarang AND so.sonotransaksi = nbo.nbokode    LEFT JOIN m5_sf sf on so.socustomdbl1 = sf.sfid GROUP BY c.kkode, so.sotgl, so.soid, i.bkode;

-- RID=50003796 | MENU=4 | ITEM=57 | RQUERY=1 | NAME=Sales Order with Production and Delivery Report | FILE=so_pd_delivery
SELECT  c.kkode as socustomerkode,  c.knama as socustomernama,  c2.kkode as sobagianpenjualankode,  c2.knama as sobagianpenjualannama,  so.sotgl,  so.sonotransaksi,  so.sotglkirim,  so.sonoref,  i.bkode,  i.bnama,  i.bsatuan,  SUM(sod.jmlbarang) as jmlbarang,  SUM(sod.jmlrealisasi) as jmlrealisasi,  ROUND(SUM(sod.jmlbarang - sod.jmlrealisasi),5) as jmloutstanding,  (IFNULL(nbi.nbijmlpd,0)) - (IFNULL(nbo.nbojmlpd,0)) as jmlpd,  ROUND(SUM(sod.jmlbarang) - ((IFNULL(nbi.nbijmlpd,0)) - (IFNULL(nbo.nbojmlpd,0))),5) as jmloutstandingpd,  sod.customdate3 as tglplanpd,  (IFNULL(nbi.nbijmlsisa,0)) as stok FROM m5_so so  JOIN m5_so_detail sod ON so.soid = sod.idso AND so.sostatus IN(2,3)   JOIN m1_item i ON sod.idbarang = i.bid  JOIN m1_contact c ON so.socustomer = c.kid  JOIN m1_contact c2 ON so.sobagianpenjualan = c2.kid  LEFT JOIN (SELECT nbigudang, nbiidbatchin, nbiidbarang, nbikode, SUM(nbijmlsisa) as nbijmlsisa, SUM(nbijmlmasuk) as nbijmlpd   FROM m1_no_batch_in GROUP BY nbiidbarang, nbikode)   as nbi ON sod.idbarang = nbi.nbiidbarang AND so.sonotransaksi = nbi.nbikode  LEFT JOIN (SELECT nbogudang, nboidbatchin, nboidbarang, nbokode, SUM(nbojmlkeluar) as nbojmlpd   FROM m1_no_batch_out where nbosumber = "SA" AND nboidbatchin <> 0 GROUP BY nboidbarang, nbokode)   as nbo ON sod.idbarang = nbo.nboidbarang AND so.sonotransaksi = nbo.nbokode GROUP BY c.kkode, so.sotgl, so.soid, i.bkode ORDER BY c.kkode, so.sotgl, so.soid, i.bkode;

-- RID=50003801 | MENU=4 | ITEM=58 | RQUERY=1 | NAME=PACKING AND WEIGHT LIST | FILE=Draft_PL_PCI
SELECT  	so.soid,  	so.sonotransaksi ,   	so.sotgl ,   	so.socustomtext1 as vessel,  	so.socustomtext2 as originport,  	so.socustomtext3 as destinationport,  	so.socustomtext4 as bundleno,  	so.socustomtext5 as marking,  	so.socustomdbl2 as freight,  	so.socustomdbl3 as insurance,  	so.souraian,   	k.knama AS socustomer ,   	so.so1alamat1 ,   	so.so2alamat1 ,   	so.socatatan ,   	so.socustomdate1 as etd,  	k.k1notelp1 as telp,  	k.k1nofax as fax,    	sod.namabarang as bnama ,   	sod.jml ,   	sod.harga ,   	sod.jml * sod.harga AS total,   	sod.customdbl4 as jmlbundle,  	sod.customtext4 as satuanbundle,  	sod.customdbl5 as grossweight,  	sod.customtext5 as measurement,  	  	sod.matauang ,     	so.somatauang ,   	so.sototalpajak1detail ,   	so.sobiayalain ,   	so.sototaltransaksi ,   	so.so1alamat2 as catatan ,   	sf.sfnotransaksi,  	so.soekspedisi as unit FROM m5_so so   JOIN m5_so_detail sod ON so.soid = sod.idso   JOIN m1_contact k ON so.socustomer = k.kid   JOIN m1_item b ON sod.idbarang = b.bid   LEFT JOIN m5_sf sf on so.socustomdbl1 = sf.sfid   ORDER BY so.sotgl ASC , so.soid ASC , sod.urutan ASC;

-- RID=50001764 | MENU=4 | ITEM=59 | RQUERY=1 | NAME=COMMERCIAL INVOICE | FILE=SO_CI_PCI
SELECT  	so.soid,  	so.sonotransaksi ,   	so.sotgl ,   	so.socustomtext1 as vessel,  	so.socustomtext2 as originport,  	so.socustomtext3 as destinationport,  	so.socustomtext4 as bundleno,  	so.socustomtext5 as marking,  	so.socustomdbl2 as freight,  	so.socustomdbl3 as insurance,  	so.souraian,   	so.socustomdate1 as etd,  	k.k1notelp1 as telp,  	k.k1nofax as fax,    	k.knama AS socustomer ,   	so.so1alamat1 ,   	so.so2alamat1 ,   	so.souraian as uraian,   	so.socustomdate1 as etd,  	k.k1notelp1 as telp,  	k.k1nofax as fax,    	sod.namabarang as bnama ,   	sod.jml ,   	sod.harga ,   	sod.jml * sod.harga AS total,   	sod.customdbl4 as jmlbundle,  	sod.customtext4 as satuanbundle,  	sod.customdbl5 as grossweight,  	sod.customtext5 as measurement,  	sod.catatan as catatandetail,  	sod.matauang ,     	so.somatauang ,   	so.sototalpajak1detail ,   	so.sobiayalain ,  	so.sojmldiskon ,   	so.sototaltransaksi ,   	so.so1alamat2 as catatan ,   	sf.sfnotransaksi, cr.csimbol,  	f_nominal_english(sototaltransaksi, somatauang) AS terbilang,    k.kcatatan,    so.soekspedisi as unit FROM m5_so so   JOIN m5_so_detail sod ON so.soid = sod.idso   JOIN m1_contact k ON so.socustomer = k.kid   JOIN m1_item b ON sod.idbarang = b.bid   LEFT JOIN m5_sf sf on so.socustomdbl1 = sf.sfid  left join m1_currency cr on so.somatauang = cr.ckode   WHERE bjenis = "P" ORDER BY so.sotgl ASC , so.soid ASC , sod.urutan ASC;

-- RID=50003822 | MENU=4 | ITEM=60 | RQUERY=2 | NAME=Index Delivery Sales Order | FILE=indexso
SELECT so.* FROM m2r_index_so so WHERE kkode <> 'CI.M002' AND bkode NOT LIKE '%MAKLON%' ORDER BY so.sotglkirim, so.sonotransaksi, so.soid, so.bkode;

-- RID=50003824 | MENU=4 | ITEM=61 | RQUERY=1 | NAME=Rencana Profit Report | FILE=order_incoming
SELECT  so.sotgl as SODATE,  GROUP_CONCAT(DISTINCT i.bdivisi ORDER BY i.bdivisi ASC) as SOITEM,  so.sonotransaksi as SONUMBER,  c.knama as SOCUSTOMER,  SUM(sod.jml) as SOQTY,  CASE so.sohargatermasukpajak WHEN 1 THEN so.sototal - so.sototalpajak1detail ELSE so.sototal END as SOAMOUNT,  so.sojenispenjualankategori as SOPROSENTASE,  so.soasalbarangkategori as  SOKURSCOSTING,  ((CASE so.sohargatermasukpajak WHEN 1 THEN so.sototal - so.sototalpajak1detail ELSE so.sototal END) / 100) * so.sojenispenjualankategori as SOPROFIT,  so.sojenispenjualankategori as proyeksiprofit   FROM m5_so so  JOIN m1_contact c ON so.socustomer = c.kid  JOIN m5_so_detail sod ON so.soid = sod.idso  JOIN m1_item i ON sod.idbarang = i.bid   GROUP BY so.sotgl, so.sonotransaksi, so.soid ORDER BY so.sotgl, so.sonotransaksi, so.soid;

-- RID=50003825 | MENU=4 | ITEM=62 | RQUERY=2 | NAME=Index Delivery Sales Order (Item) | FILE=indexsoitem
SELECT so.* FROM m2r_index_so so WHERE kkode <> 'CI.M002' AND bkode NOT LIKE '%MAKLON%' ORDER BY so.bkode, so.sotglkirim, so.sonotransaksi, so.soid;

-- RID=94 | MENU=5 | ITEM=1 | RQUERY=1 | NAME=Daftar UM Penjualan (AS) Detail | FILE=listadvancesales
SELECT    	ass.asid,   	ass.asnotransaksi ,   	ass.astgl ,   	CASE ass.asjenis   	WHEN 0 then "UM Pembelian"  	WHEN 1 then "Titipan(Deposit)"  END AS asjenis ,   kc.knama AS askontak ,   ass.asnorek ,   c.cnama ,   so.sonotransaksi ,   ip.ipnotransaksi,   ass.asmatauang ,   ass.askurs ,   st.nama AS asstatus ,   pm.nama AS carabayar ,  CASE carabayar   	WHEN 2 then asp.rekgiro  ELSE asp.rekbank  END AS noakun,   CASE carabayar   	WHEN 2 THEN c3.cnama  ELSE c2.cnama   END AS namaakun,   asp.jumlah ,   asp.jumlahvalas ,   asp.bank ,   asp.nogiro,   asp.tgljt ,   asp.noacbank FROM m5_as ass  JOIN m1_contact kc ON ass.askontak = kc.kid  JOIN m1_coa c ON ass.asnorek = c.cnomor  JOIN m0_status st ON ass.asstatus = st.kode    JOIN m5_as_pay asp ON ass.asid = asp.idas   JOIN m0_payment_method pm ON asp.carabayar = pm.kode  LEFT JOIN m5_so so ON ass.asidso = so.soid  LEFT JOIN m5_ip ip ON ass.asidip = ip.ipid  LEFT JOIN m1_coa c2 ON asp.rekbank = c2.cnomor   LEFT JOIN m1_coa c3 ON asp.rekgiro = c3.cnomor ORDER BY ass.astgl ,  ass.asid , ass.asnotransaksi , asp.urutan;

-- RID=95 | MENU=5 | ITEM=2 | RQUERY=1 | NAME=Daftar UM Penjualan (AS) Outstanding Pembayaran | FILE=listadvancesalespaymentoutstanding
SELECT  	m5as.asnotransaksi,  	m5as.astgl,  	m5as.asmatauang,  	m5as.astgljatuhtempo,  	m5as.asjumlahbayar,  	k.knama,  	asp.kurs AS kursas,  	asp.jumlah AS kredit,  	pvd.jmlbayar,  	pvd.kurs,  	pvd.jmlbayarvalas,  	pv.pvnotransaksi,  	pv.pvmatauang,  	pv.pvtgl,  	pv.pvcatatan,  	pvd.sumber  	 FROM m5_as m5as  JOIN m5_as_pay asp ON m5as.asid = asp.idas  JOIN m1_contact k ON m5as.askontak = k.kid  left JOIN m5_pv_detail pvd ON m5as.asid = pvd.idtransaksi  LEFT JOIN m5_pv pv ON pvd.idpv = pv.pvid     WHERE (pvd.sumber = "AS" AND pv.pvstatus = 2 OR pv.pvstatus = 3 OR pv.pvstatus = 4 OR pv.pvstatus = 7 AND asp.jumlah > 0) GROUP BY m5as.asnotransaksi, pv.pvnotransaksi ORDER BY m5as.asnotransaksi, pv.pvnotransaksi, pvd.urutan;

-- RID=96 | MENU=5 | ITEM=3 | RQUERY=1 | NAME=UM Penjualan (AS) 1/2 Letter | FILE=advancesalesdetail1_new
