-- RID=444 | MENU=5 | ITEM=5 | RQUERY=1 | NAME=Daftar UM Penjualan | FILE=daftarumpenjualan
SELECT  m5as.asid,  m5as.asnotransaksi,  m5as.astgl,  m5as.askontak,  c1.kkode as askontakkode,  c1.knama as askontaknama,  m5as.astgljatuhtempo,  m5as.asuraian,  m5as.ascatatan,  m5as.asmatauang,  m5as.askurs,  m5as.asjumlah,  m5as.asjumlahvalas,  m5as.asjumlahbayar,  m5as.asjumlahbayarvalas,  m5as.asjumlah - m5as.asjumlahbayar as assisa,  m5as.asjumlahvalas - m5as.asjumlahbayarvalas as assisavalas,  m5as.asstatusbayar,  m5as.astgllunas FROM m5_as m5as  JOIN m1_contact c1 ON m5as.askontak = c1.kid  LEFT JOIN m1_contact c2 ON c1.ksalesman = c2.kid WHERE m5as.asstatus IN(2,3,4,7);

-- RID=445 | MENU=5 | ITEM=6 | RQUERY=1 | NAME=Daftar UM Penjualan (Detail) | FILE=daftarumpenjualandetail
SELECT  m5as.asid,  m5as.asnotransaksi,  m5as.astgl,  m5as.askontak,  c1.kkode as askontakkode,  c1.knama as askontaknama,  m5as.astgljatuhtempo,  m5as.asuraian,  m5as.ascatatan,  m5as.asmatauang,  m5as.askurs,  m5as.asjumlah,  m5as.asjumlahvalas,  m5as.asjumlahbayar,  m5as.asjumlahbayarvalas,  m5as.asjumlah - m5as.asjumlahbayar as assisa,  m5as.asjumlahvalas - m5as.asjumlahbayarvalas as assisavalas,  m5as.asstatusbayar,  m5as.astgllunas,  pv.pvid,  pv.pvnotransaksi,  pv.pvtgl,  pv.pvcustomer,  c3.kkode as pvcustomerkode,  c3.knama as pvcustomernama,  pv.pvuraian,  pv.pvcatatan,  pv.pvmatauang,  pv.pvkurs,  pvd.jmlbayar,  pvd.jmlbayarvalas FROM m5_pv pv  JOIN m5_pv_detail pvd ON pv.pvid = pvd.idpv AND pv.pvstatus IN(2,3,4,7)  RIGHT JOIN m5_as m5as ON pvd.idtransaksi = m5as.asid AND pvd.sumber = m5as.assumber   LEFT JOIN m1_contact c1 ON m5as.askontak = c1.kid  LEFT JOIN m1_contact c2 ON c1.ksalesman = c2.kid  LEFT JOIN m1_contact c3 ON pv.pvcustomer = c3.kid WHERE m5as.asstatus IN(2,3,4,7);

