-- RID=1688 | MENU=5 | ITEM=8 | RQUERY=1 | NAME=Daftar UM Penjualan (AS) Global | FILE=listadvancesales2
SELECT    	ass.asid,   	ass.asnotransaksi ,   	ass.astgl ,   	CASE ass.asjenis   	WHEN 0 then "UM Pembelian"  	WHEN 1 then "Titipan(Deposit)"  END AS asjenis ,   kc.knama AS askontak ,   ass.asnorek ,   c.cnama ,   so.sonotransaksi ,   ip.ipnotransaksi,   ass.asmatauang ,   ass.askurs ,   st.nama AS asstatus ,   pm.nama AS carabayar ,  CASE carabayar   	WHEN 2 then asp.rekgiro  ELSE asp.rekbank  END AS noakun,   CASE carabayar   	WHEN 2 THEN c3.cnama  ELSE c2.cnama   END AS namaakun,   asp.jumlah ,   asp.jumlahvalas ,   asp.bank ,   asp.nogiro,   asp.tgljt ,   asp.noacbank FROM m5_as ass  JOIN m1_contact kc ON ass.askontak = kc.kid  JOIN m1_coa c ON ass.asnorek = c.cnomor  JOIN m0_status st ON ass.asstatus = st.kode    JOIN m5_as_pay asp ON ass.asid = asp.idas   JOIN m0_payment_method pm ON asp.carabayar = pm.kode  LEFT JOIN m5_so so ON ass.asidso = so.soid  LEFT JOIN m5_ip ip ON ass.asidip = ip.ipid  LEFT JOIN m1_coa c2 ON asp.rekbank = c2.cnomor   LEFT JOIN m1_coa c3 ON asp.rekgiro = c3.cnomor ORDER BY ass.astgl ,  ass.asid , ass.asnotransaksi , asp.urutan;

-- RID=97 | MENU=6 | ITEM=1 | RQUERY=1 | NAME=Daftar Packing Barang (PL) Detail | FILE=listpackinglist
SELECT    	pl.plid ,   	pl.plnotransaksi ,   	pl.pltgl,  	kc.knama AS plcustomer ,   	ks.knama AS plbagianpenjualan,   	st.nama AS plstatus ,   	pl.plmatauang ,   	pl.plkurs,     	b.bkode,   	pld.namabarang ,   	so.sonotransaksi ,   	pld.jml ,   	pld.satuan FROM m5_pl pl  JOIN m1_contact kc ON pl.plcustomer = kc.kid  JOIN m1_contact ks ON pl.plbagianpenjualan = ks.kid  JOIN m0_status st ON pl.plstatus = st.kode    JOIN m5_pl_detail pld ON pl.plid = pld.idpl  JOIN m1_item b ON pld.idbarang = b.bid    LEFT JOIN m5_so_detail sod ON pld.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid ORDER BY pl.pltgl , pl.plid, pl.plnotransaksi, pld.urutan;

-- RID=98 | MENU=6 | ITEM=2 | RQUERY=1 | NAME=Packing Barang (PL) Outstanding | FILE=listpackinglistoutstanding
SELECT    	pl.plid ,   	pl.plnotransaksi ,   	pl.pltgl,  	kc.knama AS plcustomer ,   	ks.knama AS plbagianpenjualan,   	st.nama AS plstatus ,   	pl.plmatauang ,   	pl.plkurs,     	b.bkode,   	pld.namabarang ,   	so.sonotransaksi ,   	pld.jml ,   	pld.satuan ,   (pld.jmlrealisasi / pld.nilaisatuan) AS jmlrealisasi ,   (pld.jml - (pld.jmlrealisasi / pld.nilaisatuan)) AS jmlsisa FROM m5_pl pl  JOIN m1_contact kc ON pl.plcustomer = kc.kid  JOIN m1_contact ks ON pl.plbagianpenjualan = ks.kid  JOIN m0_status st ON pl.plstatus = st.kode    JOIN m5_pl_detail pld ON pl.plid = pld.idpl  JOIN m1_item b ON pld.idbarang = b.bid    LEFT JOIN m5_so_detail sod ON pld.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid ORDER BY pl.pltgl , pl.plid, pl.plnotransaksi, pld.urutan;

-- RID=101 | MENU=6 | ITEM=3 | RQUERY=1 | NAME=Packing Barang (PL) 1/2 Letter | FILE=packinglistdetail1
SELECT    	pl.plid ,   	pl.plnotransaksi ,   	pl.pltgl,  	kc.knama AS plcustomer ,   	ks.knama AS plbagianpenjualan,   	pl.pluraian ,   	st.nama AS plstatus ,   	pl.plmatauang ,   	pl.plkurs,     	b.bkode,   	pld.namabarang ,   	so.sonotransaksi ,   	pld.jml ,   	pld.satuan ,   	pld.catatan AS plcatatan ,     	plp.idpl,   	plp.nopack ,   	plp.bentuk ,   	plp.berat ,   	plp.catatan FROM m5_pl pl  JOIN m1_contact kc ON pl.plcustomer = kc.kid  JOIN m1_contact ks ON pl.plbagianpenjualan = ks.kid  JOIN m0_status st ON pl.plstatus = st.kode  JOIN m5_pl_detail pld ON pl.plid = pld.idpl  JOIN m1_item b ON pld.idbarang = b.bid  JOIN m5_pl_pack plp on pld.nopack = plp.nopack AND pld.idpl = plp.idpl  LEFT JOIN m5_so_detail sod ON pld.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid ORDER BY pl.pltgl , pl.plid, pl.plnotransaksi, plp.nopack ,  pld.urutan;

-- RID=540 | MENU=6 | ITEM=4 | RQUERY=1 | NAME=Packing Barang (PL), UD | FILE=packinglistdetail1_UD
SELECT    	pl.plid ,   	pl.plnotransaksi ,   	pl.pltgl,  	kc.knama AS plcustomer ,   	ks.knama AS plbagianpenjualan,   	pl.pluraian ,   	st.nama AS plstatus ,   	pl.plmatauang ,   	pl.plkurs,     	b.bkode,   	pld.namabarang ,   	so.sonotransaksi ,   	pld.jml ,   	pld.satuan ,   	pld.catatan AS plcatatan ,     	plp.idpl,   	plp.nopack ,   	plp.bentuk ,   	plp.berat ,   	plp.catatan FROM m5_pl pl  JOIN m1_contact kc ON pl.plcustomer = kc.kid  JOIN m1_contact ks ON pl.plbagianpenjualan = ks.kid  JOIN m0_status st ON pl.plstatus = st.kode  JOIN m5_pl_detail pld ON pl.plid = pld.idpl  JOIN m1_item b ON pld.idbarang = b.bid  JOIN m5_pl_pack plp on pld.nopack = plp.nopack AND pld.idpl = plp.idpl  LEFT JOIN m5_so_detail sod ON pld.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid ORDER BY pl.pltgl , pl.plid, pl.plnotransaksi, plp.nopack ,  pld.urutan;

-- RID=320 | MENU=6 | ITEM=5 | RQUERY=1 | NAME=PL Terkait DO dan DR | FILE=plterkaitdodr
SELECT  	pld.idpldetail,  	dod.idpldetail AS ddo,  	pl.plnotransaksi,  	pl.pltgl,  	pld.jml,  	pld.satuan,  	pld.namabarang,  	pld.tipebarang,  	b.bkode,  	ks.knama,  	ddo.donotransaksi,  	ddo.dotgl,  	dod.jml AS asjmldo,  	dod.satuan AS assatuando,  	dr.drnotransaksi,  	dr.drtgl,  	drd.jml AS asjmldr,  	drd.satuan AS assatuandr   FROM m5_pl pl  JOIN m5_pl_detail pld ON pld.idpl = pl.plid  JOIN m1_contact ks ON ks.kid = pl.plbagianpenjualan  JOIN m1_item b ON pld.idbarang = b.bid  LEFT JOIN m5_do_detail dod ON pld.idpldetail = dod.idpldetail  JOIN m5_do ddo ON dod.iddo = ddo.doid    LEFT JOIN m5_dr_detail drd ON drd.iddodetail = dod.iddodetail AND dod.idbarang  JOIN m5_dr dr ON drd.iddr = dr.drid     GROUP BY pl.plnotransaksi, ddo.donotransaksi, dr.drnotransaksi ORDER BY pl.plnotransaksi, ddo.donotransaksi, dr.drnotransaksi, pld.urutan;

-- RID=321 | MENU=6 | ITEM=6 | RQUERY=1 | NAME=PL Terkait DO dan PI | FILE=plterkaitdopi
SELECT  	pld.idpldetail,  	dod.idpldetail AS ddo,  	pl.plnotransaksi,  	pl.pltgl,  	pld.jml,  	pld.satuan,  	pld.namabarang,  	pld.tipebarang,  	b.bkode,  	ks.knama,  	ddo.donotransaksi,  	ddo.dotgl,  	dod.jml AS asjmldo,  	dod.satuan AS assatuando,  	pi.pinotransaksi,  	pi.pitgl,  	pid.jml AS asjmlpi,  	pid.satuan AS assataunpi FROM m5_pl pl  JOIN m5_pl_detail pld ON pld.idpl = pl.plid  JOIN m1_contact ks ON ks.kid = pl.plbagianpenjualan  JOIN m1_item b ON pld.idbarang = b.bid  LEFT JOIN m5_do_detail dod ON pld.idpldetail = dod.idpldetail  JOIN m5_do ddo ON dod.iddo = ddo.doid  LEFT JOIN m5_pi_detail pid ON pid.idpidetail = dod.idpidetail AND dod.idbarang  JOIN m5_pi pi ON pid.idpi = pi.piid GROUP BY pl.plnotransaksi, ddo.donotransaksi, pi.pinotransaksi ORDER BY pl.plnotransaksi, ddo.donotransaksi, pi.pinotransaksi, pld.urutan;

-- RID=99 | MENU=6 | ITEM=7 | RQUERY=1 | NAME=Daftar Packing Barang (PL) Outstanding Sisa | FILE=listpackinglistoutstandingsisa
SELECT   	pl.plnotransaksi,  	pl.pltgl,  	(CASE pl.plstatus  	WHEN 0 THEN 'Draft'  	WHEN 1 THEN 'Minta Approve'  	WHEN 2 THEN 'Approved'  	WHEN 3 THEN 'Inprogress'  	WHEN 4 THEN 'Complete'  	WHEN 5 THEN 'Revisi'  	WHEN 6 THEN 'Reject'  	WHEN 7 THEN 'Close'  	WHEN 8 THEN 'Approve1'   	WHEN 9 THEN 'Approve2'   	WHEN 10 THEN 'Approve3'  	WHEN 11 THEN 'Approve'   	WHEN 12 THEN 'Hapus'  END) AS plstatus,  pld.jml,   ((pld.jml) - IFNULL(pld.jmldo,0)) AS jmldo,  ((pld.jml) - IFNULL(pld.jmldr,0)) AS jmldr,  ((pld.jml) - IFNULL(pld.jmlsi,0)) AS jmlsi,  ((pld.jml) - IFNULL(pld.jmlrnr,0)) AS jmlrnr,  ((pld.jml) - IFNULL(pld.jmlsr,0)) AS jmlsr,  ((pld.jml) - IFNULL(pid.jml,0)) AS jmlpi,  pld.satuan,  pld.namabarang,  pld.tipebarang,  pld.catatan,  b.bkode,  kc.knama AS customer,  ks.knama AS bagpenjualan FROM m5_pl pl  JOIN m1_contact kc ON pl.plcustomer = kc.kid  JOIN m5_pl_detail pld ON pl.plid = pld.idpl  JOIN m1_item b ON pld.idbarang = b.bid  LEFT JOIN m1_contact ks ON pl.plbagianpenjualan = ks.kid  LEFT JOIN m5_pi_detail pid ON pld.idpidetail = pid.idpidetail ORDER BY pl.plnotransaksi, pld.urutan;

-- RID=100 | MENU=6 | ITEM=8 | RQUERY=1 | NAME=Daftar Packing Barang (PL) Per Produk | FILE=listpackinglist_perproduk
SELECT    b.bid , b.bkode , pld.namabarang ,   pl.plnotransaksi , pl.pltgl , kc.knama AS plcustomer, ks.knama AS plbagianpenjualan ,   so.sonotransaksi , pi.pinotransaksi , SUM(pld.jml) AS jml , pld.satuan FROM m5_pl pl  JOIN m1_contact kc ON pl.plcustomer = kc.kid  JOIN m1_contact ks ON pl.plbagianpenjualan = ks.kid  JOIN m0_status st ON pl.plstatus = st.kode    JOIN m5_pl_detail pld ON pl.plid = pld.idpl  JOIN m1_item b ON pld.idbarang = b.bid    LEFT JOIN m5_so_detail sod ON pld.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid    LEFT JOIN m5_pi_detail pid ON pld.idpidetail = pid.idpidetail   LEFT JOIN m5_pi pi ON pid.idpi = pi.piid GROUP BY pld.idbarang, b.bid, b.bkode, pld.namabarang, pld.satuan, pld.idpl ORDER BY pld.idbarang , b.bid, b.bkode , pld.namabarang;

-- RID=742 | MENU=6 | ITEM=9 | RQUERY=1 | NAME=Packing Barang (PL) 1 Letter | FILE=packinglistdetail2
