plid,plcabang,pllokasi,plgudang,plasalbarang,plasalbarangkategori,pljenispenjualan,pljenispenjualankategori,plcarabayar,  plsumber,plautonotransaksi,plnotransaksi,pltgl,plkodepa,plcustomer,plcustomerkontak,pl1alamat1,pl1alamat2,pl1alamat3,  pl2alamat1,pl2alamat2,pl2alamat3,plbagianpenjualan,plbagianpengepakan,plekspedisi,pltglkirim,pltgljatuhtempo,pluraian,  plcatatan,plnoref,pltglnoref,pltglpenutupan,plmatauang,plkurs,plhargatermasukpajak,pltotal,pldiskonpersen,pljmldiskon,  pltotalpajak1detail,pltotalpajak2detail,plbiayalainpersen,plbiayalain,pltotaltransaksi,plrekdiskon,plrekpajak1,  plrekpajak2,plrekbiayalain,plidsq,plidso,plidpi,plstatusdo,plstatusdr,plstatussi,plstatusrnr,plstatussr,plstatusrealisasi,  plstatus,plstatussebelumnya,pljmlrevisi,plcetakanke,plinputuser,plinputtgl,plmodifikasiuser,plmodifikasitgl,plposting,  plpostingtgl,plisclose,plcustomtext1,plcustomtext2,plcustomtext3,plcustomtext4,plcustomtext5,plcustomint1,plcustomint2,  plcustomint3,plcustomdbl1,plcustomdbl2,plcustomdbl3,plcustomdate1,plcustomdate2,plcustomdate3,idpidetail,idpl,idbarang,  namabarang,tipebarang,nopack,jml,satuan,nilaisatuan,jmlbarang,satuanbarang,matauang,kurs,harga,diskon,jmldiskon,pajak1,  jmlpajak1,pajak2,jmlpajak2,cabang,lokasi,gudang,costcenter,divisi,subdivisi,proyek,catatan,urutan,idsqdetail,idsodetail,  idpidetail,jmldo,statusdo,jmldr,statusdr,jmlsi,statussi,jmlrnr,statusrnr,jmlsr,statussr,jmlrealisasi,statusrealisasi,  isclose FROM m5_pl pl  JOIN m5_pl_detail pld ON pl.plid = pld.idpl ORDER BY pl.pltgl ASC,pl.pltgl ASC, pld.idpldetail ASC;

