-- RID=103 | MENU=7 | ITEM=1 | RQUERY=1 | NAME=Daftar Pengiriman Order (DO) Detail | FILE=listdeliveryorder
SELECT     	doo.doid ,   	doo.donotransaksi ,  	doo.dotgl,   	kc.knama AS docustomer ,   	ks.knama AS dobagianpenjualan,   	w.wnama AS dogudang,   	doo.douraian,   	st.nama AS dostatus,   	doo.domatauang ,   	doo.dokurs,     	b.bkode ,   	dod.namabarang ,   	so.sonotransaksi ,   	dod.jml ,   	dod.satuan ,   	dod.catatan,     dod.harga ,   dod.harga * dod.jml AS total FROM m5_do doo  JOIN m1_contact kc ON doo.docustomer = kc.kid  JOIN m1_contact ks ON doo.dobagianpenjualan = ks.kid  JOIN m1_warehouse w ON doo.dogudang = w.wkode  JOIN m0_status st ON doo.dostatus = st.kode    JOIN m5_do_detail dod ON doo.doid = dod.iddo  JOIN m1_item b ON dod.idbarang = b.bid      LEFT JOIN m5_so_detail sod ON dod.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid ORDER BY doo.dotgl, doo.doid, doo.donotransaksi , dod.urutan;

-- RID=332 | MENU=7 | ITEM=2 | RQUERY=1 | NAME=Daftar Pengiriman Order (DO) Outstanding | FILE=listdeliveryorderoutstanding
SELECT     	doo.doid ,   	doo.donotransaksi ,  	doo.dotgl,   	kc.knama AS docustomer ,   	ks.knama AS dobagianpenjualan,   	w.wnama AS dogudang,   	doo.douraian,     	b.bkode ,   	dod.namabarang ,   	dod.jml ,   	dod.satuan, dod.catatan,   (dod.jmlrealisasi / dod.nilaisatuan) AS jmlrealisasi ,   dod.harga ,   (dod.jmlrealisasi / dod.nilaisatuan) * dod.harga AS total ,   (dod.jml - (dod.jmlrealisasi / dod.nilaisatuan)) AS jmlsisa,   doo.domatauang ,   doo.dokurs,  so.sonotransaksi FROM m5_do doo  JOIN m1_contact kc ON doo.docustomer = kc.kid  JOIN m1_contact ks ON doo.dobagianpenjualan = ks.kid  JOIN m1_warehouse w ON doo.dogudang = w.wkode    JOIN m5_do_detail dod ON doo.doid = dod.iddo  JOIN m1_item b ON dod.idbarang = b.bid    left join m5_so_detail sod on dod.idsodetail = sod.idsodetail  left join m5_so so on sod.idso = so.soid ORDER BY doo.dotgl, doo.doid, doo.donotransaksi , dod.urutan;

