-- RID=485 | MENU=7 | ITEM=7 | RQUERY=1 | NAME=Pengiriman Order (DO) Serial 1/2 Letter | FILE=deliveryorderdetail_serial
SELECT     	COUNT(*),   	dod.idbarang ,   	doo.doid ,   	doo.donotransaksi ,  	doo.dotgl,   	kc.knama AS docustomer ,   	ks.knama AS dobagianpenjualan,   	w.wnama AS dogudang,   	doo.douraian,   	st.nama AS dostatus,   	doo.domatauang ,   	doo.dokurs,     	b.bkode ,   	dod.namabarang ,   	so.sonotransaksi ,   	SUM(dod.jmlbarang) AS jml  ,   	dod.customdbl1,  	dod.satuan ,   	dod.catatan FROM m5_do doo  JOIN m1_contact kc ON doo.docustomer = kc.kid  JOIN m1_contact ks ON doo.dobagianpenjualan = ks.kid  JOIN m1_warehouse w ON doo.dogudang = w.wkode  JOIN m0_status st ON doo.dostatus = st.kode    JOIN m5_do_detail dod ON doo.doid = dod.iddo  JOIN m1_item b ON dod.idbarang = b.bid      LEFT JOIN m5_so_detail sod ON dod.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid GROUP BY doo.doid , dod.idbarang , dod.namabarang , dod.satuan ORDER BY doo.dotgl, doo.doid, doo.donotransaksi , dod.idbarang ,  dod.urutan;

-- RID=577 | MENU=7 | ITEM=8 | RQUERY=1 | NAME=Pengiriman Order (DO), UD Serial | FILE=deliveryorderdetail_serialUD
SELECT     	COUNT(*),   	dod.idbarang ,   	doo.doid ,   	doo.donotransaksi ,  	doo.dotgl,   	kc.knama AS docustomer ,   	ks.knama AS dobagianpenjualan,   	w.wnama AS dogudang,   	doo.douraian,   	st.nama AS dostatus,   	doo.domatauang ,   	doo.dokurs,     	b.bkode ,   	dod.namabarang ,   	so.sonotransaksi ,   	SUM(dod.jmlbarang) AS jml  ,   	dod.satuan ,   	dod.catatan FROM m5_do doo  JOIN m1_contact kc ON doo.docustomer = kc.kid  JOIN m1_contact ks ON doo.dobagianpenjualan = ks.kid  JOIN m1_warehouse w ON doo.dogudang = w.wkode  JOIN m0_status st ON doo.dostatus = st.kode    JOIN m5_do_detail dod ON doo.doid = dod.iddo  JOIN m1_item b ON dod.idbarang = b.bid      LEFT JOIN m5_so_detail sod ON dod.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid GROUP BY doo.doid , dod.idbarang , dod.namabarang , dod.satuan ORDER BY doo.dotgl, doo.doid, doo.donotransaksi , dod.idbarang ,  dod.urutan;

-- RID=542 | MENU=7 | ITEM=9 | RQUERY=1 | NAME=Pengiriman Order (DO), UD | FILE=deliveryorderdetail_UD
SELECT     	doo.doid ,   	doo.donotransaksi ,  	doo.dotgl,   	kc.knama AS docustomer ,   	ks.knama AS dobagianpenjualan,   	w.wnama AS dogudang,   	doo.douraian,   	st.nama AS dostatus,   	doo.domatauang ,   	doo.dokurs,     	b.bkode ,   	dod.namabarang ,   	so.sonotransaksi ,   	dod.jml,   	dod.satuan ,   	dod.catatan,    ilw.blgkodelokasi FROM m5_do doo  JOIN m1_contact kc ON doo.docustomer = kc.kid  JOIN m1_contact ks ON doo.dobagianpenjualan = ks.kid  JOIN m1_warehouse w ON doo.dogudang = w.wkode  JOIN m0_status st ON doo.dostatus = st.kode    JOIN m5_do_detail dod ON doo.doid = dod.iddo  JOIN m1_item b ON dod.idbarang = b.bid      LEFT JOIN m5_so_detail sod ON dod.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid  LEFT JOIN m1_item_location_warehouse ilw ON dod.idbarang = ilw.blgidbarang AND dod.gudangasal = ilw.blggudang ORDER BY doo.dotgl, doo.doid, doo.donotransaksi , dod.urutan;

-- RID=314 | MENU=7 | ITEM=10 | RQUERY=1 | NAME=DO Terkait DR dan PI | FILE=doterkaitdrpi
SELECT  	dod.iddodetail,  	drd.iddodetail AS dr,  	ddo.dotgl,  	ddo.donotransaksi,  	dod.namabarang,  	dod.tipebarang,  	dod.jml,  	dod.satuan,  	b.bkode,  	ks.knama,  	dr.drnotransaksi,  	dr.drtgl,  	drd.jml AS asjmldr,  	drd.satuan AS assatuandr,  	pi.pinotransaksi,  	pi.pitgl,  	pid.jml AS asjmlpi,  	pid.satuan AS assatuanpi FROM m5_do ddo  JOIN m5_do_detail dod ON dod.iddo = ddo.doid  JOIN m1_contact ks ON ks.kid = ddo.dobagianpenjualan  JOIN m1_item b ON dod.idbarang = b.bid    LEFT JOIN m5_dr_detail drd ON dod.iddodetail = drd.iddodetail  JOIN m5_dr dr ON dr.drid = drd.iddr    LEFT JOIN m5_pi_detail pid ON pid.idpidetail = drd.idpidetail AND drd.idbarang  JOIN m5_pi pi ON pid.idpi = pi.piid GROUP BY ddo.donotransaksi, dr.drnotransaksi, pi.pinotransaksi ORDER BY ddo.donotransaksi, dr.drnotransaksi, pi.pinotransaksi, dod.urutan;

-- RID=315 | MENU=7 | ITEM=11 | RQUERY=1 | NAME=DO terkait DR dan SI | FILE=doterkaitdrsi
SELECT  	dod.iddodetail,  	drd.iddodetail AS dr,  	ddo.dotgl,  	ddo.donotransaksi,  	dod.namabarang,  	dod.tipebarang,  	dod.jml,  	dod.satuan,  	b.bkode,  	ks.knama,  	dr.drnotransaksi,  	dr.drtgl,  	drd.jml AS asjmldr,  	drd.satuan AS assatuandr,  	si.sinotransaksi,  	si.sitgl,  	sid.jml AS asjmlsi,  	sid.satuan AS assatuansi FROM m5_do ddo  JOIN m5_do_detail dod ON dod.iddo = ddo.doid  JOIN m1_contact ks ON ks.kid = ddo.dobagianpenjualan  JOIN m1_item b ON dod.idbarang = b.bid  LEFT JOIN m5_dr_detail drd ON dod.iddodetail = drd.iddodetail  JOIN m5_dr dr ON dr.drid = drd.iddr  LEFT JOIN m5_si_detail sid ON sid.iddrdetail = drd.iddrdetail AND drd.idbarang  JOIN m5_si si ON sid.idsi = si.siid   GROUP BY ddo.donotransaksi, dr.drnotransaksi, si.sinotransaksi ORDER BY ddo.donotransaksi, dr.drnotransaksi, si.sinotransaksi, dod.urutan;

-- RID=339 | MENU=7 | ITEM=12 | RQUERY=1 | NAME=Daftar Pengiriman Order (DO) Outstanding Sisa | FILE=listdeliveryorderoutstandingsisa
SELECT  	`do`.donotransaksi,  	`do`.dotgl,  	dod.namabarang,  	dod.tipebarang,  	b.bkode,  	dod.jml,  	dod.satuan,  	dod.catatan,  	`do`.douraian,  	`do`.dotermin,  	((dod.jml) - IFNULL(dod.jmldr,0)) AS jmldr,  	((dod.jml) - IFNULL(dod.jmlsi,0)) AS jmlsi,  	((dod.jml) - IFNULL(dod.jmlrnr,0)) AS jmlrnr,  	((dod.jml) - IFNULL(dod.jmlsr,0)) AS jmlsr,  	((dod.jml) - IFNULL(pid.jml,0)) AS jmlpi,  	kc.knama AS customer,  	ks.knama AS salesman FROM m5_do `do`  JOIN m5_do_detail dod ON `do`.doid = dod.iddo  JOIN m1_item b ON dod.idbarang = b.bid  JOIN m1_contact kc ON `do`.docustomer = kc.kid  JOIN m1_contact ks ON `do`.dobagianpenjualan = ks.kid  LEFT JOIN m5_pi_detail pid ON dod.idpldetail = pid.idpidetail   ORDER BY `do`.donotransaksi, dod.urutan;

-- RID=1026 | MENU=7 | ITEM=13 | RQUERY=1 | NAME=Daftar Pengiriman Order (DO) Per Produk | FILE=listdeliveryorder_perproduk
SELECT    b.bid , b.bkode , dod.namabarang ,   doo.donotransaksi , doo.dotgl , kc.knama AS docustomer , ks.knama AS dobagianpenjualan,   so.sonotransaksi, SUM(dod.jml) AS jml ,   	dod.satuan FROM m5_do doo  JOIN m1_contact kc ON doo.docustomer = kc.kid  JOIN m1_contact ks ON doo.dobagianpenjualan = ks.kid  JOIN m1_warehouse w ON doo.dogudang = w.wkode  JOIN m0_status st ON doo.dostatus = st.kode    JOIN m5_do_detail dod ON doo.doid = dod.iddo  JOIN m1_item b ON dod.idbarang = b.bid    LEFT JOIN m5_so_detail sod ON dod.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid GROUP BY dod.idbarang, b.bid, b.bkode, dod.namabarang, dod.satuan, dod.iddo ORDER BY dod.idbarang, b.bid, b.bkode , dod.namabarang;

-- RID=776 | MENU=7 | ITEM=14 | RQUERY=1 | NAME=Pengiriman Order (DO) Batch 1/2 Letter | FILE=deliveryorderdetail_batch
SELECT     	COUNT(*),   	dod.idbarang ,   	doo.doid ,   	doo.donotransaksi ,  	doo.dotgl,   	kc.knama AS docustomer ,   	ks.knama AS dobagianpenjualan,   	w.wnama AS dogudang,   	doo.douraian,   	st.nama AS dostatus,   	doo.domatauang ,   	doo.dokurs,     	b.bkode ,   	dod.namabarang ,   	so.sonotransaksi ,   	SUM(dod.jmlbarang) AS jml  ,   	dod.customdbl1,  	dod.satuan ,   	dod.catatan FROM m5_do doo  JOIN m1_contact kc ON doo.docustomer = kc.kid  JOIN m1_contact ks ON doo.dobagianpenjualan = ks.kid  JOIN m1_warehouse w ON doo.dogudang = w.wkode  JOIN m0_status st ON doo.dostatus = st.kode    JOIN m5_do_detail dod ON doo.doid = dod.iddo  JOIN m1_item b ON dod.idbarang = b.bid      LEFT JOIN m5_so_detail sod ON dod.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid GROUP BY doo.doid , dod.idbarang , dod.namabarang , dod.satuan ORDER BY doo.dotgl, doo.doid, doo.donotransaksi , dod.idbarang ,  dod.urutan;

-- RID=233 | MENU=7 | ITEM=15 | RQUERY=1 | NAME=Pengiriman Order (DO) Valas | FILE=deliveryorderdetailvalas
SELECT  	`do`.donotransaksi,  	`do`.dotgl,  	dod.namabarang,  	dod.tipebarang,  	b.bkode,  	`do`.domatauang,  	Sum(dod.jml) AS jml,  	dod.satuan,  	dod.harga,  	dod.diskon,  	dod.jmldiskon,  	g.wnama,  	kc.knama AS customer,  	ks.knama AS salesman,  	Sum((dod.harga * dod.jml) - dod.jmldiskon) AS total,  	dod.matauang,  	dod.kurs,  	`do`.dokurs,  	(dod.harga * dod.kurs) AS hargavalas,  	SUM(dod.jml * (dod.harga * dod.kurs) - (dod.jmldiskon * dod.kurs)) AS totalvalas FROM m5_do `do`  JOIN m5_do_detail dod ON `do`.doid = dod.iddo  JOIN m1_item b ON dod.idbarang = b.bid  JOIN m1_contact kc ON `do`.docustomer = kc.kid  JOIN m1_contact ks ON `do`.dobagianpenjualan = ks.kid  JOIN m1_warehouse g ON `do`.dogudang = g.wkode   WHERE `do`.domatauang <> "IDR" GROUP BY `do`.donotransaksi, b.bkode, dod.tipebarang, dod.namabarang ORDER BY `do`.donotransaksi, dod.urutan;

-- RID=1168 | MENU=7 | ITEM=16 | RQUERY=1 | NAME=Pengiriman Order (DO) Alamat 1/2 Letter | FILE=deliveryorderdetail_new3
