-- RID=50001775 | MENU=7 | ITEM=22 | RQUERY=1 | NAME=Packing List (BR) | FILE=DO 1
SELECT    doo.donotransaksi ,   doo.dotgl ,   k.knama AS docustomer ,   doo.do1alamat1 ,   doo.do2alamat1 ,  doo.dotglkirim ,     doo.douraian ,     doo.donoref ,     so.sotgl ,     dod.customdbl3 AS bundle ,   dod.catatan ,     b.bnama ,   b.bjmllapangan ,   b.bsatuanlapangan ,   dod.jml ,   dod.satuan ,   dod.customdbl2 AS GW ,     doo.docatatan FROM m5_do doo   JOIN m5_do_detail dod ON doo.doid = dod.iddo   JOIN m1_contact k ON doo.docustomer = k.kid    LEFT JOIN m5_so_detail sod ON dod.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid     JOIN m1_item b ON dod.idbarang = b.bid ORDER BY doo.dotgl ASC , doo.doid ASC , dod.urutan ASC;

-- RID=50001776 | MENU=7 | ITEM=23 | RQUERY=1 | NAME=Packing List (BW) | FILE=DO 2
SELECT    	doo.donotransaksi ,   	doo.dotgl ,   	k.knama AS docustomer ,   	doo.do1alamat1 ,   	doo.do2alamat1 ,  	doo.dotglkirim ,     	doo.douraian ,     	doo.donoref ,     	so.sotgl ,         	b.bnama ,   	b.bjmllapangan ,   	b.bsatuanlapangan ,   	dod.satuan ,   	dod.customtext2 AS NoPallet ,   	dod.customdbl3 AS TTL ,   	dod.jml AS NW,   dod.customdbl2 AS GW ,   dod.catatan ,   0 AS TTLKGS ,   0 AS TTLKGS2 ,       	doo.docatatan FROM m5_do doo   JOIN m5_do_detail dod ON doo.doid = dod.iddo   JOIN m1_contact k ON doo.docustomer = k.kid    LEFT JOIN m5_so_detail sod ON dod.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid     JOIN m1_item b ON dod.idbarang = b.bid ORDER BY doo.dotgl ASC , doo.doid ASC , dod.urutan ASC;

-- RID=105 | MENU=8 | ITEM=1 | RQUERY=1 | NAME=Daftar Hasil Pengiriman Order (DR) Detail | FILE=listdeliveryreport
SELECT    dr.drid,   dr.drnotransaksi ,   dr.drtgl ,   kc.knama AS drcustomer ,   ks.knama AS drbagianpenjualan,   w.wnama AS drgudang ,   dr.druraian ,   st.nama AS drstatus,   dr.drmatauang ,   dr.drkurs ,     b.bkode,   drd.namabarang ,   drd.jml ,   drd.jmlkembali ,   drd.satuan ,   doo.donotransaksi ,   drd.catatan FROM m5_dr dr  JOIN m1_contact kc ON dr.drcustomer = kc.kid  JOIN m1_contact ks ON dr.drbagianpenjualan = ks.kid  JOIN m1_warehouse w ON dr.drgudang = w.wkode  JOIN m0_status st ON dr.drstatus = st.kode    JOIN m5_dr_detail drd ON dr.drid = drd.iddr  JOIN m1_item b ON drd.idbarang = b.bid    LEFT JOIN m5_do_detail dod ON drd.iddodetail = dod.iddodetail   LEFT JOIN m5_do doo ON dod.iddo = doo.doid ORDER BY dr.drtgl , dr.drid , dr.drnotransaksi, drd.urutan;

-- RID=333 | MENU=8 | ITEM=2 | RQUERY=1 | NAME=Daftar Hasil Pengiriman (DR) Outstanding | FILE=listdeliveryreportoutstanding
SELECT    	dr.drid,   	dr.drnotransaksi ,   	dr.drtgl ,   	kc.knama AS drcustomer ,   	ks.knama AS drbagianpenjualan,   	w.wnama AS drgudang ,   	dr.druraian ,     	b.bkode,   	drd.namabarang ,   	drd.jml ,   	drd.jmlkembali ,   	drd.satuan ,   	(drd.jmlrealisasi / drd.nilaisatuan) AS jmlrealisasi ,   (drd.jml - (drd.jmlrealisasi / drd.nilaisatuan)) AS jmlsisa,     dr.drmatauang ,   dr.drkurs ,   doo.donotransaksi ,   drd.harga ,     drd.harga * drd.jml AS hargajml,   drd.harga * drd.jmlkembali AS hargajmlkembali,   (drd.jmlrealisasi / drd.nilaisatuan) * drd.harga AS hargajmlrealisasi ,   (drd.jml - (drd.jmlrealisasi / drd.nilaisatuan)) * drd.harga AS hargajmlsisa,  so.sonotransaksi FROM m5_dr dr  JOIN m1_contact kc ON dr.drcustomer = kc.kid  JOIN m1_contact ks ON dr.drbagianpenjualan = ks.kid  JOIN m1_warehouse w ON dr.drgudang = w.wkode    JOIN m5_dr_detail drd ON dr.drid = drd.iddr  JOIN m1_item b ON drd.idbarang = b.bid    LEFT JOIN m5_do_detail dod ON drd.iddodetail = dod.iddodetail  LEFT JOIN m5_do doo ON dod.iddo = doo.doid     left join m5_so_detail sod on dod.idsodetail = sod.idsodetail  left join m5_so so on sod.idso = so.soid ORDER BY dr.drtgl , dr.drid , dr.drnotransaksi, drd.urutan;

