SELECT    dr.drid,   dr.drnotransaksi ,   dr.drtgl ,   kc.knama AS drcustomer ,   ks.knama AS drbagianpenjualan,   w.wnama AS drgudang ,   dr.druraian ,   st.nama AS drstatus,   dr.drmatauang ,   dr.drkurs ,     b.bkode,   drd.namabarang ,   drd.jml ,   drd.jmlkembali ,   drd.satuan ,   doo.donotransaksi ,   drd.catatan FROM m5_dr dr  JOIN m1_contact kc ON dr.drcustomer = kc.kid  JOIN m1_contact ks ON dr.drbagianpenjualan = ks.kid  JOIN m1_warehouse w ON dr.drgudang = w.wkode  JOIN m0_status st ON dr.drstatus = st.kode    JOIN m5_dr_detail drd ON dr.drid = drd.iddr  JOIN m1_item b ON drd.idbarang = b.bid    LEFT JOIN m5_do_detail dod ON drd.iddodetail = dod.iddodetail   LEFT JOIN m5_do doo ON dod.iddo = doo.doid ORDER BY dr.drtgl , dr.drid , dr.drnotransaksi, drd.urutan;

-- RID=317 | MENU=8 | ITEM=7 | RQUERY=1 | NAME=DR Terkait SI dan RNR | FILE=drterkaitsirnr
SELECT    	drd.iddrdetail,  	sid.iddrdetail AS si,  	dr.drnotransaksi,  	dr.drtgl,  	drd.namabarang,  	drd.tipebarang,  	b.bkode,  	ks.knama,  	drd.jml,  	drd.satuan,	  	si.sinotransaksi,  	si.sitgl,  	sid.jml AS asjmlsi,  	sid.satuan AS assatuansi,  	rnr.rnrnotransaksi,  	rnr.rnrtgl,  	rnrd.jml AS asjmlrnr,  	rnrd.satuan AS assatuanrnr FROM m5_dr dr  JOIN m5_dr_detail drd ON drd.iddr = dr.drid  JOIN m1_contact ks ON ks.kid = dr.drbagianpenjualan  JOIN m1_item b ON drd.idbarang = b.bid  LEFT JOIN m5_si_detail sid ON drd.iddrdetail = sid.iddrdetail  JOIN m5_si si ON si.siid = sid.idsi  LEFT JOIN m5_rnr_detail rnrd ON rnrd.idsidetail = sid.idsidetail AND sid.idbarang  JOIN m5_rnr rnr ON rnrd.idrnr = rnr.rnrid   GROUP BY dr.drnotransaksi, si.sinotransaksi, rnr.rnrnotransaksi ORDER BY dr.drnotransaksi, si.sinotransaksi, rnr.rnrnotransaksi, drd.urutan;

-- RID=340 | MENU=8 | ITEM=8 | RQUERY=1 | NAME=Daftar Hasil Pengiriman (DR) Outstanding Sisa | FILE=listdeliveryreportoutstandingsisa
SELECT  	dr.drnotransaksi,  	dr.drtgl,  	drd.jml,  	drd.satuan,  	drd.namabarang,  	drd.tipebarang,  	b.bkode,  	dr.druraian,  	drd.catatan,  	dr.drtermin,  	((drd.jml) - IFNULL(pid.jml,0)) AS jmlpi,  	((drd.jml) - IFNULL(drd.jmlsi,0)) AS jmlsi,  	((drd.jml) - IFNULL(drd.jmlrnr,0)) AS jmlrnr,  	((drd.jml) - IFNULL(drd.jmlsr,0)) AS jmlsr,  	kp.knama AS bagpengiriman FROM m5_dr dr  JOIN m5_dr_detail drd ON dr.drid = drd.iddr  JOIN m1_item b ON drd.idbarang = b.bid  JOIN m1_contact kp ON dr.drbagianpengiriman = kp.kid  LEFT JOIN m5_pi_detail pid ON drd.idpidetail = pid.idpidetail   ORDER BY dr.drnotransaksi, drd.urutan;

-- RID=248 | MENU=8 | ITEM=9 | RQUERY=1 | NAME=Hasil Pengiriman Order (DR) Valas  | FILE=deliveryreportdetailvalas
SELECT  	dr.drnotransaksi,  	dr.drtgl,  	sum(drd.jml) AS jml,  	drd.satuan,  	dr.drmatauang,  	drd.namabarang,  	drd.tipebarang,  	dr.drtglkirim,  	b.bkode,  	dr.druraian,  	drd.catatan,  	drd.harga,  	drd.diskon,  	drd.jmldiskon,  	sum((drd.jml * drd.harga) - drd.jmldiskon) AS total,  	kp.knama AS bagpengiriman,  	(drd.harga * drd.kurs) as hargavalas,  	SUM(drd.jml * (drd.harga * drd.kurs) - (drd.jmldiskon * drd.kurs)) AS totalvalas,  	dr.drkurs FROM m5_dr dr  JOIN m5_dr_detail drd ON dr.drid = drd.iddr  JOIN m1_item b ON drd.idbarang = b.bid  JOIN m1_contact kp ON dr.drbagianpengiriman = kp.kid   WHERE (dr.drmatauang <> "IDR") GROUP BY dr.drnotransaksi, b.bkode, drd.tipebarang, drd.namabarang ORDER BY dr.drnotransaksi, drd.urutan;

-- RID=778 | MENU=8 | ITEM=10 | RQUERY=1 | NAME=Hasil Pengiriman Order (DR) Batch 1/2 Letter | FILE=deliveryreportdetail_batch
