drid,drcabang,drlokasi,drgudang,drasalbarang,drasalbarangkategori,drjenispenjualan,drjenispenjualankategori,  drcarabayar,drsumber,drautonotransaksi,drnotransaksi,drtgl,drkodepa,drcustomer,drcustomerkontak,dr1alamat1,  dr1alamat2,dr1alamat3,dr2alamat1,dr2alamat2,dr2alamat3,drbagianpenjualan,drbagianpengiriman,drekspedisi,  drtglkirim,drtermin,drtgljatuhtempo,druraian,drcatatan,drnoref,drtglnoref,drtglpenutupan,drmatauang,  drkurs,drhargatermasukpajak,drtotal,drdiskonpersen,drjmldiskon,drtotalpajak1detail,drtotalpajak2detail,  drbiayalainpersen,drbiayalain,drtotaltransaksi,drrekdiskon,drrekpajak1,drrekpajak2,drrekbiayalain,dridsq,  dridso,dridpl,driddo,drstatussi,drstatusrnr,drstatussr,drstatusrealisasi,drstatus,drstatussebelumnya,drjmlrevisi,  drcetakanke,drinputuser,drinputtgl,drmodifikasiuser,drmodifikasitgl,drposting,drpostingtgl,drtutupperiode,  drisclose,drcustomtext1,drcustomtext2,drcustomtext3,drcustomtext4,drcustomtext5,drcustomint1,drcustomint2,  drcustomint3,drcustomdbl1,drcustomdbl2,drcustomdbl3,drcustomdate1,drcustomdate2,drcustomdate3,iddrdetail,iddr,  idbarang,namabarang,tipebarang,jml,jmlkembali,satuan,nilaisatuan,jmlbarang,jmlbarangkembali,satuanbarang,  matauang,kurs,idhppkhususmasuk,idhppfifomasuk,harga,hpp,diskon,jmldiskon,pajak1,jmlpajak1,pajak2,jmlpajak2,  cabang,lokasi,gudangasal,gudangtransit,gudangtujuan,gudangkembali,rekpersediaan,rekhargapokok,rekdiskonpenjualan,  costcenter,divisi,subdivisi,proyek,catatan,urutan,idsqdetail,idsodetail,idpidetail,idpldetail,iddodetail,jmlsi,  statussi,jmlrnr,statusrnr,jmlsr,statussr,jmlrealisasi,statusrealisasi,isclose FROM m5_dr dr  JOIN m5_dr_detail drd ON dr.drid = drd.iddr ORDER BY dr.drtgl ASC,dr.drtgl ASC, drd.iddrdetail ASC;

-- RID=107 | MENU=9 | ITEM=1 | RQUERY=1 | NAME=Daftar Invoice Sementara (PI) Detail | FILE=listproformainvoice
SELECT    	pi.piid,   	pi.pinotransaksi ,   	pi.pitgl ,   	kc.knama AS picustomer,   	ks.knama AS pibagianpenjualan,   	st.nama AS pistatus,   	pi.pimatauang ,   	pi.pikurs ,   	pi.pidiskonpersen ,   	pi.pijmldiskon ,   	pi.pibiayalain ,   	pi.pitotalpajak1detail,     	b.bkode ,   	pid.namabarang ,   	so.sonotransaksi ,   	pid.catatan,   	pid.jml ,   	pid.satuan ,   	pid.diskon ,   	pid.harga ,   	((pid.jml * pid.harga) - pid.jmldiskon) AS total FROM m5_pi pi   JOIN m1_contact kc ON pi.picustomer = kc.kid  JOIN m1_contact ks ON pi.pibagianpenjualan = ks.kid  JOIN m0_status st ON pi.pistatus = st.kode    JOIN m5_pi_detail pid ON pi.piid = pid.idpi  JOIN m1_item b ON pid.idbarang = b.bid    LEFT JOIN m5_so_detail sod ON pid.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid ORDER BY pi.pitgl, pi.piid, pi.pinotransaksi , pid.urutan;

-- RID=108 | MENU=9 | ITEM=2 | RQUERY=1 | NAME=Daftar Invoice Sementara (PI) Outstanding | FILE=listproformainvoiceoutstanding
SELECT    pi.piid ,   pi.pinotransaksi ,   pi.pitgl ,   kc.knama AS picustomer ,   ks.knama AS pibagianpenjualan ,   pi.piuraian ,     b.bkode ,   pid.namabarang ,   pid.catatan ,   pid.jml ,   pid.satuan,   (pid.jmlrealisasi / pid.nilaisatuan) AS jmlrealisasi ,   (pid.jml - (pid.jmlrealisasi / pid.nilaisatuan)) AS jmlsisa FROM m5_pi pi   JOIN m1_contact kc ON pi.picustomer = kc.kid  JOIN m1_contact ks ON pi.pibagianpenjualan = ks.kid    JOIN m5_pi_detail pid ON pi.piid = pid.idpi  JOIN m1_item b ON pid.idbarang = b.bid ORDER BY pi.pitgl, pi.piid, pi.pinotransaksi , pid.urutan;

-- RID=111 | MENU=9 | ITEM=3 | RQUERY=1 | NAME=Invoice Sementara (PI) 1/2 Letter | FILE=proformainvoicedetail1
SELECT    	pi.piid,   	pi.pinotransaksi ,   	pi.pitgl ,   	kc.knama AS picustomer,   	kc.k1alamat1 ,   	ks.knama AS pibagianpenjualan,   	st.nama AS pistatus,   	pi.pimatauang ,   	pi.pikurs ,   	pi.pidiskonpersen ,   	pi.pijmldiskon ,   	pi.pibiayalain ,   	pi.pitotalpajak1detail,   	pi.piuraian ,     	b.bkode ,   	pid.namabarang ,   	so.sonotransaksi ,   	pid.catatan,   	pid.jml ,   	pid.satuan ,   	pid.diskon ,   	pid.harga ,   	((pid.jml * pid.harga) - pid.jmldiskon) AS total ,   usr.unama FROM m5_pi pi   JOIN m1_contact kc ON pi.picustomer = kc.kid  JOIN m1_contact ks ON pi.pibagianpenjualan = ks.kid  JOIN m0_status st ON pi.pistatus = st.kode  JOIN m5_pi_detail pid ON pi.piid = pid.idpi  JOIN m1_item b ON pid.idbarang = b.bid  JOIN m0_user usr ON pi.piinputuser = usr.userid  LEFT JOIN m5_so_detail sod ON pid.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid ORDER BY pi.pitgl, pi.piid, pi.pinotransaksi , pid.urutan;

-- RID=538 | MENU=9 | ITEM=4 | RQUERY=1 | NAME=Invoice Sementara (PI), UD | FILE=proformainvoicedetail1_UD
SELECT    	pi.piid,   	pi.pinotransaksi ,   	pi.pitgl ,   	kc.knama AS picustomer,   	ks.knama AS pibagianpenjualan,   	st.nama AS pistatus,   	pi.pimatauang ,   	pi.pikurs ,   	pi.pidiskonpersen ,   	pi.pijmldiskon ,   	pi.pibiayalain ,   	pi.pitotalpajak1detail,   	pi.piuraian ,     	b.bkode ,   	pid.namabarang ,   	so.sonotransaksi ,   	pid.catatan,   	pid.jml ,   	pid.satuan ,   	pid.diskon ,   	pid.harga ,   	((pid.jml * pid.harga) - pid.jmldiskon) AS total FROM m5_pi pi   JOIN m1_contact kc ON pi.picustomer = kc.kid  JOIN m1_contact ks ON pi.pibagianpenjualan = ks.kid  JOIN m0_status st ON pi.pistatus = st.kode    JOIN m5_pi_detail pid ON pi.piid = pid.idpi  JOIN m1_item b ON pid.idbarang = b.bid    LEFT JOIN m5_so_detail sod ON pid.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid ORDER BY pi.pitgl, pi.piid, pi.pinotransaksi , pid.urutan;

-- RID=669 | MENU=9 | ITEM=5 | RQUERY=1 | NAME=Invoice Sementara (PI) Surat Jalan 1/2 Letter | FILE=proformainvoicedetaildo1
SELECT    pi.pitgl ,   pi.pinotransaksi ,   st.nama AS pistatus ,   kc.knama AS picustomer,   ks.knama AS pibagianpenjualan ,   w.wnama AS pigudang ,   pi.piuraian ,     b.bkode ,   pid.namabarang ,   pid.jml ,   pid.satuan ,   pid.catatan ,     ilw.blgnamalokasi FROM m5_pi pi   JOIN m0_status st ON pi.pistatus = st.kode  JOIN m1_contact ks ON pi.pibagianpenjualan = ks.kid  JOIN m1_warehouse w ON pi.pigudang = w.wkode   JOIN m5_pi_detail pid ON pi.piid = pid.idpi   JOIN m1_item b ON pid.idbarang = b.bid  LEFT JOIN m1_contact kc ON pi.picustomer = kc.kid   LEFT JOIN m1_item_location_warehouse ilw ON pid.idbarang = ilw.blgidbarang AND pid.gudang = ilw.blggudang ORDER BY pi.pitgl , pi.piid , pi.pinotransaksi , pid.urutan;

-- RID=670 | MENU=9 | ITEM=6 | RQUERY=1 | NAME=Invoice Sementara (PI) Invoice 1/2 Letter | FILE=proformainvoicedetailsi1
SELECT    pi.pitgl,   pi.pinotransaksi ,   pi.pimatauang ,   st.nama AS pistatus ,   kc.knama AS picustomer ,   pi.pitermin ,   pi.piuraian ,     b.bkode ,   pid.namabarang ,   pid.jml ,   pid.satuan ,   pid.harga ,   pid.diskon ,   ((pid.jml * pid.harga) - pid.jmldiskon) AS total ,   so.sonotransaksi ,     pi.pijmldiskon ,   pi.picustomdbl2,   pi.pitotalpajak1detail ,   pi.pibiayalain FROM m5_pi pi  JOIN m0_status st ON pi.pistatus = st.kode  JOIN m1_contact kc ON pi.picustomer = kc.kid    JOIN m5_pi_detail pid ON pi.piid = pid.idpi  JOIN m1_item b ON pid.idbarang = b.bid     LEFT JOIN m5_so_detail sod ON pid.idsodetail = sod.idsodetail   LEFT JOIN m5_so so ON sod.idso = so.soid ORDER BY pi.pitgl , pi.piid , pi.pinotransaksi, pid.urutan;

-- RID=310 | MENU=9 | ITEM=7 | RQUERY=1 | NAME=Invoice Sementara (PI) Valas 1/2 Letter | FILE=proformainvoicedetail_valas1
SELECT    	pi.piid,   	pi.pinotransaksi ,   	pi.pitgl ,   	kc.knama AS picustomer,   	kc.k1alamat1 ,   	ks.knama AS pibagianpenjualan,   	st.nama AS pistatus,   	pi.pimatauang ,   	pi.pikurs ,   	pi.pidiskonpersen ,   	pi.pijmldiskon ,   	pi.pibiayalain ,   	pi.pitotalpajak1detail,   	pi.piuraian ,     	b.bkode ,   	pid.namabarang ,   	so.sonotransaksi ,   	pid.catatan,   	pid.jml ,   	pid.satuan ,   	pid.diskon ,   	pid.harga ,   	(pid.harga * pid.kurs) AS hargavalas ,   	((pid.jml * pid.harga) - pid.jmldiskon) AS total ,   ((pid.jml * (pid.harga * pid.kurs)) - (pid.jmldiskon * pid.kurs)) AS totalvalas ,   usr.unama FROM m5_pi pi   JOIN m1_contact kc ON pi.picustomer = kc.kid  JOIN m1_contact ks ON pi.pibagianpenjualan = ks.kid  JOIN m0_status st ON pi.pistatus = st.kode  JOIN m5_pi_detail pid ON pi.piid = pid.idpi  JOIN m1_item b ON pid.idbarang = b.bid  JOIN m0_user usr ON pi.piinputuser = usr.userid  LEFT JOIN m5_so_detail sod ON pid.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid WHERE (pi.pimatauang <> "IDR" AND pi.pimatauang <> "RP" ) ORDER BY pi.pitgl, pi.piid, pi.pinotransaksi , pid.urutan;

-- RID=318 | MENU=9 | ITEM=8 | RQUERY=1 | NAME=PI terkait SI dan RNR | FILE=piterkaitsirnr
SELECT    	pid.idpidetail,  	sid.idpidetail AS si,  	pi.pinotransaksi,  	pi.pitgl,  	pid.jml,  	pid.satuan,  	pid.namabarang,  	pid.tipebarang,  	b.bkode,  	ks.knama,  	si.sinotransaksi,  	si.sitgl,  	sid.jml AS asjmlsi,  	sid.satuan AS assatuansi,  	rnr.rnrnotransaksi,  	rnr.rnrtgl,  	rnrd.jml AS jmlrnr,  	rnrd.satuan AS assatuanrnr   FROM m5_pi pi  JOIN m5_pi_detail pid ON pid.idpi = pi.piid  JOIN m1_contact ks ON ks.kid = pi.pibagianpenjualan  JOIN m1_item b ON pid.idbarang = b.bid  LEFT JOIN m5_si_detail sid ON pid.idpidetail = sid.idpidetail  JOIN m5_si si ON si.siid = sid.idsi  LEFT JOIN m5_rnr_detail rnrd ON rnrd.idsidetail = sid.idsidetail AND sid.idbarang  JOIN m5_rnr rnr ON rnrd.idrnr = rnr.rnrid   GROUP BY pi.pinotransaksi, si.sinotransaksi, rnr.rnrnotransaksi ORDER BY pi.pinotransaksi, si.sinotransaksi, rnr.rnrnotransaksi, pid.urutan;

-- RID=319 | MENU=9 | ITEM=9 | RQUERY=1 | NAME=PI Terkait SI dan SR | FILE=piterkaitsisr
SELECT    	pid.idpidetail,  	sid.idpidetail AS si,  	pi.pinotransaksi,  	pi.pitgl,  	pid.jml,  	pid.satuan,  	pid.namabarang,  	pid.tipebarang,  	b.bkode,  	ks.knama,  	si.sinotransaksi,  	si.sitgl,  	sid.jml AS asjmlsi,  	sid.satuan AS assatuansi,  	sr.srnotransaksi,  	sr.srtgl,  	srd.jml AS asjmlsr,  	srd.satuan AS assatuansr FROM m5_pi pi  JOIN m5_pi_detail pid ON pid.idpi = pi.piid  JOIN m1_contact ks ON ks.kid = pi.pibagianpenjualan  JOIN m1_item b ON pid.idbarang = b.bid  LEFT JOIN m5_si_detail sid ON pid.idpidetail = sid.idpidetail  JOIN m5_si si ON si.siid = sid.idsi  LEFT JOIN m5_sr_detail srd ON srd.idsidetail = sid.idsidetail AND sid.idbarang  JOIN m5_sr sr ON srd.idsr = sr.srid   GROUP BY pi.pinotransaksi, si.sinotransaksi, sr.srnotransaksi ORDER BY pi.pinotransaksi, si.sinotransaksi, sr.srnotransaksi, pid.urutan;

-- RID=109 | MENU=9 | ITEM=10 | RQUERY=1 | NAME=Daftar Invoice Sementara (PI) Outstanding Sisa | FILE=listproformainvoiceresidueoutstanding
SELECT  	pi.pinotransaksi,   	pi.pitgl,   	pi.pitermin,  	pi.piuraian,  	pid.catatan,  	pid.jml,  	((pid.jml) - IFNULL(sod.jml,0)) AS jmlso,  	((pid.jml) - IFNULL(sqd.jml,0)) AS jmlsq,  	((pid.jml) - IFNULL(pld.jml,0)) AS jmlpl,  	((pid.jml) - IFNULL(dod.jml,0)) AS jmldo,  	((pid.jml) - IFNULL(drd.jml,0)) AS jmldr,  	((pid.jml) - IFNULL(pid.jmlsi,0)) AS jmlsi,   	((pid.jml) - IFNULL(pid.jmlrnr,0)) AS jmlrnr,  	((pid.jml) - IFNULL(pid.jmlsr,0)) AS jmlsr,  	pid.satuan,  	pid.namabarang,   	pid.tipebarang,  	b.bkode,   	kc.knama AS customer,   	ks.knama AS bagpenjualan,     	CASE pi.pistatus   	WHEN 0 THEN 'Draft'  	WHEN 1 THEN 'Minta Approve'  	WHEN 2 THEN 'Approved'  	WHEN 3 THEN 'Inprogress'  	WHEN 4 THEN 'Complete'  	WHEN 5 THEN 'Revisi'  	WHEN 6 THEN 'Reject'  	WHEN 7 THEN 'Close'  END AS pistatus FROM m5_pi pi   JOIN m1_contact kc ON pi.picustomer = kc.kid  JOIN m1_contact ks ON pi.pibagianpenjualan = ks.kid  JOIN m5_pi_detail pid ON pi.piid = pid.idpi   JOIN m1_item b ON pid.idbarang = b.bid  LEFT JOIN m5_so_detail sod ON pid.idsodetail = sod.idsodetail  LEFT JOIN m5_sq_detail sqd ON pid.idsqdetail = sqd.idsqdetail  LEFT JOIN m5_pl_detail pld ON pid.idpldetail = pld.idpldetail  LEFT JOIN m5_do_detail dod ON pid.idpldetail = dod.iddodetail  LEFT JOIN m5_dr_detail drd ON pid.idpldetail = drd.iddrdetail ORDER BY pi.pinotransaksi, pid.urutan;

-- RID=110 | MENU=9 | ITEM=11 | RQUERY=1 | NAME=Daftar Invoice Sementara (PI) Per Produk | FILE=listproformainvoice_perproduk
SELECT    b.bid , b.bkode , pid.namabarang ,   pi.pinotransaksi , pi.pitgl , kc.knama AS picustomer , ks.knama AS pibagianpenjualan , SUM(pid.jml) AS jml ,   	pid.satuan ,   	pid.diskon ,   	pid.harga ,   	SUM((pid.jml * pid.harga) - pid.jmldiskon) AS total FROM m5_pi pi   JOIN m1_contact kc ON pi.picustomer = kc.kid  JOIN m1_contact ks ON pi.pibagianpenjualan = ks.kid  JOIN m0_status st ON pi.pistatus = st.kode    JOIN m5_pi_detail pid ON pi.piid = pid.idpi  JOIN m1_item b ON pid.idbarang = b.bid GROUP BY pid.idbarang, b.bid, b.bkode, pid.namabarang, pid.satuan, pid.harga , pid.idpi ORDER BY pid.idbarang , b.bid, b.bkode , pid.namabarang;

-- RID=741 | MENU=9 | ITEM=12 | RQUERY=1 | NAME=Invoice Sementara (PI) 1 Letter | FILE=proformainvoicedetail2
SELECT    	pi.piid,   	pi.pinotransaksi ,   	pi.pitgl ,   	kc.knama AS picustomer,   	ks.knama AS pibagianpenjualan,   	st.nama AS pistatus,   	pi.pimatauang ,   	pi.pikurs ,   	pi.pidiskonpersen ,   	pi.pijmldiskon ,   	pi.pibiayalain ,   	pi.pitotalpajak1detail,   	pi.piuraian ,     	b.bkode ,   	pid.namabarang ,   	so.sonotransaksi ,   	pid.catatan,   	pid.jml ,   	pid.satuan ,   	pid.diskon ,   	pid.harga ,   	((pid.jml * pid.harga) - pid.jmldiskon) AS total FROM m5_pi pi   JOIN m1_contact kc ON pi.picustomer = kc.kid  JOIN m1_contact ks ON pi.pibagianpenjualan = ks.kid  JOIN m0_status st ON pi.pistatus = st.kode    JOIN m5_pi_detail pid ON pi.piid = pid.idpi  JOIN m1_item b ON pid.idbarang = b.bid    LEFT JOIN m5_so_detail sod ON pid.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid ORDER BY pi.pitgl, pi.piid, pi.pinotransaksi , pid.urutan;

-- RID=1692 | MENU=9 | ITEM=13 | RQUERY=1 | NAME=Daftar Invoice Sementara (PI) Global | FILE=listproformainvoice2
SELECT    	pi.piid,   	pi.pinotransaksi ,   	pi.pitgl ,   	kc.knama AS picustomer,   	ks.knama AS pibagianpenjualan,   	st.nama AS pistatus,   	pi.pimatauang ,   	pi.pikurs ,   	pi.pidiskonpersen ,   	pi.pijmldiskon ,   	pi.pibiayalain ,   	pi.pitotalpajak1detail,     	b.bkode ,   	pid.namabarang ,   	so.sonotransaksi ,   	pid.catatan,   	pid.jml ,   	pid.satuan ,   	pid.diskon ,   	pid.harga ,   	((pid.jml * pid.harga) - pid.jmldiskon) AS total FROM m5_pi pi   JOIN m1_contact kc ON pi.picustomer = kc.kid  JOIN m1_contact ks ON pi.pibagianpenjualan = ks.kid  JOIN m0_status st ON pi.pistatus = st.kode    JOIN m5_pi_detail pid ON pi.piid = pid.idpi  JOIN m1_item b ON pid.idbarang = b.bid    LEFT JOIN m5_so_detail sod ON pid.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid ORDER BY pi.pitgl, pi.piid, pi.pinotransaksi , pid.urutan;

-- RID=1706 | MENU=9 | ITEM=14 | RQUERY=1 | NAME=Invoice Sementara (PI) Surat Jalan 1 Letter | FILE=proformainvoicedetaildo2
SELECT    pi.pitgl ,   pi.pinotransaksi ,   st.nama AS pistatus ,   kc.knama AS picustomer,   ks.knama AS pibagianpenjualan ,   w.wnama AS pigudang ,   pi.piuraian ,     b.bkode ,   pid.namabarang ,   pid.jml ,   pid.satuan ,   pid.catatan ,     ilw.blgnamalokasi FROM m5_pi pi   JOIN m0_status st ON pi.pistatus = st.kode  JOIN m1_contact ks ON pi.pibagianpenjualan = ks.kid  JOIN m1_warehouse w ON pi.pigudang = w.wkode   JOIN m5_pi_detail pid ON pi.piid = pid.idpi   JOIN m1_item b ON pid.idbarang = b.bid  LEFT JOIN m1_contact kc ON pi.picustomer = kc.kid   LEFT JOIN m1_item_location_warehouse ilw ON pid.idbarang = ilw.blgidbarang AND pid.gudang = ilw.blggudang ORDER BY pi.pitgl , pi.piid , pi.pinotransaksi , pid.urutan;

-- RID=1707 | MENU=9 | ITEM=15 | RQUERY=1 | NAME=Invoice Sementara (PI) Invoice 1 Letter | FILE=proformainvoicedetailsi2
SELECT    pi.pitgl,   pi.pinotransaksi ,   pi.pimatauang ,   st.nama AS pistatus ,   kc.knama AS picustomer ,   pi.pitermin ,   pi.piuraian ,     b.bkode ,   pid.namabarang ,   pid.jml ,   pid.satuan ,   pid.harga ,   pid.diskon ,   ((pid.jml * pid.harga) - pid.jmldiskon) AS total ,   so.sonotransaksi ,     pi.pijmldiskon ,   pi.picustomdbl2,   pi.pitotalpajak1detail ,   pi.pibiayalain FROM m5_pi pi  JOIN m0_status st ON pi.pistatus = st.kode  JOIN m1_contact kc ON pi.picustomer = kc.kid    JOIN m5_pi_detail pid ON pi.piid = pid.idpi  JOIN m1_item b ON pid.idbarang = b.bid     LEFT JOIN m5_so_detail sod ON pid.idsodetail = sod.idsodetail   LEFT JOIN m5_so so ON sod.idso = so.soid ORDER BY pi.pitgl , pi.piid , pi.pinotransaksi, pid.urutan;

-- RID=1708 | MENU=9 | ITEM=16 | RQUERY=1 | NAME=Invoice Sementara (PI) Valas 1 Letter | FILE=proformainvoicedetail_valas2
SELECT    	pi.piid,   	pi.pinotransaksi ,   	pi.pitgl ,   	kc.knama AS picustomer,   	kc.k1alamat1 ,   	ks.knama AS pibagianpenjualan,   	st.nama AS pistatus,   	pi.pimatauang ,   	pi.pikurs ,   	pi.pidiskonpersen ,   	pi.pijmldiskon ,   	pi.pibiayalain ,   	pi.pitotalpajak1detail,   	pi.piuraian ,     	b.bkode ,   	pid.namabarang ,   	so.sonotransaksi ,   	pid.catatan,   	pid.jml ,   	pid.satuan ,   	pid.diskon ,   	pid.harga ,   	(pid.harga * pid.kurs) AS hargavalas ,   	((pid.jml * pid.harga) - pid.jmldiskon) AS total ,   ((pid.jml * (pid.harga * pid.kurs)) - (pid.jmldiskon * pid.kurs)) AS totalvalas ,   usr.unama FROM m5_pi pi   JOIN m1_contact kc ON pi.picustomer = kc.kid  JOIN m1_contact ks ON pi.pibagianpenjualan = ks.kid  JOIN m0_status st ON pi.pistatus = st.kode  JOIN m5_pi_detail pid ON pi.piid = pid.idpi  JOIN m1_item b ON pid.idbarang = b.bid  JOIN m0_user usr ON pi.piinputuser = usr.userid  LEFT JOIN m5_so_detail sod ON pid.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid WHERE (pi.pimatauang <> "IDR" AND pi.pimatauang <> "RP" ) ORDER BY pi.pitgl, pi.piid, pi.pinotransaksi , pid.urutan;

-- RID=50001663 | MENU=9 | ITEM=17 | RQUERY=1 | NAME=Transaksi PI | FILE=Report(pi)
piid,picabang,pilokasi,pigudang,piasalbarang,piasalbarangkategori,pijenispenjualan,pijenispenjualankategori,  picarabayar,pisumber,piautonotransaksi,pinotransaksi,pitgl,pikodepa,picustomer,picustomerkontak,pi1alamat1,  pi1alamat2,pi1alamat3,pi2alamat1,pi2alamat2,pi2alamat3,pibagianpenjualan,piekspedisi,pitglkirim,pitermin,  pitgljatuhtempo,piuraian,picatatan,pinoref,pitglpenutupan,pimatauang,pikurs,pihargatermasukpajak,pitotal,  pidiskonpersen,pijmldiskon,pitotalpajak1detail,pitotalpajak2detail,pibiayalainpersen,pibiayalain,pitotaltransaksi,  pijmlbayar,pirekdiskon,pirekpajak1,pirekpajak2,pirekbiayalain,pirekbayar,piidsq,piidso,pistatuspl,pistatusdo,  pistatusdr,pistatussi,pistatussr,pistatusrealisasi,pistatus,pistatussebelumnya,pijmlrevisi,picetakanke,  piinputuser,piinputtgl,pimodifikasiuser,pimodifikasitgl,piposting,pipostingtgl,piisclose,pitutupperiode,  picustomtext1,picustomtext2,picustomtext3,picustomtext4,picustomtext5,picustomint1,picustomint2,picustomint3,  picustomdbl1,picustomdbl2,picustomdbl3,picustomdate1,picustomdate2,picustomdate3,idpidetail,idpi,idbarang,  namabarang,tipebarang,jml,satuan,nilaisatuan,jmlbarang,satuanbarang,matauang,kurs,harga,diskon,jmldiskon,pajak1,  jmlpajak1,pajak2,jmlpajak2,cabang,lokasi,gudang,costcenter,divisi,subdivisi,proyek,catatan,urutan,idsqdetail,idsodetail,  jmlpl,statuspl,jmldo,statusdo,jmldr,statusdr,jmlsi,statussi,jmlrnr,statusrnr,jmlsr,statussr,jmlrealisasi,statusrealisasi,  isclose FROM m5_pi pi  JOIN m5_pi_detail pid ON pi.piid = pid.idpi ORDER BY pi.pitgl ASC,pi.pitgl ASC, pid.idpidetail ASC;

-- RID=166 | MENU=10 | ITEM=1 | RQUERY=1 | NAME=Daftar Invoice Penjualan (SI) Global | FILE=listsalesinvoice
SELECT  	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,     	'' as kode ,   	'' as namabarang ,   	'' as catatan ,   	sum(sid.jml) as jml ,   	sid.satuan as satuan ,   	0 as harga ,   	0 as diskon ,   	si.sitotal AS total FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode  JOIN m5_si_detail sid ON si.siid = sid.idsi GROUP BY si.sitgl ,si.sinotransaksi , si.siid ORDER BY si.sitgl ,si.sinotransaksi , si.siid;

-- RID=462 | MENU=10 | ITEM=2 | RQUERY=1 | NAME=Daftar Invoice Penjualan (SI) 1 | FILE=listsalesinvoice1
SELECT    	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail   FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode ORDER BY si.sitgl , si.siid, si.sinotransaksi;

-- RID=562 | MENU=10 | ITEM=3 | RQUERY=1 | NAME=Daftar Invoice Penjualan (SI) Detail | FILE=listsalesinvoice2
SELECT	  	si.sitgl ,   	si.sinotransaksi ,   	IFNULL(do2.donotransaksi,do1.donotransaksi) AS donotransaksi,  IFNULL(IFNULL(so2.sonotransaksi,so1.sonotransaksi),so3.sonotransaksi) AS sonotransaksi,  si.sicabang, si.silokasi,  si.sigudang,  	kc.kkode AS kodecustomer,  	kc.knama AS sicustomer ,   	kc.kkategoricustomer,  	ks.kkode AS kodesalesman,  	ks.knama AS sibagianpenjualan  ,   	st.nama AS sistatus ,  	si.sinofakturpajak,  	si.sitermin,  	si.sitgljatuhtempo,  	si.siuraian ,  	si.sinoref,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,     si.sicustomerkontak as driver,    	b.bkode ,   	sid.namabarang ,    b.bkategori, b.btipe, b.bdivisi,  	sid.catatan ,    IFNULL(IFNULL(sod2.jml,sod1.jml),sod3.jml) AS jmlSO,    	IFNULL(dod2.jml,dod1.jml) AS jmlDO,  	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	sid.jmldiskon,  	((sid.jml * sid.harga) - sid.jmldiskon) AS total,  	sid.pajak1, sid.jmlpajak1,  	sid.pajak2, sid.jmlpajak2,  sid.divisi,  sid.subdivisi,  sid.proyek,  sid.catatan,  	b.brekpersediaan,  	b.brekpenjualan,  	b.brekhargapokok,  	kc.krekpiutang,    dr1.drnotransaksi, si.si1alamat1, si1alamat2, si2alamat1, si2alamat2, sinoref, siekspedisi, sitglnoref,   CASE WHEN IFNULL(srd.idsrdetail,0) <> 0 THEN sr.srnotransaksi ELSE '' END as srnotransaksi,  IFNULL(IFNULL(so1.sojenispenjualankategori,so2.sojenispenjualankategori),so3.sojenispenjualankategori) as proyeksiprofit ,  b.baoem as kadar FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid    LEFT JOIN m5_dr_detail drd1 ON drd1.iddrdetail = sid.iddrdetail  LEFT JOIN m5_dr dr1 ON dr1.drid = drd1.iddr    LEFT JOIN m5_do_detail dod1 ON dod1.iddodetail = sid.iddodetail  LEFT JOIN m5_do do1 on do1.doid = dod1.iddo    LEFT JOIN m5_so_detail sod1 ON sod1.idsodetail = dod1.idsodetail  LEFT JOIN m5_so so1 on so1.soid = sod1.idso    LEFT JOIN m5_do_detail dod2 ON dod2.iddodetail = drd1.iddodetail  LEFT JOIN m5_do do2 on do2.doid = dod2.iddo    LEFT JOIN m5_so_detail sod2 ON sod2.idsodetail = dod2.idsodetail  LEFT JOIN m5_so so2 on so2.soid = sod2.idso    LEFT JOIN m5_so_detail sod3 ON sod3.idsodetail = sid.idsodetail   LEFT JOIN m5_so so3 on so3.soid = sod3.idso    LEFT JOIN m5_sr sr ON si.siid = sr.sridsi AND sr.srstatus IN(2,3,4,7)  LEFT JOIN m5_sr_detail srd ON sr.srid = srd.idsr AND sid.idbarang = srd.idbarang GROUP BY si.sitgl , si.sinotransaksi , si.siid, sid.urutan, sid.idsidetail ORDER BY si.sitgl , si.sinotransaksi , si.siid, sid.urutan, sid.idsidetail;

-- RID=167 | MENU=10 | ITEM=4 | RQUERY=1 | NAME=Daftar Invoice Penjualan (SI) Outstanding | FILE=listsalesinvoiceoutstanding
SELECT    	si.siid ,   	si.sitgl ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	st.nama AS sistatus ,  	si.siuraian ,  kc.kcustomtext4 as instruksi,  si.sicustomerkontak,  	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan  ,   (sid.jmlrealisasi / sid.nilaisatuan) AS jmlrealisasi ,   (sid.jml - (sid.jmlrealisasi / sid.nilaisatuan)) AS jmlsisa ,   sid.idbarang,  si.sikurs ,   si.simatauang ,     dr.drnotransaksi ,   doo.donotransaksi ,   soo.sonotransaksi,  sid.harga ,     sid.harga * sid.jml AS hargajml,   (sid.jmlrealisasi / sid.nilaisatuan) * (sid.harga - (sid.jmldiskon / sid.jml)) AS hargajmlrealisasi ,   (sid.jml - (sid.jmlrealisasi / sid.nilaisatuan)) * (sid.harga - (sid.jmldiskon / sid.jml)) AS hargajmlsisa ,  b.bdivisi FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid    LEFT JOIN m5_dr_detail drd ON sid.iddrdetail = drd.iddrdetail   LEFT JOIN m5_dr dr ON drd.iddr = dr.drid    LEFT JOIN m5_do_detail dod ON drd.iddodetail = dod.iddodetail  LEFT JOIN m5_do doo ON dod.iddo = doo.doid     LEFT JOIN m5_so_detail sod ON sid.idsodetail = sod.idsodetail  LEFT JOIN m5_so soo ON sod.idso = soo.soid ORDER BY si.sicustomerkontak, si.sitgl , si.siid, si.sinotransaksi , sid.urutan;

-- RID=176 | MENU=10 | ITEM=5 | RQUERY=1 | NAME=Sales Invoice (SI) 1/2 Letter | FILE=salesinvoicedetail1_new
SELECT    f_nominal(si.sitotaltransaksi, si.simatauang) AS terbilang,   CASE sid.iddodetail 	WHEN 0 THEN `do`.donotransaksi 	ELSE do2.donotransaksi END AS donotransaksi ,    si.sihargatermasukpajak ,   CASE si.sihargatermasukpajak  	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS "caption" ,     si.sicustomtext1 ,   	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	CONCAT(kc.k1alamat1,   (CASE WHEN LENGTH(kc.k2alamat1) > 0 THEN "\n" ELSE "" END) ,kc.k2alamat1,  (CASE WHEN LENGTH(kc.k1kota) > 0 OR LENGTH(kc.k1kodepos) > 0 THEN "\n" ELSE "" END) ,kc.k1kota," ",kc.k1kodepos) as si1alamat1 ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,   si.sitotalpajak2detail ,   si.sitotaltransaksi ,   	si.sijmluangmuka ,   	si.sitermin ,   si.sitgljatuhtempo ,   	si.sicustomdbl2,  	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,      sid.jmldiskon,     	((sid.jml * sid.harga)) AS total,  CASE si.sihargatermasukpajak  WHEN 0 THEN ROUND(si.sitotal * 11/12)  ELSE ROUND((si.sitotal - si.sitotalpajak1detail) * 11/12)  END as totallain,  si.sicatatan ,   si.sinoref,  sf.sfnotransaksi FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid    LEFT JOIN m5_dr_detail drd ON sid.iddrdetail = drd.iddrdetail   LEFT JOIN m5_do_detail dod ON drd.iddodetail = dod.iddodetail  LEFT JOIN m5_do_detail dod2 ON sid.iddodetail = dod2.iddodetail  LEFT JOIN m5_do `do` ON dod.iddo = `do`.doid  LEFT JOIN m5_do `do2` ON dod2.iddo = `do2`.doid    LEFT JOIN m5_so_detail sod on sid.idsodetail = sod.idsodetail  LEFT JOIN m5_so so on so.soid = sod.idso  LEFT JOIN m5_sf sf on so.socustomdbl1 = sf.sfid ORDER BY si.sitgl , si.siid, si.sinotransaksi , sid.urutan;

