-- RID=170 | MENU=10 | ITEM=21 | RQUERY=1 | NAME=Daftar Invoice Penjualan (SI) Rupiah | FILE=listsalesinvoicerupiah
SELECT  	si.sinotransaksi,  	si.sitgl,  	si.siuraian,  	b.bkode AS kodebarang,  	(sid.harga * si.sikurs) AS harga,  	sid.namabarang,  	sid.tipebarang,  	kc.knama AS customer,  	ks.knama AS selesman,  	sid.jmlsr,  	si.simatauang,  	(sid.jml - sid.jmlsr) AS iv_sr,  	((sid.harga * sid.jml)* si.sikurs) AS total,  	((sid.harga * sid.jml)* si.sikurs) - (sid.jmldiskon - si.sikurs) AS ttl,  	si.sitotaltransaksi, sid.jmldiskon, sid.diskon,  	sid.jml,   	sid.satuan,  	(CASE sistatusrnr  	WHEN 1 THEN 'Sudah'  	WHEN 0 THEN 'Belum'  END) AS ODdiAR,  (CASE sistatuslunas  	WHEN 1 THEN 'Sudah'  	WHEN 0 THEN 'Belum'  END) AS ODdiEX,  (CASE sistatussr  	WHEN 'B' THEN 'Belum'  	WHEN 'P' THEN 'Proses'  	WHEN 'S' THEN 'Selesai'  END) AS status   FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b ON sid.idbarang = b.bid  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid   ORDER BY si.sinotransaksi, sid.urutan;

-- RID=171 | MENU=10 | ITEM=22 | RQUERY=1 | NAME=Daftar Invoice Penjualan (SI) Kontan | FILE=listsalesinvoicecashsales
SELECT  	si.sinotransaksi,   	sid.urutan,  	si.sitgl,  	si.siuraian,    	kc.knama,   	ks.knama AS salesman,   	b.bkode,   	sid.catatan,  	sid.tipebarang,   	sid.namabarang,   	sid.jml,   	sid.satuan,   	sid.harga,   	(sid.jml * sid.harga) AS total,  	((sid.jml * sid.harga) -  sid.jmldiskon) AS ttl,  	si.sitotaltransaksi, sid.jmldiskon, sid.diskon FROM m5_si si   JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b ON sid.idbarang = b.bid    ORDER BY si.sinotransaksi, sid.urutan;

-- RID=172 | MENU=10 | ITEM=23 | RQUERY=1 | NAME=Tanda Terima Invoice Penjualan (SI) | FILE=salesinvoicereceipt1
SELECT  sid.urutan,  si.sinotransaksi,  si.sitgl,  si.sistatus,  b.bkode AS kodebarang,  sid.namabarang,   sid.tipebarang,  si.sicustomerkontak,  ks.knama,  SUM(sid.jml) AS jml,  sid.satuan,  si.si2alamat1 AS alamatantar,   so.sonotransaksi FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi   JOIN m1_item b ON sid.idbarang = b.bid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  LEFT JOIN m5_so_detail sod ON sid.idsodetail = sod.idsodetail   LEFT JOIN m5_so so ON sod.idso = so.soid GROUP BY si.sinotransaksi, b.bkode, sid.tipebarang, sid.namabarang, sid.satuan, so.sonotransaksi ORDER BY si.sinotransaksi, sid.urutan;

-- RID=174 | MENU=10 | ITEM=24 | RQUERY=1 | NAME=Sales Invoice (SI) Rupiah | FILE=salesinvoicerupiahdetail1
SELECT  	si.siid,  	si.sinotransaksi,  	si.sicatatan,  	si.sitgl,  	si.simatauang,  	si.si1alamat1 AS sialamat,  	sid.namabarang,   	sid.tipebarang,  	sid.satuan,  	so.sonotransaksi,  	u.unama,  	b.bid,  	b.bkode,  	kc.knama AS customer,  	ks.knama AS salesman,  	SUM(sid.jml) AS asjml,  	(sid.harga * si.sikurs) AS asharga,  	SUM((sid.harga * si.sikurs) * sid.jml) AS hsl,  	SUM(((sid.harga * si.sikurs) * sid.jml) - (sid.jmldiskon * si.sikurs))AS astotal,  	f_nominal (si.sitotal , sid.matauang) AS terbilang,  	(si.sitotalpajak1detail * si.sikurs) AS asttlpajak,  	sid.diskon,  	SUM(sid.jmldiskon * si.sikurs) AS asjmldiskon,  	sid.urutan FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi  LEFT JOIN m5_so_detail sod ON sid.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid   JOIN m1_item b ON sid.idbarang = b.bid  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_user u ON si.siinputuser = u.userid GROUP BY si.sinotransaksi, b.bkode, sid.tipebarang, sid.namabarang, sid.satuan, asharga ORDER BY si.sinotransaksi, sid.urutan;

-- RID=265 | MENU=10 | ITEM=25 | RQUERY=1 | NAME=Invoice Penjualan (SI) Valas | FILE=salesinvoicedetailvalas
SELECT  	sid.urutan,  	si.sinotransaksi,  	si.sicustomerkontak,  	si.sitgl,  	u.unama,  	si.simatauang,  	b.bkode,  	sid.namabarang,   	sid.tipebarang,  	kc.knama AS customer,  	ks.knama,  	SUM(sid.jml) AS jml,  	sid.satuan,  	sid.harga,  	si.si1alamat1 AS sialamat,  	sid.diskon,  	si.sicatatan,  	SUM((sid.harga * sid.jml)- sid.jmldiskon) AS total,  	(sid.harga * sid.kurs) AS hargavalas,  	SUM(sid.jml * (sid.harga * sid.kurs) - (sid.jmldiskon * sid.kurs)) AS totalvalas,  	si.sikurs,  	sid.kurs	 FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi   JOIN m1_item b ON sid.idbarang = b.bid  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_user u ON si.siinputuser = u.userid  LEFT JOIN m5_so_detail sod ON sid.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid WHERE (si.simatauang <> "IDR") GROUP BY si.sinotransaksi, b.bkode, sid.tipebarang, sid.namabarang, sid.satuan, sid.harga ORDER BY si.sinotransaksi, sid.urutan;

-- RID=322 | MENU=10 | ITEM=26 | RQUERY=1 | NAME=SI Terkait RNR dan SR | FILE=siterkaitrnrsr
SELECT  	sid.idsidetail,  	rnrd.idsidetail AS rnr,  	si.sinotransaksi,  	si.sitgl,  	sid.jml,  	sid.satuan,  	sid.namabarang,  	sid.tipebarang,  	b.bkode,  	ks.knama,  	rnr.rnrnotransaksi,  	rnr.rnrtgl,  	rnrd.jml AS asjmlrnr,  	rnrd.satuan AS assatuanrnr,  	sr.srnotransaksi,  	sr.srtgl,  	srd.jml AS asjmlsr,  	srd.satuan AS assatuansr FROM m5_si si  JOIN m5_si_detail sid ON sid.idsi = si.siid  JOIN m1_contact ks ON ks.kid = si.sibagianpenjualan  JOIN m1_item b ON sid.idbarang = b.bid  LEFT JOIN m5_rnr_detail rnrd ON sid.idsidetail = rnrd.idsidetail  JOIN m5_rnr rnr ON rnr.rnrid = rnrd.idrnr  LEFT JOIN m5_sr_detail srd ON srd.idrnrdetail = rnrd.idrnrdetail AND rnrd.idbarang  JOIN m5_sr sr ON srd.idsr = sr.srid GROUP BY si.sinotransaksi, rnr.rnrnotransaksi, sr.srnotransaksi ORDER BY si.sinotransaksi, rnr.rnrnotransaksi, sr.srnotransaksi, sid.urutan;

-- RID=168 | MENU=10 | ITEM=27 | RQUERY=1 | NAME=Daftar Invoice Penjualan (SI) Outstanding Sisa | FILE=listsalesinvoiceresidueoutstanding
SELECT  si.sinotransaksi,  si.sitgl,  si.siuraian,  si.sitermin,  ((sid.jml) - IFNULL(sod.jml,0)) AS jmlso,  ((sid.jml) - IFNULL(sqd.jml,0)) AS jmlsq,  ((sid.jml) - IFNULL(pld.jml,0)) AS jmlpl,  ((sid.jml) - IFNULL(dod.jml,0)) AS jmldo,  ((sid.jml) - IFNULL(drd.jml,0)) AS jmldr,  ((sid.jml) - IFNULL(pid.jml,0)) AS jmlpi,  sid.jml,  ((sid.jml) - IFNULL(sid.jmlrnr,0)) AS jmlrnr,  ((sid.jml) - IFNULL(sid.jmlsr,0)) AS jmlsr,  sid.satuan,  sid.catatan,  b.bkode,  sid.namabarang,  sid.tipebarang,  kc.knama AS customer,  ks.knama AS salesman FROM m5_si si  JOIN m5_si_detail sid ON si.siid = sid.idsi   JOIN m1_item b ON sid.idbarang = b.bid  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  LEFT JOIN m5_so_detail sod ON sid.idsodetail = sod.idsodetail  LEFT JOIN m5_sq_detail sqd ON sid.idsqdetail = sqd.idsqdetail  LEFT JOIN m5_pl_detail pld ON sid.idpldetail = pld.idpldetail  LEFT JOIN m5_do_detail dod ON sid.iddodetail = dod.iddodetail  LEFT JOIN m5_dr_detail drd ON sid.iddrdetail = drd.iddrdetail  LEFT JOIN m5_pi_detail pid ON sid.idpidetail = pid.idpidetail ORDER BY si.sinotransaksi, sid.urutan;

-- RID=169 | MENU=10 | ITEM=28 | RQUERY=1 | NAME=Daftar Invoice Penjualan (SI) Per Produk | FILE=listsalesinvoice_perproduk
SELECT    si.sitgl ,   	si.sinotransaksi ,   	kc.kkode AS kodecustomer,  	kc.knama AS sicustomer ,   	ks.kkode AS kodesalesman,  	ks.knama AS sibagianpenjualan  ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,     	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	sid.jmldiskon,  	((sid.jml * sid.harga) - sid.jmldiskon) AS total,  	sid.pajak1, sid.jmlpajak1,  	sid.pajak2, sid.jmlpajak2,  	kc.krekpiutang,  	kc.kkategoricustomer,  	si.sinofakturpajak,  	si.sitermin,  	si.sitgljatuhtempo,  	b.brekpersediaan,  	b.brekpenjualan,  	b.brekhargapokok FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid GROUP BY sid.idbarang, b.bid, b.bkode, sid.namabarang, sid.satuan, sid.idsi ORDER BY sid.idbarang, b.bid, b.bkode , sid.namabarang;

-- RID=779 | MENU=10 | ITEM=29 | RQUERY=1 | NAME=Sales Invoice (SI) Batch 1/2 Letter | FILE=salesinvoicedetail1_new_batch
