SELECT    	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan ,   	si.siuraian ,     	b.bkode ,   	sid.namabarang ,   	so.sonotransaksi ,   	sid.jml, b.bsatuan ,   	sid.harga ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total  ,    	si.sijmldiskon ,   	si.sitotalpajak1detail ,   	si.sibiayalain ,     	si.sicatatan ,     	si.sijmluangmuka FROM m5_si si   JOIN m1_contact kc ON  si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b ON sid.idbarang = b.bid  LEFT JOIN m5_so_detail sod ON sid.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid   ORDER BY si.sinotransaksi , sid.urutan;

-- RID=1089 | MENU=10 | ITEM=36 | RQUERY=1 | NAME=Invoice Penjualan Penyusun | FILE=SIpenyusunGlobal
SELECT    	si.siid , sid.idsidetail ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,     	sid.idbarang ,   	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid ORDER BY si.sitgl ,si.sinotransaksi , sid.urutan;

-- RID=1090 | MENU=10 | ITEM=37 | RQUERY=1 | NAME=Invoice Penjualan Penyusun 1/2 Letter | FILE=SIpenyusunDetail
SELECT    	si.siid , sid.idsidetail ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail, si.sijmluangmuka ,   	si.sitermin ,   	si.sicustomdbl2,  	si.sicatatan ,     	sid.idbarang ,   	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total ,   	si.si1alamat1 FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid ORDER BY si.sitgl ,si.sinotransaksi , sid.urutan;

-- RID=1091 | MENU=10 | ITEM=38 | RQUERY=1 | NAME=Invoice Penjualan Penyusun 1 Letter | FILE=SIpenyusunDetail2
SELECT    	si.siid , sid.idsidetail ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail, si.sijmluangmuka ,   	si.sitermin ,   	si.sicustomdbl2,  	si.sicatatan ,     	sid.idbarang ,   	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total ,   	si.si1alamat1 FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid ORDER BY si.sitgl ,si.sinotransaksi , sid.urutan;

-- RID=1108 | MENU=10 | ITEM=39 | RQUERY=1 | NAME=Sales Invoice (SI) Penjualan Kredit | FILE=salesinvoicedetail2_penjualanKredit_BAJA
SELECT    f_nominal((SELECT  sum(sidd.jml * sidd.harga)   					FROM m5_si_detail sidd  					WHERE si.siid = sidd.idsi  					GROUP BY sidd.idsi  						) ,si.simatauang) AS test ,     	si.sitgljatuhtempo ,   	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	kc.k1alamat1 ,   	si.sicustomerkontak ,   	ks.knama AS sibagianpenjualan  ,   	si.si1alamat1 ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,   	si.sijmluangmuka ,   	si.sitermin ,   	si.sicustomdbl2,  	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	(sid.jml * sid.harga) AS total ,   	u.unama FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid    JOIN m0_user u ON si.siinputuser = u.userid ORDER BY si.sitgl , si.siid, si.sinotransaksi , sid.urutan;

-- RID=1109 | MENU=10 | ITEM=40 | RQUERY=1 | NAME=Sales Invoice (SI) Penjualan Tunai | FILE=salesinvoicedetail1_BAJA
SELECT    	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	si.sicustomerkontak ,   	ks.knama AS sibagianpenjualan  ,   	si.si1alamat1 ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,   	si.sijmluangmuka ,   	si.sitermin ,   	si.sicustomdbl2,  	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	(sid.jml * sid.harga) AS total FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid ORDER BY si.sitgl , si.siid, si.sinotransaksi , sid.urutan;

-- RID=1165 | MENU=10 | ITEM=42 | RQUERY=1 | NAME=Penjualan Unit | FILE=SIpertokoan
SELECT    k.kkategoricustomer ,cc.ccnama ,     si.sicarabayar , pm.nama ,   SUM(si.sitotaltransaksi) AS sitotaltransaksi FROM m5_si si  JOIN m1_contact k ON si.sicustomer = k.kid   JOIN m1_customer_category cc ON k.kkategoricustomer = cc.cckode  LEFT JOIN m0_payment_method pm ON si.sicarabayar = pm.kode GROUP BY k.kkategoricustomer , si.sicarabayar ORDER BY k.kkategoricustomer , si.sicarabayar;

-- RID=1166 | MENU=10 | ITEM=43 | RQUERY=1 | NAME=Penjualan  | FILE=laporanpenjualan
SELECT    si.sitgl , si.sinotransaksi ,   si.sicarabayar ,   pm.nama ,   ic.icnama  ,   (((sid.jml * sid.harga) - sid.jmldiskon) + sid.jmlpajak1) AS jumlah ,   si.sijmldiskon , (si.sitotalpajak1detail + si.sibiayalain ) AS biayalain FROM m5_si si  JOIN m5_si_detail sid ON si.siid = sid.idsi   JOIN m1_item b ON sid.idbarang = b.bid   JOIN m1_item_category ic ON b.bkategori = ic.ickode   JOIN m0_payment_method pm ON si.sicarabayar = pm.kode ORDER BY si.sitgl , pm.nama , b.bkategori , ic.ickode;

-- RID=1167 | MENU=10 | ITEM=44 | RQUERY=1 | NAME=Penjualan Dan Ppn Keluaran | FILE=omzetppnkeluaran
SELECT    si.sitotaltransaksi ,   si.sitgl ,   (si.sitotaltransaksi - si.sitotalpajak1detail ) AS pajak ,   si.sitotalpajak1detail FROM m5_si si ORDER BY si.sitgl;

-- RID=1377 | MENU=10 | ITEM=45 | RQUERY=1 | NAME=Penjualan Per User | FILE=penjualanperuser
SELECT    si.siinputuser ,   u.unama ,   si.sicarabayar , pm.nama ,   SUM(si.sitotaltransaksi) AS sitotaltransaksi FROM m5_si si  JOIN m0_user u ON si.siinputuser = u.userid   LEFT JOIN m0_payment_method pm ON si.sicarabayar = pm.kode GROUP BY si.siinputuser , si.sicarabayar ORDER BY si.siinputuser, si.sicarabayar;

-- RID=1455 | MENU=10 | ITEM=46 | RQUERY=1 | NAME=Daftar Invoice Penjualan (SI) Rekap | FILE=listsalesinvoice_REKAP_KENAPAJAK2
SELECT    	b.bkp ,   	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,     	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.diskon ,     SUM(	CASE b.bkp   	WHEN 0 THEN 0   	WHEN 1 THEN (((sid.jml * sid.harga) - sid.jmldiskon) / 11)  END) as pajak ,     SUM(CASE b.bkp   	WHEN 0 THEN ((sid.jml * sid.harga) - sid.jmldiskon)  	WHEN 1 THEN ((((sid.jml * sid.harga) - sid.jmldiskon) / 11) * 10)  END) as harga FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid GROUP BY si.siid ORDER BY si.sitgl, si.siid, si.sinotransaksi ASC;

-- RID=1560 | MENU=10 | ITEM=47 | RQUERY=1 | NAME=Daftar Invoice Penjualan (SI) Rekap Kena Pajak | FILE=listsalesinvoice_REKAP_KENAPAJAK2
SELECT    	b.bkp ,   	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,     	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.diskon ,     SUM(	CASE b.bkp   	WHEN 0 THEN 0   	WHEN 1 THEN (((sid.jml * sid.harga) - sid.jmldiskon) / 11)  END) as pajak ,     SUM(CASE b.bkp   	WHEN 0 THEN ((sid.jml * sid.harga) - sid.jmldiskon)  	WHEN 1 THEN ((((sid.jml * sid.harga) - sid.jmldiskon) / 11) * 10)  END) as harga FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid WHERE (b.bkp = 1) GROUP BY si.siid ORDER BY si.sitgl, si.siid, si.sinotransaksi ASC;

-- RID=1457 | MENU=10 | ITEM=48 | RQUERY=1 | NAME=Daftar Invoice Penjualan (SI) Rekap Tidak Kena Pajak  | FILE=listsalesinvoice_REKAP_KENAPAJAK2
SELECT    	b.bkp ,   	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,     	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.diskon ,     SUM(	CASE b.bkp   	WHEN 0 THEN 0   	WHEN 1 THEN (((sid.jml * sid.harga) - sid.jmldiskon) / 11)  END) as pajak ,     SUM(CASE b.bkp   	WHEN 0 THEN ((sid.jml * sid.harga) - sid.jmldiskon)  	WHEN 1 THEN ((((sid.jml * sid.harga) - sid.jmldiskon) / 11) * 10)  END) as harga FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid WHERE (b.bkp = 0) GROUP BY si.siid ORDER BY si.sitgl, si.siid, si.sinotransaksi ASC;

-- RID=1456 | MENU=10 | ITEM=49 | RQUERY=1 | NAME=Daftar Invoice Penjualan (SI) Rekap Kena Pajak | FILE=listsalesinvoice1_pos4_kenapajak
SELECT    	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,     	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid WHERE (b.bkp = 1) ORDER BY si.sitgl , si.siid, si.sinotransaksi;

-- RID=1584 | MENU=10 | ITEM=50 | RQUERY=1 | NAME=Laporan Penjualan Per Hari | FILE=penjualanperhari
SELECT    	b.bnama AS sicabang ,   	l.lnama AS silokasi ,     	si.siid , sid.idsi , si.sinotransaksi ,   	si.sitgl,   	(((Sum((sid.jml * sid.harga) - sid.jmldiskon) - si.sijmldiskon) + si.sitotalpajak1detail) + si.sibiayalain) as totaltransaksi FROM m5_si si   JOIN  m5_si_detail sid ON si.siid = sid.idsi  LEFT JOIN  m1_branch b ON si.sicabang = b.bkode  LEFT JOIN  m1_location l ON si.silokasi = l.lkode AND si.sicabang = l.lcabang WHERE ((si.sistatus = 2) OR	(si.sistatus = 3) OR (si.sistatus = 4) OR (si.sistatus = 7) ) GROUP BY si.sicabang, si.silokasi, si.sitgl , si.siid ORDER BY si.sicabang, si.silokasi, si.sitgl , si.siid;

-- RID=1585 | MENU=10 | ITEM=51 | RQUERY=1 | NAME=Laporan Penjualan Per Lokasi | FILE=penjualanperlokasi
SELECT    	b.bnama AS sicabang ,   	  	si.siid , sid.idsi , si.sinotransaksi ,   	si.sitgl, si.silokasi , l.lnama ,   	((((Sum(sid.jml * sid.harga) - sid.jmldiskon) - si.sijmldiskon) + si.sitotalpajak1detail) + si.sibiayalain) as totaltransaksi ,   	l.lluas FROM m5_si si   JOIN  m5_si_detail sid ON si.siid = sid.idsi  LEFT JOIN  m1_branch b ON si.sicabang = b.bkode  LEFT JOIN  m1_location l ON si.silokasi = l.lkode AND si.sicabang = l.lcabang WHERE ((si.sistatus = 2) OR	(si.sistatus = 3) OR (si.sistatus = 4) OR (si.sistatus = 7) ) GROUP BY si.sicabang , si.silokasi , si.siid ORDER BY si.sicabang , si.silokasi , si.siid;

-- RID=1586 | MENU=10 | ITEM=52 | RQUERY=1 | NAME=Laporan Laba Rugi Per Hari | FILE=labarugiperhari
SELECT    	b.bnama AS sicabang ,   	l.lnama AS silokasi ,     	si.siid , sid.idsi , si.sinotransaksi ,   	si.sitgl,   	(((Sum((sid.jml * sid.harga) - sid.jmldiskon) - si.sijmldiskon) + si.sitotalpajak1detail) + si.sibiayalain) as totaltransaksi ,  	SUM(sid.jml * sid.hpp) AS hargapokok FROM m5_si si   JOIN  m5_si_detail sid ON si.siid = sid.idsi  LEFT JOIN  m1_branch b ON si.sicabang = b.bkode  LEFT JOIN  m1_location l ON si.silokasi = l.lkode AND si.sicabang = l.lcabang WHERE ((si.sistatus = 2) OR	(si.sistatus = 3) OR (si.sistatus = 4) OR (si.sistatus = 7) ) GROUP BY si.sicabang, si.silokasi, si.sitgl , si.siid ORDER BY si.sicabang, si.silokasi, si.sitgl , si.siid;

-- RID=1587 | MENU=10 | ITEM=53 | RQUERY=1 | NAME=Laporan Laba Rugi Per Lokasi | FILE=labarugiperlokasi
SELECT    	b.bnama AS sicabang ,   	l.lnama AS silokasi ,     	si.siid , sid.idsi , si.sinotransaksi ,   	si.sitgl,   	(((Sum((sid.jml * sid.harga) - sid.jmldiskon) - si.sijmldiskon) + si.sitotalpajak1detail) + si.sibiayalain) as totaltransaksi ,  	SUM(sid.jml * sid.hpp) AS hargapokok ,   	l.lluas FROM m5_si si   JOIN  m5_si_detail sid ON si.siid = sid.idsi  LEFT JOIN  m1_branch b ON si.sicabang = b.bkode  LEFT JOIN  m1_location l ON si.silokasi = l.lkode AND si.sicabang = l.lcabang WHERE ((si.sistatus = 2) OR	(si.sistatus = 3) OR (si.sistatus = 4) OR (si.sistatus = 7) ) GROUP BY si.sicabang, si.silokasi, si.siid ORDER BY si.sicabang, si.silokasi, si.siid;

-- RID=1709 | MENU=10 | ITEM=54 | RQUERY=1 | NAME=Daftar Invoice Penjualan (SI) Rekap Tidak Kena Pajak (GSA) | FILE=listsalesinvoice_REKAP_KENAPAJAK2_GSA
SELECT    	b.bkp ,   	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,     	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.diskon ,       CASE si.sihargatermasukpajak   	WHEN 0 THEN SUM(((sid.jml * sid.harga) - sid.jmldiskon))  	WHEN 1 THEN (SUM(((sid.jml * sid.harga) - sid.jmldiskon)) - si.sitotalpajak1detail)  END as harga ,    si.sitotalpajak1detail FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid GROUP BY si.siid ORDER BY si.sitgl, si.siid, si.sinotransaksi ASC;

-- RID=1710 | MENU=10 | ITEM=55 | RQUERY=1 | NAME=Invoice Penjualan (SI) Valas 1/2 Letter | FILE=salesinvoicedetail_valas1
SELECT    si.sihargatermasukpajak ,   CASE si.sihargatermasukpajak  	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS "caption" ,     a.anama ,   si.sicustomtext1 ,   	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	si.si1alamat1 ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,   	si.sijmluangmuka ,   	si.sitermin ,   	si.sicustomdbl2,  	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	(sid.harga * sid.kurs) AS hargavalas ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total,  	((sid.jml * (sid.harga * sid.kurs)) - (sid.jmldiskon * sid.kurs)) AS totalvalas,  	`do`.donotransaksi ,     si.sicatatan FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid  LEFT JOIN m5_do_detail dod ON sid.iddodetail = dod.iddodetail  LEFT JOIN m5_do `do` ON dod.iddo = `do`.doid    LEFT JOIN m1_area a ON si.sicustomtext1 = a.akode WHERE si.simatauang <> "IDR" AND si.simatauang <> "RP" ORDER BY si.sitgl , si.siid, si.sinotransaksi , sid.urutan;

-- RID=1711 | MENU=10 | ITEM=56 | RQUERY=1 | NAME=Invoice Penjualan (SI) Valas 1 Letter | FILE=salesinvoicedetail_valas2
