-- RID=747474 | MENU=10 | ITEM=74 | RQUERY=1 | NAME=Rekap Penjualan Per Salesman Per Barang | FILE=DaftarBarang_alamindo
SELECT    	k.kkode ,   	k.knama ,   	dp.dpnama ,   	sdp.sdpnama ,   	sid.tipebarang tipebarang,  	si.siid ,   	sid.idbarang ,   	b.bkode , b.bnama , SUM(sid.jml) AS jml , sid.satuan  , u.ukode , u.unilai ,   	SUM(sid.jml  * sid.nilaisatuan) AS tjml ,   	SUM(sid.jml   * sid.harga)-SUM(sid.jmldiskon) AS total,   	un.ukode AS kodeKRT , un.unilai AS nilaiKRT ,   (SUM(sid.jml * sid.nilaisatuan) - SUM(sid.jml * sid.nilaisatuan) MOD un.unilai) / un.unilai AS KRT ,   ((SUM(sid.jml * sid.nilaisatuan)-(SUM(sid.jml * sid.nilaisatuan) - SUM(sid.jml * sid.nilaisatuan) MOD un.unilai)) - (SUM(sid.jml * sid.nilaisatuan)-(SUM(sid.jml * sid.nilaisatuan) - SUM(sid.jml * sid.nilaisatuan) MOD un.unilai)) MOD 12) / 12  AS LSN ,   SUM(sid.jml * sid.nilaisatuan)-((SUM(sid.jml * sid.nilaisatuan) - SUM(sid.jml * sid.nilaisatuan) MOD un.unilai)+((SUM(sid.jml * sid.nilaisatuan)-(SUM(sid.jml * sid.nilaisatuan) - SUM(sid.jml * sid.nilaisatuan) MOD un.unilai)) - (SUM(sid.jml * sid.nilaisatuan)-(SUM(sid.jml * sid.nilaisatuan) - SUM(sid.jml * sid.nilaisatuan) MOD un.unilai)) MOD 12)) AS PCS     FROM m5_si si   JOIN m1_contact k ON si.sibagianpenjualan =  k.kid   JOIN m5_si_detail sid ON si.siid = sid.idsi   JOIN m1_item b ON sid.idbarang = b.bid   join m1_unit u on sid.satuan = u.ukode  LEFT JOIN m1_unit un ON b.bcustom2 = un.ukode    JOIN m1_department dp ON b.bdepartemen = dp.dpkode  JOIN m1_subdepartment sdp ON b.bsubdepartemen = sdp.sdpkode GROUP BY bdepartemen ASC , bsubdepartemen ASC, sibagianpenjualan ASC , sid.idbarang ORDER BY bdepartemen ASC , bsubdepartemen ASC, sibagianpenjualan ASC , sid.idbarang;

-- RID=757474 | MENU=10 | ITEM=75 | RQUERY=1 | NAME=Rekap Nota Per Salesman | FILE=rekap_nota_persales
SELECT    	d.dpnama AS bdepartemen ,   	k.kkode ,   	k.knama AS sibagianpenjualan ,   	si.sinotransaksi ,   	si.sitgl ,   	c.kkode AS kodecustomer , 	  	c.knama AS namacustomer ,   	c.k1alamat1 AS si1alamat1 ,     	((SUM(sid.jml * sid.harga) - SUM(sid.jmldiskon))) AS total FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b ON sid.idbarang = b.bid   JOIN m1_department d ON b.bdepartemen = d.dpkode   JOIN m1_contact k ON si.sibagianpenjualan = k.kid   JOIN m1_contact c ON si.sicustomer = c.kid GROUP BY b.bdepartemen , si.sibagianpenjualan , si.siid ORDER BY b.bdepartemen ASC, si.sibagianpenjualan ASC,((SUM(sid.jml * sid.harga) - SUM(sid.jmldiskon))) DESC;

-- RID=502120 | MENU=10 | ITEM=76 | RQUERY=1 | NAME=Penjualan Detail | FILE=testes
SELECT    	si.sihargatermasukpajak ,   	CASE si.sihargatermasukpajak  	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS "caption" ,     a.anama ,   si.sicustomtext1 ,   	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	si.si1alamat1 ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,   	si.sijmluangmuka ,   	si.sitermin ,   	si.sicustomdbl2,  	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	SUM(sid.jml) AS jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   SUM(sid.jmldiskon) AS jmldiskon ,   	SUM((sid.jml * sid.harga) - sid.jmldiskon) AS total,  	`do`.donotransaksi ,     si.sicatatan ,     CASE sid.satuan   	WHEN "GLN" THEN 1  	WHEN "LSN" THEN 2  	WHEN "Gram" THEN 3  END AS "UPCS" FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid  LEFT JOIN m5_do_detail dod ON sid.iddodetail = dod.iddodetail  LEFT JOIN m5_do `do` ON dod.iddo = `do`.doid    LEFT JOIN m1_area a ON si.sicustomtext1 = a.akode GROUP BY si.sitgl , si.siid, si.sinotransaksi , sid.idbarang , sid.satuan , sid.harga ORDER BY si.sitgl , si.siid, si.sinotransaksi , sid.urutan;

