-- RID=503333 | MENU=10 | ITEM=79 | RQUERY=1 | NAME=Data Nota Penjualan | FILE=NOTAPENJUALAN
SELECT sitgl TGL, sinotransaksi NOTRANSAKSI, c.kkode `KODE CUSTOMER`, c.knama `NAMA CUSTOMER`, c.k1alamat1 `ALAMAT`,  sid.namabarang `NAMA BARANG`,   sid.jmlbarang `JUMLAHPCS`, sid.jml `JUMLAH`, sid.satuan `SATUAN`, (harga-(jmldiskon/jml)) HRG_DISKON, (jml*(harga-(jmldiskon/jml))) AS SUBTOTAL FROM m5_si  JOIN m5_si_detail sid ON sid.idsi = siid  JOIN m1_item i ON i.bid = sid.idbarang  JOIN m1_contact c ON c.kid = sicustomer  JOIN m1_contact cs ON cs.kid = sibagianpenjualan ORDER BY siid DESC;

