tusrealisasi ,   isbonus , isbonusfrom , isclose FROM FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi ORDER BY si.sitgl ASC , si.siid ASC , sid.idsidetail ASC;

-- RID=50001765 | MENU=10 | ITEM=85 | RQUERY=1 | NAME=SURAT JALAN | FILE=salesinvoicedetail1_suratjalan_PCI
SELECT    si.sinotransaksi ,   si.sitgl ,   k.kkode ,   k.knama ,     b.bkode , b.bnama ,   sid.jml ,   sid.harga ,   sid.jml * sid.harga AS total ,   sid.satuan ,     sid.catatan ,     ks.kkode as kodesales,   ks.knama AS namasales ,     si.siuraian ,   si.sicatatan ,   si.sinoref FROM m5_si si  JOIN m5_si_detail sid ON si.siid = sid.idsi   JOIN m1_contact k ON si.sicustomer = k.kid  JOIN m1_item b ON sid.idbarang = b.bid   JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid ORDER BY si.sitgl ASC , si.siid ASC , sid.urutan ASC;

-- RID=50001768 | MENU=10 | ITEM=87 | RQUERY=1 | NAME=COMMERCIAL INVOICE (CIF) | FILE=SI_CI_PCI
SELECT  	si.siid,  	si.sinotransaksi ,   	si.sitgl ,   	si.sicustomtext1 as vessel,  	si.sicustomtext2 as originport,  	si.sicustomtext3 as destinationport,  	si.sicustomtext4 as bundleno,  	si.sicustomtext5 as marking,  	si.sicustomdbl2 as freight,  	si.sicustomdbl3 as insurance,  	si.siuraian,   	k.knama AS sicustomer ,   	si.si1alamat1 ,   	si.si2alamat1 ,   	si.siuraian as uraian,   	si.sicustomdate1 as etd,  	k.k1notelp1 as telp,  	k.k1nofax as fax,   case sicustomint4 when 0 then "CIF" when 1 then "CFR" else "FOB" END as tipecif,     	sid.namabarang as bnama ,   	sid.jml ,   	sid.harga ,   	sid.jml * sid.harga AS total,   	sid.customdbl4 as jmlbundle,  	sid.customtext4 as satuanbundle,  	sid.customdbl5 as grossweight,  	sid.customtext5 as measurement,  	sid.catatan as catatandetail,  	sid.matauang ,     	si.simatauang ,   	si.sitotalpajak1detail ,   	si.sibiayalain ,  	si.sijmldiskon ,   	si.sitotaltransaksi ,   	si.sicustomtext9 as catatan ,   	sf.sfnotransaksi, cr.csimbol,  	UPPER(f_nominal_english(sitotaltransaksi, simatauang)) AS terbilang,    k.kcatatan,    si.siekspedisi as unit,  	si.si1alamat3,  	si.sicustomtext7   FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi   JOIN m1_contact k ON si.sicustomer = k.kid   JOIN m1_item b ON sid.idbarang = b.bid   LEFT JOIN m5_sf sf on si.sicustomdbl1 = sf.sfid  left join m1_currency cr on si.simatauang = cr.ckode   WHERE bjenis = "P" ORDER BY si.sitgl ASC , si.siid ASC , sid.urutan ASC;

-- RID=50001770 | MENU=10 | ITEM=89 | RQUERY=1 | NAME=Shipping Advice | FILE=Shipping_Advice
SELECT    si.sinotransaksi ,   si.sitgl ,   si.sicustomtext2 AS vessel ,   si.sicustomtext3 AS alamatvessel ,   si.sicustomtext4 AS issuingbank ,   si.sicustomtext5 AS shipped,   si.sicustomtext6 AS LCNO,   si.sicustomtext7 AS NSC ,   si.siuraian AS WEHEREBY,   k.knama AS sicustomer ,   si.si1alamat1 ,   si.si2alamat1 ,   si.sicatatan ,     b.bnama ,   sid.jml ,   sid.harga ,   sid.jml * sid.harga AS total,   sid.matauang ,     si.sibiayalain ,   si.sitotaltransaksi ,   sid.catatan ,     f_nominal(si.sitotaltransaksi, si.simatauang) AS terbilang ,   si.simatauang FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi   JOIN m1_contact k ON si.sicustomer = k.kid   JOIN m1_item b ON sid.idbarang = b.bid ORDER BY si.sitgl ASC , si.siid ASC , sid.urutan ASC;

-- RID=50001773 | MENU=10 | ITEM=90 | RQUERY=1 | NAME=Beneficary Compliance Certificate | FILE=Beneficary Compliance Certificate
SELECT    si.sinotransaksi ,   si.sitgl ,   si.sicustomtext2 AS vessel ,   si.sicustomtext3 AS alamatvessel ,   si.sicustomtext4 AS issuingbank ,   si.sicustomtext5 AS shipped,   si.sicustomtext6 AS LCNO,   si.sicustomtext7 AS NSC ,   si.siuraian AS WEHEREBY,   k.knama AS sicustomer ,   si.si1alamat1 ,   si.si2alamat1 ,   si.sicatatan ,     b.bnama ,   sid.jml ,   sid.harga ,   sid.jml * sid.harga AS total,   sid.matauang ,     si.sibiayalain ,   si.sitotaltransaksi ,   sid.catatan ,     f_nominal(si.sitotaltransaksi, si.simatauang) AS terbilang ,   si.simatauang FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi   JOIN m1_contact k ON si.sicustomer = k.kid   JOIN m1_item b ON sid.idbarang = b.bid ORDER BY si.sitgl ASC , si.siid ASC , sid.urutan ASC;

-- RID=50001777 | MENU=10 | ITEM=91 | RQUERY=1 | NAME=Laporan Komisi Sales | FILE=laporankomisisales
SELECT    ks.kkode ,    ks.knama ,     si.sinotransaksi ,    SUBSTRING_INDEX( GROUP_CONCAT(pv.pvnotransaksi ORDER BY pv.pvtgl DESC,   pv.pvnotransaksi DESC, pv.pvid DESC, pvd.urutan DESC) ,',',1) as pvnotransaksi,   si.sitgl ,    si.sitgllunas as pvtgl,   kc.kkode AS custkode,    kc.knama custnama ,    si.simatauang,   si.sitotaltransaksi,    sidv.jml,   sid.satuan FROM m5_si si  JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m1_contact kc ON si.sicustomer = kc.kid   JOIN m5_si_detail_komisi_v sidv ON si.siid = sidv.idsi  LEFT JOIN m5_pv_detail pvd ON si.sisumber = pvd.sumber AND si.siid = pvd.idtransaksi  LEFT JOIN m5_pv pv ON pvd.idpv = pv.pvid   GROUP BY si.sibagianpenjualan ASC , si.sitgl ASC ,  si.sinotransaksi ASC ORDER BY si.sibagianpenjualan ASC , si.sitgl ASC ,  si.sinotransaksi ASC;

-- RID=50003770 | MENU=10 | ITEM=93 | RQUERY=1 | NAME=Surat Jalan (SI) 1/2 Letter DO | FILE=SI_DO
SELECT    si.siid ,   si.sinotransaksi ,   si.sitgl ,   kc.knama AS sicustomer ,   kc.k2alamat1 ,   ks.knama AS sibagianpenjualan ,   w.wnama AS sigudang ,   si.siuraian ,   st.nama AS sistatus ,   si.simatauang ,   si.sikurs ,   si.sicustomerkontak,   	CONCAT(kc.k1alamat1,   (CASE WHEN LENGTH(kc.k2alamat1) > 0 THEN "\n" ELSE "" END) ,kc.k2alamat1,  (CASE WHEN LENGTH(kc.k1kota) > 0 OR LENGTH(kc.k1kodepos) > 0 THEN "\n" ELSE "" END) ,kc.k1kota," ",kc.k1kodepos) as si1alamat1 ,   b.bkode ,   sid.namabarang ,   so.sonotransaksi ,   sid.jml ,   sid.customdbl1 ,   sid.satuan ,   sid.catatan ,   ilw.blgkodelokasi ,   si.sinoref FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid   JOIN m1_warehouse w ON si.sigudang = w.wkode   JOIN m0_status st ON si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b ON sid.idbarang = b.bid     LEFT JOIN m5_so_detail sod ON sid.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid  LEFT JOIN m1_item_location_warehouse ilw ON sid.idbarang = ilw.blgidbarang   AND sod.gudang = ilw.blggudang ORDER BY si.sitgl , si.siid , si.sinotransaksi , sid.urutan;

-- RID=50003771 | MENU=10 | ITEM=94 | RQUERY=1 | NAME=Surat Jalan (SI) 1 Letter DO | FILE=SI_DO2
SELECT    si.siid ,   si.sinotransaksi ,   si.sitgl ,   kc.knama AS sicustomer ,   kc.k2alamat1 ,   ks.knama AS sibagianpenjualan ,   w.wnama AS sigudang ,   si.siuraian ,   st.nama AS sistatus ,   si.simatauang ,   si.sikurs ,   si.sicustomerkontak,  	CONCAT(kc.k1alamat1,   (CASE WHEN LENGTH(kc.k2alamat1) > 0 THEN "\n" ELSE "" END) ,kc.k2alamat1,  (CASE WHEN LENGTH(kc.k1kota) > 0 OR LENGTH(kc.k1kodepos) > 0 THEN "\n" ELSE "" END) ,kc.k1kota," ",kc.k1kodepos) as si1alamat1 ,   b.bkode ,   sid.namabarang ,   so.sonotransaksi ,   sid.jml ,   sid.customdbl1 ,   sid.satuan ,   sid.catatan ,   ilw.blgkodelokasi ,   si.sinoref FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid   JOIN m1_warehouse w ON si.sigudang = w.wkode   JOIN m0_status st ON si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b ON sid.idbarang = b.bid     LEFT JOIN m5_so_detail sod ON sid.idsodetail = sod.idsodetail  LEFT JOIN m5_so so ON sod.idso = so.soid  LEFT JOIN m1_item_location_warehouse ilw ON sid.idbarang = ilw.blgidbarang   AND sod.gudang = ilw.blggudang ORDER BY si.sitgl , si.siid , si.sinotransaksi , sid.urutan;

-- RID=50003789 | MENU=10 | ITEM=95 | RQUERY=1 | NAME=SI and PEB Summary | FILE=SI PEB Summary
SELECT    si.sitgl ,   si.sinotransaksi ,   si.sicustomtext8 as nopeb,  si.sikurs ,   SUM((sid.jml * sid.harga) - sid.jmldiskon)  * si.sikurs AS dppamount ,   SUM(sid.jml) AS jml ,   SUM((sid.jml * sid.harga) - sid.jmldiskon) as sitotaltransaksi ,   kc.knama AS sicustomer ,   st.nama ,   so.sonoref FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi   JOIN m1_item b ON sid.idbarang = b.bid  JOIN m1_contact kc ON si.sicustomer = kc.kid   JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid   JOIN m0_status st ON si.sistatus = st.kode     LEFT JOIN m5_so_detail sod ON sid.idsodetail = sod.idsodetail   LEFT JOIN m5_so so ON sod.idso = so.soid WHERE b.bid not IN (8051, 8052) GROUP BY si.sitgl ASC , si.sinotransaksi ASC ORDER BY si.sitgl ASC , si.sinotransaksi ASC;

-- RID=50003802 | MENU=10 | ITEM=96 | RQUERY=1 | NAME=PACKING AND WEIGHT LIST | FILE=SI_PL_PCI
SELECT  	si.siid,  	si.sinotransaksi ,   	si.sitgl ,   	si.sicustomtext1 as vessel,  	si.sicustomtext2 as originport,  	si.sicustomtext3 as destinationport,  	si.sicustomtext4 as bundleno,  	si.sicustomtext5 as marking,  	si.sicustomdbl2 as freight,  	si.sicustomdbl3 as insurance,  	si.siuraian,   	k.knama AS sicustomer ,   	si.si1alamat1 ,   	si.si2alamat1 ,   	si.sicatatan ,   	si.sicustomdate1 as etd,  	k.k1notelp1 as telp,  	k.k1nofax as fax,    	sid.namabarang as bnama ,   	sid.jml ,   	sid.harga ,   	sid.jml * sid.harga AS total,   	sid.customdbl4 as jmlbundle,  	sid.customtext4 as satuanbundle,  	sid.customdbl5 as grossweight,  	sid.customtext5 as measurement,    sid.customtext2,  	sid.catatan as catatandetail,  	sid.matauang ,     	si.simatauang ,   	si.sitotalpajak1detail ,   	si.sibiayalain ,   	si.sitotaltransaksi ,   	si.sicustomtext9 as catatan ,   	sf.sfnotransaksi,  	si.siekspedisi as unit,  	si.si1alamat3,  	si.sicustomtext7,    si.sicustomtext6 FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi   JOIN m1_contact k ON si.sicustomer = k.kid   JOIN m1_item b ON sid.idbarang = b.bid  and b.bjenis= "P"  LEFT JOIN m5_sf sf on si.sicustomdbl1 = sf.sfid   ORDER BY si.sitgl ASC , si.siid ASC , sid.urutan ASC;

-- RID=50003803 | MENU=10 | ITEM=97 | RQUERY=1 | NAME=COMMERCIAL INVOICE (CFR) | FILE=SI_CI_PCI_CFR
SELECT  	si.siid,  	si.sinotransaksi ,   	si.sitgl ,   	si.sicustomtext1 as vessel,  	si.sicustomtext2 as originport,  	si.sicustomtext3 as destinationport,  	si.sicustomtext4 as bundleno,  	si.sicustomtext5 as marking,  	si.sicustomdbl2 as freight,  	si.sicustomdbl3 as insurance,  	si.siuraian,   	k.knama AS sicustomer ,   	si.si1alamat1 ,   	si.si2alamat1 ,   	si.siuraian as uraian,   	si.sicustomdate1 as etd,  	k.k1notelp1 as telp,  	k.k1nofax as fax,   case sicustomint4 when 0 then "CIF" when 1 then "CFR" else "FOB" END as tipecif,     	sid.namabarang as bnama ,   	sid.jml ,   	sid.harga ,   	sid.jml * sid.harga AS total,   	sid.customdbl4 as jmlbundle,  	sid.customtext4 as satuanbundle,  	sid.customdbl5 as grossweight,  	sid.customtext5 as measurement,  	sid.catatan as catatandetail,  	sid.matauang ,     	si.simatauang ,   	si.sitotalpajak1detail ,   	si.sibiayalain ,  	si.sijmldiskon ,   	si.sitotaltransaksi ,   	si.sicustomtext9 as catatan ,   	sf.sfnotransaksi, cr.csimbol,  	UPPER(f_nominal_english(sitotaltransaksi, simatauang)) AS terbilang,    k.kcatatan,    si.siekspedisi as unit,  	si.si1alamat3,  	si.sicustomtext7   FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi   JOIN m1_contact k ON si.sicustomer = k.kid   JOIN m1_item b ON sid.idbarang = b.bid   LEFT JOIN m5_sf sf on si.sicustomdbl1 = sf.sfid  left join m1_currency cr on si.simatauang = cr.ckode   WHERE bjenis = "P" ORDER BY si.sitgl ASC , si.siid ASC , sid.urutan ASC;

-- RID=50003810 | MENU=10 | ITEM=98 | RQUERY=1 | NAME=COMMERCIAL INVOICE (FOB) | FILE=SI_CI_PCI_FOB
SELECT  	si.siid,  	si.sinotransaksi ,   	si.sitgl ,   	si.sicustomtext1 as vessel,  	si.sicustomtext2 as originport,  	si.sicustomtext3 as destinationport,  	si.sicustomtext4 as bundleno,  	si.sicustomtext5 as marking,  	si.sicustomdbl2 as freight,  	si.sicustomdbl3 as insurance,  	si.siuraian,   	k.knama AS sicustomer ,   	si.si1alamat1 ,   	si.si2alamat1 ,   	si.siuraian as uraian,   	si.sicustomdate1 as etd,  	k.k1notelp1 as telp,  	k.k1nofax as fax,   case sicustomint4 when 0 then "CIF" when 1 then "CFR" else "FOB" END as tipecif,     	sid.namabarang as bnama ,   	sid.jml ,   	sid.harga ,   	sid.jml * sid.harga AS total,   	sid.customdbl4 as jmlbundle,  	sid.customtext4 as satuanbundle,  	sid.customdbl5 as grossweight,  	sid.customtext5 as measurement,  	sid.catatan as catatandetail,  	sid.matauang ,     	si.simatauang ,   	si.sitotalpajak1detail ,   	si.sibiayalain ,  	si.sijmldiskon ,   	si.sitotaltransaksi ,   	si.sicustomtext9 as catatan ,   	sf.sfnotransaksi, cr.csimbol,  	UPPER(f_nominal_english(sitotaltransaksi, simatauang)) AS terbilang,    k.kcatatan,    si.siekspedisi as unit,  	si.si1alamat3,  	si.sicustomtext7   FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi   JOIN m1_contact k ON si.sicustomer = k.kid   JOIN m1_item b ON sid.idbarang = b.bid   LEFT JOIN m5_sf sf on si.sicustomdbl1 = sf.sfid  left join m1_currency cr on si.simatauang = cr.ckode   WHERE bjenis = "P" ORDER BY si.sitgl ASC , si.siid ASC , sid.urutan ASC;

-- RID=50003812 | MENU=10 | ITEM=99 | RQUERY=1 | NAME=Commission By Salesman (Global) | FILE=commission_sales
SELECT  	cs.kid as salesman,  	cs.kkode as salesmankode,  	cs.knama as salesmannama,  	c.kid as sicustomer,  	c.kkode as sicustomerkode,  	c.knama as sicustomernama,  	si.sinotransaksi,  	si.simatauang,  	si.sitotaltransaksi,  	detail.qty as jmlkomisi,  	sic.customdbl1 as hargakomisi,  	detail.qty * sic.customdbl1  as totalkomisi FROM m5_si si  JOIN m1_contact c ON si.sicustomer = c.kid  LEFT JOIN m5_si_cost sic ON si.siid = sic.idsi  LEFT JOIN m1_contact cs ON sic.kontak = cs.kid  LEFT join (select siid, SUM(jml) AS qty from m5_si_detail JOIN m1_item ON bid = idbarang join m5_si ON siid = idsi AND bjenis = "P" AND bkategori NOT IN("JS") GROUP BY siid) AS detail  ON detail.siid = si.siid WHERE sistatus in(4,7) GROUP BY cs.kkode, c.kkode, si.sinotransaksi, sic.urutan    ORDER BY cs.kkode, c.kkode, si.sinotransaksi, sic.urutan;

-- RID=50003813 | MENU=10 | ITEM=100 | RQUERY=1 | NAME=Commission By Customer (Global) | FILE=commission_customer_global
SELECT  	cs.kid as salesman,  	cs.kkode as salesmankode,  	cs.knama as salesmannama,  	c.kid as sicustomer,  	c.kkode as sicustomerkode,  	c.knama as sicustomernama,  	si.sinotransaksi,  	si.simatauang,  	si.sitotaltransaksi,  	detail.qty as jmlkomisi,  	sic.customdbl1 as hargakomisi,  	detail.qty * sic.customdbl1  as totalkomisi FROM m5_si si  JOIN m1_contact c ON si.sicustomer = c.kid  LEFT JOIN m5_si_cost sic ON si.siid = sic.idsi  LEFT JOIN m1_contact cs ON sic.kontak = cs.kid  LEFT join (select siid, SUM(jml) AS qty from m5_si_detail JOIN m1_item ON bid = idbarang join m5_si ON siid = idsi AND bjenis = "P" AND bkategori NOT IN("JS") GROUP BY siid) AS detail  ON detail.siid = si.siid WHERE sistatus in(4,7) GROUP BY c.kkode, si.sinotransaksi, cs.kkode, sic.urutan ORDER BY c.kkode, si.sinotransaksi, sic.urutan;

-- RID=50003814 | MENU=10 | ITEM=101 | RQUERY=1 | NAME=Commission By Customer (Detail) | FILE=commission_customer_detail_2
SELECT  si.siid,  	cs.kid as salesman,  	cs.kkode as salesmankode,  	cs.knama as salesmannama,  	c.kid as sicustomer,  	c.kkode as sicustomerkode,  	c.knama as sicustomernama,  	si.sinotransaksi,  	si.simatauang,  	si.sitotaltransaksi,  	detail.qty as jmlkomisi,  	sic.customdbl1 as hargakomisi,  	detail.qty * sic.customdbl1  as totalkomisi FROM m5_si si  JOIN m1_contact c ON si.sicustomer = c.kid  LEFT JOIN m5_si_cost sic ON si.siid = sic.idsi  LEFT JOIN m1_contact cs ON sic.kontak = cs.kid  LEFT join (select siid, SUM(jml) AS qty from m5_si_detail JOIN m1_item ON bid = idbarang join m5_si ON siid = idsi AND bjenis = "P" AND bkategori NOT IN("JS") GROUP BY siid) AS detail  ON detail.siid = si.siid WHERE sistatus in(4,7) GROUP BY si.sinotransaksi ORDER BY c.kkode, si.sinotransaksi;

-- RID=50003817 | MENU=10 | ITEM=102 | RQUERY=1 | NAME=Commission By Salesman (Detail) | FILE=commission_salesman_detail
SELECT  	si.siid,  	cs.kid as salesman,  	cs.kkode as salesmankode,  	cs.knama as salesmannama,  	c.kid as sicustomer,  	c.kkode as sicustomerkode,  	c.knama as sicustomernama,  	si.sinotransaksi,  	si.simatauang,  	si.sitotaltransaksi,  	sic.customdbl1 as hargakomisi,  	detail.jml * sic.customdbl1 as totalkomisi,  	detail.bkode, detail.namabarang, detail.satuan, detail.jml, detail.harga, detail.total FROM m5_si si  JOIN m1_contact c ON si.sicustomer = c.kid  JOIN m5_si_cost sic ON si.siid = sic.idsi  JOIN m1_contact cs ON sic.kontak = cs.kid  JOIN  (select  idsidetail, idsi, bkode, namabarang, satuan, jml, harga, jml*harga - jmldiskon as total, urutan from m5_si_detail JOIN m1_item ON bid = idbarang   AND bjenis = "P" AND bkategori NOT IN("JS") GROUP BY idsidetail) AS detail  ON detail.idsi = si.siid   WHERE sistatus in(4,7) GROUP BY cs.kkode, c.kkode, si.sinotransaksi, detail.idsidetail, sic.urutan    ORDER BY cs.kkode, c.kkode, si.sinotransaksi, detail.urutan, sic.urutan;

-- RID=50003826 | MENU=10 | ITEM=103 | RQUERY=2 | NAME=FAKTUR PAJAK | FILE=FAKTURPAJAKEXSPORT
SELECT  FK,  KD_JENIS_TRANSAKSI,  FG_PENGGANTI,  NOMOR_FAKTUR,  MASA_PAJAK,  TAHUN_PAJAK,  TANGGAL_FAKTUR,  NPWP,  NAMA,  ALAMAT_LENGKAP,  JUMLAH_DPP,  JUMLAH_PPN,  JUMLAH_PPNBM,  ID_KETERANGAN_TAMBAHAN,  FG_UANG_MUKA,  UANG_MUKA_DPP,  UANG_MUKA_PPN,  UANG_MUKA_PPNBM,  REFERENSI,  KODE_DOKUMEN_PENDUKUNG FROM m2r_fakturpajak ORDER BY urutan ASC;

-- RID=50003836 | MENU=10 | ITEM=104 | RQUERY=1 | NAME=DETAIL FAKTUR | FILE=FAKTURPAJAKEXSPORT
SELECT  si.sinotransaksi,  sid.namabarang as 'NamaBarangJasa',  sid.harga as 'HargaSatuan',  sid.jml as 'JumlahBarangJasa',  sid.jmldiskon as 'TotalDiskon',  ((sid.jml * sid.harga) - sid.jmldiskon) as 'DPP',  ROUND((11/12) * ((sid.jml * sid.harga) - sid.jmldiskon)) as 'DPPNilaiLain',  12 as 'TarifPPN',  ROUND(sid.jmlpajak1) as 'PPN',  0 as 'TarifPPnBM',  0 as 'PPnBM' FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid   ORDER BY si.sitgl, si.sinotransaksi, si.siid, sid.urutan, sid.idsidetail;

-- RID=178 | MENU=11 | ITEM=1 | RQUERY=1 | NAME=Daftar Penerimaan Barang Retur (RNR) | FILE=ListReceiptNoteReturn
SELECT  	rnr.rnrnotransaksi,  	rnr.rnrtgl,  	rnr.rnrmatauang,  	rnr.rnrkurs,  	rnr.rnruraian,  	c1.knama AS rnrcustomernama,  	b.bkode,  	rnrd.tipebarang,  	rnrd.namabarang,  	rnrd.jml,  	rnrd.satuan,  	rnrd.harga,  	rnrd.jmldiskon,  	rnrd.diskon,  	rnrd.catatan,  	wh.wnama AS rnrgudangnama,  	((rnrd.jml * rnrd.harga) - rnrd.jmldiskon) AS total FROM m5_rnr rnr  JOIN m5_rnr_detail rnrd ON rnr.rnrid = rnrd.idrnr  JOIN m1_item b ON rnrd.idbarang = b.bid  JOIN m1_contact c1 ON rnr.rnrcustomer = c1.kid  JOIN m1_warehouse wh ON rnr.rnrgudang = wh.wkode   ORDER BY rnr.rnrnotransaksi, rnrd.urutan;

-- RID=179 | MENU=11 | ITEM=2 | RQUERY=1 | NAME=Penerimaan Barang Retur (RNR)  | FILE=ReceiptNoteReturndetail
SELECT  	rnr.rnrnotransaksi,  	rnr.rnrtgl,  	rnr.rnrjenispenjualan,  	rnr.rnrmatauang,  	rnr.rnrkurs,  	rnr.rnruraian,  	kc.knama AS customer,  	b.bkode,  	rnrd.tipebarang,  	rnrd.namabarang,  	Sum(rnrd.jml) AS jml,  	rnrd.satuan,  	rnrd.harga,  	rnrd.jmldiskon,  	rnrd.diskon,  	rnrd.catatan,  	sum((rnrd.jml * rnrd.harga) - rnrd.jmldiskon) AS total FROM m5_rnr rnr  JOIN m5_rnr_detail rnrd ON rnr.rnrid = rnrd.idrnr  JOIN m1_item b ON rnrd.idbarang = b.bid  JOIN m1_contact kc ON rnr.rnrcustomer = kc.kid   GROUP BY rnr.rnrnotransaksi, b.bkode, rnrd.tipebarang, rnrd.namabarang ORDER BY rnr.rnrnotransaksi, rnrd.urutan;

-- RID=241 | MENU=11 | ITEM=4 | RQUERY=1 | NAME=Penerimaan Barang Reur (RNR) Valas | FILE=ReceiptNoteReturndetailvalas
SELECT  	rnr.rnrnotransaksi,  	rnr.rnrtgl,  	rnr.rnrjenispenjualan,  	rnr.rnrmatauang,  	rnr.rnrkurs,  	rnr.rnruraian,  	kc.knama AS customer,  	b.bkode,  	rnrd.tipebarang,  	rnrd.namabarang,  	Sum(rnrd.jml) AS jml,  	rnrd.satuan,  	rnrd.harga,  	rnrd.jmldiskon,  	rnrd.diskon,  	rnrd.catatan,  	sum((rnrd.jml * rnrd.harga) - rnrd.jmldiskon) AS total,  	(rnrd.harga * rnrd.kurs) AS hargavalas,  	SUM(rnrd.jml * (rnrd.harga * rnrd.kurs) - (rnrd.jmldiskon * rnrd.kurs)) AS totalvalas FROM m5_rnr rnr  JOIN m5_rnr_detail rnrd ON rnr.rnrid = rnrd.idrnr  JOIN m1_item b ON rnrd.idbarang = b.bid  JOIN m1_contact kc ON rnr.rnrcustomer = kc.kid   WHERE (rnr.rnrmatauang <> "IDR") GROUP BY rnr.rnrnotransaksi, b.bkode, rnrd.tipebarang, rnrd.namabarang ORDER BY rnr.rnrnotransaksi, rnrd.urutan;

-- RID=334 | MENU=11 | ITEM=6 | RQUERY=1 | NAME=Daftar Penerimaan Barang Retur (RNR) Outstanding | FILE=ListReceiptNoteReturnoutstanding
SELECT  	rnr.rnrnotransaksi,  	rnr.rnrtgl,  	rnr.rnrjenispenjualan,  	rnr.rnruraian,  	kc.knama AS customer,  	b.bkode,  	IFNULL(rnrd.jmlsr,0) AS jmlsr,  	rnrd.tipebarang,  	rnrd.namabarang,  	rnrd.jml,  	rnrd.satuan,  	rnr.rnrtermin,  	rnrd.catatan   FROM m5_rnr rnr  JOIN m5_rnr_detail rnrd ON rnr.rnrid = rnrd.idrnr  JOIN m1_item b ON rnrd.idbarang = b.bid  JOIN m1_contact kc ON rnr.rnrcustomer = kc.kid   ORDER BY rnr.rnrnotransaksi, rnrd.urutan;

-- RID=341 | MENU=11 | ITEM=7 | RQUERY=1 | NAME=Daftar Penerimaan Barang Retur (RNR) Outstanding Sisa | FILE=ListReceiptNoteReturnoutstandingsisa
SELECT  	rnr.rnrnotransaksi,  	rnr.rnrtgl,  	rnr.rnrjenispenjualan,  	rnr.rnruraian,  	kc.knama AS customer,  	b.bkode,  	((rnrd.jml) - IFNULL(rnrd.jmlsr,0)) AS jmlsr,  	rnrd.tipebarang,  	rnrd.namabarang,  	rnrd.jml,  	rnrd.satuan,  	rnr.rnrtermin,  	rnrd.catatan FROM m5_rnr rnr  JOIN m5_rnr_detail rnrd ON rnr.rnrid = rnrd.idrnr  JOIN m1_item b ON rnrd.idbarang = b.bid  JOIN m1_contact kc ON rnr.rnrcustomer = kc.kid   ORDER BY rnr.rnrnotransaksi, rnrd.urutan;

-- RID=50001652 | MENU=11 | ITEM=8 | RQUERY=1 | NAME=Transkasi RNR | FILE=M5RNR
