-- RID=488 | MENU=12 | ITEM=9 | RQUERY=1 | NAME=Sales Retur (SR) Serial 1/2 Letter | FILE=salesreturdetail1_serial
SELECT    	COUNT(*),   	srd.idbarang ,     	sr.srid ,   	sr.srnotransaksi,   	sr.srtgl ,   	kc.knama AS srcustomer,   	ks.knama AS srbagianpenjualan ,   	w.wnama AS srgudang,   	st.nama AS srstatus ,   	sr.sruraian,   	sr.srmatauang ,   	sr.srkurs ,   	sr.srdiskonpersen , sr.srjmldiskon ,   	sr.srbiayalain ,   	sr.srtotalpajak1detail,     	b.bkode ,   	srd.namabarang,   	si.sinotransaksi,   	SUM(srd.jml) AS jml ,   	srd.satuan ,   	srd.harga,   	srd.hpp ,   	srd.diskon ,   	((SUM(srd.jml) * srd.harga) - SUM(srd.jmldiskon)) AS total FROM m5_sr sr   JOIN m1_contact kc ON sr.srcustomer = kc.kid  JOIN m1_contact ks ON sr.srbagianpenjualan = ks.kid  JOIN m1_warehouse w ON sr.srgudang = w.wkode  JOIN m0_status st ON sr.srstatus = st.kode    JOIN m5_sr_detail srd ON sr.srid = srd.idsr  JOIN m1_item b ON srd.idbarang = b.bid  LEFT JOIN m5_si_detail sid ON srd.idsidetail = sid.idsidetail   LEFT JOIN m5_si si ON sid.idsi = si.siid GROUP BY sr.srid, srd.idbarang , srd.namabarang , srd.satuan , srd.harga , srd.hpp ORDER BY sr.srtgl , sr.srid , sr.srnotransaksi , srd.urutan;

-- RID=181 | MENU=12 | ITEM=10 | RQUERY=1 | NAME=Daftar Retur Penjualan (SR) Outstanding Pembayaran | FILE=listsalesreturoutstanding
SELECT    sr.srnotransaksi,   sr.srtgl,   kc.knama AS customer ,   ks.knama AS salesman ,   sr.srmatauang,   sr.srkurs ,   pv.pvnotransaksi,   pv.pvtgl ,   pv.pvstatus ,   pv.pvcatatan ,   pv.pvmatauang ,   pv.pvkurs ,   pvd.jmlbayarvalas ,   pvd.terbayar,   pvd.jmlbayar FROM m5_sr sr   JOIN m5_sr_detail srd ON sr.srid = srd.idsr  JOIN m1_contact kc ON sr.srcustomer = kc.kid  JOIN m1_contact ks ON sr.srbagianpenjualan = ks.kid  LEFT JOIN m5_pv_detail pvd ON srd.idsr = pvd.idtransaksi  LEFT JOIN m5_pv pv ON pvd.idpv = pv.pvid WHERE (pvd.sumber = "SR") AND (pv.pvstatus = 2 OR pv.pvstatus = 3 OR pv.pvstatus = 4 OR pv.pvstatus = 7) GROUP BY sr.srnotransaksi , pv.pvnotransaksi ORDER BY sr.srtgl, sr.srid , sr.srnotransaksi , srd.urutan , pv.pvnotransaksi;

-- RID=182 | MENU=12 | ITEM=11 | RQUERY=1 | NAME=Daftar Retur Penjualan (SR) Outstanding Sisa | FILE=listsalesreturresidueoutstanding
SELECT  sr.srnotransaksi,  sr.srtgl,  sr.srcatatan,  ((srd.jml) - IFNULL(sqd.jml,0)) AS jmlsq,  ((srd.jml) - IFNULL(sod.jml,0)) AS jmlso,  ((srd.jml) - IFNULL(pld.jml,0)) AS jmlpl,  ((srd.jml) - IFNULL(dod.jml,0)) AS jmldo,  ((srd.jml) - IFNULL(drd.jml,0)) AS jmldr,  ((srd.jml) - IFNULL(pid.jml,0)) AS jmlpi,  ((srd.jml) - IFNULL(sid.jml,0)) AS jmlsi,  ((srd.jml) - IFNULL(rnrd.jml,0)) AS jmlrnr,  srd.jml,  srd.catatan,  srd.satuan,  srd.namabarang,  srd.tipebarang,  b.bkode,  ks.knama AS salesman,  kc.knama AS customer FROM m5_sr sr   JOIN m5_sr_detail srd ON sr.srid = srd.idsr  JOIN m1_item b ON srd.idbarang = b.bid  JOIN m1_contact ks ON sr.srbagianpenjualan = ks.kid  JOIN m1_contact kc ON sr.srcustomer = kc.kid  LEFT JOIN m5_sq_detail sqd ON srd.idsqdetail = sqd.idsqdetail  LEFT JOIN m5_so_detail sod ON srd.idsodetail = sod.idsodetail  LEFT JOIN m5_pl_detail pld ON srd.idpldetail = pld.idpldetail  LEFT JOIN m5_do_detail dod ON srd.iddodetail = dod.iddodetail  LEFT JOIN m5_dr_detail drd ON srd.iddrdetail = drd.iddrdetail  LEFT JOIN m5_pi_detail pid ON srd.idpidetail = pid.idpidetail  LEFT JOIN m5_si_detail sid ON srd.idsidetail = sid.idsidetail  LEFT JOIN m5_rnr_detail rnrd ON srd.idrnrdetail = rnrd.idrnrdetail ORDER BY sr.srnotransaksi, srd.urutan;

-- RID=183 | MENU=12 | ITEM=12 | RQUERY=1 | NAME=Daftar Retur Penjualan (SR) Per Produk | FILE=listsalesretur_perproduk
SELECT    b.bid , b.bkode , srd.namabarang ,   sr.srnotransaksi , sr.srtgl , kc.knama AS srcustomer , si.sinotransaksi , SUM(srd.jml) AS jml ,   srd.satuan ,   srd.harga,   srd.hpp ,   SUM(srd.diskon) AS diskon ,   SUM((srd.jml * srd.harga) - srd.jmldiskon) AS total FROM m5_sr sr   JOIN m1_contact kc ON sr.srcustomer = kc.kid  JOIN m1_warehouse w ON sr.srgudang = w.wkode  JOIN m0_status st ON sr.srstatus = st.kode    JOIN m5_sr_detail srd ON sr.srid = srd.idsr  JOIN m1_item b ON srd.idbarang = b.bid  LEFT JOIN m5_si_detail sid ON srd.idsidetail = sid.idsidetail   LEFT JOIN m5_si si ON sid.idsi = si.siid GROUP BY srd.idbarang, b.bid, b.bkode, srd.namabarang, srd.satuan, srd.idsr ORDER BY srd.idbarang, b.bid, b.bkode , srd.namabarang;

-- RID=231 | MENU=12 | ITEM=13 | RQUERY=1 | NAME=Sales Retur (SR) Valas 1/2 Letter | FILE=salesreturdetail_valas1
SELECT    	sr.srid ,   	sr.srnotransaksi,   	sr.srtgl ,   	kc.knama AS srcustomer,   	ks.knama AS srbagianpenjualan ,   	w.wnama AS srgudang,   	st.nama AS srstatus ,   	sr.sruraian,   	sr.srmatauang ,   	sr.srkurs ,   	sr.srdiskonpersen , sr.srjmldiskon ,   	sr.srbiayalain ,   	sr.srtotalpajak1detail,     	b.bkode ,   	srd.namabarang,   	si.sinotransaksi,   	srd.jml ,   	srd.satuan ,   	srd.harga,   	(srd.harga * srd.kurs) AS hargavalas ,   	srd.hpp ,   	srd.diskon ,   	((srd.jml * srd.harga) - srd.jmldiskon) AS total ,  ((srd.jml * (srd.harga * srd.kurs)) - (srd.jmldiskon * srd.kurs)) AS totalvalas FROM m5_sr sr   JOIN m1_contact kc ON sr.srcustomer = kc.kid  JOIN m1_contact ks ON sr.srbagianpenjualan = ks.kid  JOIN m1_warehouse w ON sr.srgudang = w.wkode  JOIN m0_status st ON sr.srstatus = st.kode    JOIN m5_sr_detail srd ON sr.srid = srd.idsr  JOIN m1_item b ON srd.idbarang = b.bid  LEFT JOIN m5_si_detail sid ON srd.idsidetail = sid.idsidetail   LEFT JOIN m5_si si ON sid.idsi = si.siid WHERE (sr.srmatauang <> "IDR" AND sr.srmatauang <> "RP") GROUP BY sr.srtgl , sr.srid , sr.srnotransaksi , srd.urutan ORDER BY sr.srnotransaksi, srd.urutan;

-- RID=780 | MENU=12 | ITEM=14 | RQUERY=1 | NAME=Sales Retur (SR) Batch 1/2 Letter | FILE=salesreturdetail1_batch
