-- RID=186 | MENU=13 | ITEM=1 | RQUERY=1 | NAME=Daftar Penagihan Piutang (IC) Detail | FILE=ListInvoiceCollector
SELECT  ic.icid,   ic.icnotransaksi ,   ic.ictgl ,   kc.knama AS iccustomer,   ic.icuraian ,   ic.icmatauang ,   ic.ickurs ,   st.nama AS icstatus,     CASE sumber  	WHEN "SI" then si.sinotransaksi   	WHEN "RP" then rp.rpnotransaksi   	WHEN "IP" then ip.ipnotransaksi   	WHEN "AS" then ass.asnotransaksi   	WHEN "SR" then sr.srnotransaksi   	WHEN "CA" then CONCAT(icd.sumber,"(",coa.cnomor, ")")  END as notransaksi ,  CASE sumber  	WHEN "SI" then si.sitgl   	WHEN "RP" then rp.rptgl  	WHEN "IP" then ip.iptgl  	WHEN "AS" then ass.astgl  	WHEN "SR" then sr.srtgl  	END as tanggal,   icd.sumber ,   icd.matauang ,   icd.kurs ,   icd.totaltransaksi ,   icd.terbayar ,   icd.rencana ,   icd.jmlbayar,   icd.jmlbayarvalas,   CASE sumber  	WHEN "SI" then si.sitermin   	WHEN "RP" then rp.rptermin  	WHEN "IP" then ip.iptermin  	WHEN "AS" then ass.astermin  	WHEN "SR" then sr.srtermin  	END as termin FROM m5_ic ic  JOIN m1_contact kc ON ic.iccustomer = kc.kid  JOIN m0_status st ON ic.icstatus = st.kode    JOIN m5_ic_detail icd ON ic.icid = icd.idic  LEFT JOIN m5_si si ON icd.sumber = si.sisumber AND icd.idtransaksi = si.siid  LEFT JOIN m5_rp rp ON icd.sumber = rp.rpsumber AND icd.idtransaksi = rp.rpid  LEFT JOIN m5_ip ip ON icd.sumber = ip.ipsumber AND icd.idtransaksi = ip.ipid  LEFT JOIN m5_as ass ON icd.sumber = ass.assumber AND icd.idtransaksi = ass.asid  LEFT JOIN m5_sr sr ON icd.sumber = sr.srsumber AND icd.idtransaksi = sr.srid  LEFT JOIN m1_coa coa ON icd.rekhutangpiutang = coa.cnomor ORDER BY ic.ictgl , ic.icid , ic.icnotransaksi , icd.urutan;

-- RID=187 | MENU=13 | ITEM=2 | RQUERY=1 | NAME=Penagihan Piutang (IC) 1/2 Letter | FILE=InvoiceCollectordetail
SELECT    (SELECT f_nominal(SUM(icd2.jmlbayar), icd2.matauang)  FROM m5_ic_detail icd2   WHERE icd.idic = icd2.idic   AND icd2.sumber <> "CA"   GROUP BY icd2.idic  ORDER BY icd2.idic ) AS terbilang,     ic.icid,   ic.icnotransaksi ,   ic.ictgl ,   kc.knama AS iccustomer,   kc.k1alamat1 ,   ic.icuraian ,   ic.iccatatan ,   ic.icmatauang ,   ic.ickurs ,   st.nama AS icstatus,     CASE sumber  	WHEN "SI" then si.sinotransaksi   	WHEN "RP" then rp.rpnotransaksi   	WHEN "IP" then ip.ipnotransaksi   	WHEN "AS" then ass.asnotransaksi   	WHEN "SR" then sr.srnotransaksi   	WHEN "CA" then CONCAT(icd.sumber,"(",coa.cnomor, ")")  END as notransaksi ,  CASE sumber  	WHEN "SI" then si.sitgl   	WHEN "RP" then rp.rptgl  	WHEN "IP" then ip.iptgl  	WHEN "AS" then ass.astgl  	WHEN "SR" then sr.srtgl  	END as tanggal,   CASE sumber  	WHEN "SI" then si.sitgljatuhtempo   	WHEN "RP" then rp.rptgljatuhtempo  	WHEN "IP" then ip.iptgljatuhtempo  	WHEN "AS" then ass.astgljatuhtempo  	WHEN "SR" then sr.srtgljatuhtempo  	END as tanggalJT,   icd.sumber ,   icd.matauang ,   icd.kurs ,   icd.totaltransaksi ,   icd.terbayar ,   icd.rencana ,   icd.jmlbayar,   icd.jmlbayarvalas,   CASE sumber  	WHEN "SI" then si.sitermin   	WHEN "RP" then rp.rptermin  	WHEN "IP" then ip.iptermin  	WHEN "AS" then ass.astermin  	WHEN "SR" then sr.srtermin  	END as termin ,   icd.catatan FROM m5_ic ic  JOIN m1_contact kc ON ic.iccustomer = kc.kid  JOIN m0_status st ON ic.icstatus = st.kode    JOIN m5_ic_detail icd ON ic.icid = icd.idic  LEFT JOIN m5_si si ON icd.sumber = si.sisumber AND icd.idtransaksi = si.siid  LEFT JOIN m5_rp rp ON icd.sumber = rp.rpsumber AND icd.idtransaksi = rp.rpid  LEFT JOIN m5_ip ip ON icd.sumber = ip.ipsumber AND icd.idtransaksi = ip.ipid  LEFT JOIN m5_as ass ON icd.sumber = ass.assumber AND icd.idtransaksi = ass.asid  LEFT JOIN m5_sr sr ON icd.sumber = sr.srsumber AND icd.idtransaksi = sr.srid  LEFT JOIN m1_coa coa ON icd.rekhutangpiutang = coa.cnomor WHERE icd.sumber <> "CA" ORDER BY ic.ictgl, ic.icnotransaksi asc, ic.icid , icd.catatan,  icd.sumber = "SI" DESC , icd.sumber = "RP", icd.sumber = "IP" DESC , icd.sumber = "AS" DESC, icd.sumber = "SR" DESC , icd.sumber = "CA" DESC , icd.urutan;

