gl, ic.icnotransaksi asc, ic.icid , icd.catatan,  icd.sumber = "SI" DESC , icd.sumber = "RP", icd.sumber = "IP" DESC , icd.sumber = "AS" DESC, icd.sumber = "SR" DESC , icd.sumber = "CA" DESC , icd.urutan;

-- RID=1695 | MENU=13 | ITEM=5 | RQUERY=1 | NAME=Daftar Penagihan Piutang (IC) Global | FILE=ListInvoiceCollector2
SELECT  ic.icid,   ic.icnotransaksi ,   ic.ictgl ,   kc.knama AS iccustomer,   ic.icuraian ,   ic.iccatatan ,  ic.icmatauang ,   ic.ickurs ,   st.nama AS icstatus,     CASE sumber  	WHEN "SI" then si.sinotransaksi   	WHEN "RP" then rp.rpnotransaksi   	WHEN "IP" then ip.ipnotransaksi   	WHEN "AS" then ass.asnotransaksi   	WHEN "SR" then sr.srnotransaksi   	WHEN "CA" then CONCAT(icd.sumber,"(",coa.cnomor, ")")  END as notransaksi ,  CASE sumber  	WHEN "SI" then si.sitgl   	WHEN "RP" then rp.rptgl  	WHEN "IP" then ip.iptgl  	WHEN "AS" then ass.astgl  	WHEN "SR" then sr.srtgl  	END as tanggal,   icd.sumber ,   icd.matauang ,   icd.kurs ,   icd.totaltransaksi ,   icd.terbayar ,   icd.rencana ,   icd.jmlbayar,   icd.jmlbayarvalas,   CASE sumber  	WHEN "SI" then si.sitermin   	WHEN "RP" then rp.rptermin  	WHEN "IP" then ip.iptermin  	WHEN "AS" then ass.astermin  	WHEN "SR" then sr.srtermin  	END as termin FROM m5_ic ic  JOIN m1_contact kc ON ic.iccustomer = kc.kid  JOIN m0_status st ON ic.icstatus = st.kode    JOIN m5_ic_detail icd ON ic.icid = icd.idic  LEFT JOIN m5_si si ON icd.sumber = si.sisumber AND icd.idtransaksi = si.siid  LEFT JOIN m5_rp rp ON icd.sumber = rp.rpsumber AND icd.idtransaksi = rp.rpid  LEFT JOIN m5_ip ip ON icd.sumber = ip.ipsumber AND icd.idtransaksi = ip.ipid  LEFT JOIN m5_as ass ON icd.sumber = ass.assumber AND icd.idtransaksi = ass.asid  LEFT JOIN m5_sr sr ON icd.sumber = sr.srsumber AND icd.idtransaksi = sr.srid  LEFT JOIN m1_coa coa ON icd.rekhutangpiutang = coa.cnomor ORDER BY ic.ictgl , ic.icid , ic.icnotransaksi , icd.urutan;

-- RID=1697 | MENU=13 | ITEM=6 | RQUERY=1 | NAME=Daftar Penagihan Piutang (IC) Outstanding | FILE=DaftarPenagihanPiutang_Outstanding
SELECT    ic.icnotransaksi,   ic.ictgl ,   kc.knama AS customer ,   ks.knama AS salesman ,   ic.icmatauang ,   ic.ickurs ,    pv.pvnotransaksi,   pv.pvtgl ,   pv.pvstatus ,   pv.pvcatatan ,   pv.pvmatauang ,   pv.pvkurs ,   pvd.jmlbayarvalas ,   pvd.terbayar,   pvd.jmlbayar FROM m5_ic ic   JOIN m5_ic_detail icd ON ic.icid = icd.idic  JOIN m1_contact kc ON ic.iccustomer = kc.kid  JOIN m1_contact ks ON ic.icbagianpenagihan = ks.kid  LEFT JOIN m5_pv_detail pvd ON icd.idic = pvd.idtransaksi  LEFT JOIN m5_pv pv ON pvd.idpv = pv.pvid WHERE (pvd.sumber = "SR") AND (pv.pvstatus = 2 OR pv.pvstatus = 3 OR pv.pvstatus = 4 OR pv.pvstatus = 7) GROUP BY ic.icnotransaksi , pv.pvnotransaksi ORDER BY ic.ictgl, ic.icid, ic.icnotransaksi , icd.urutan, pv.pvnotransaksi;

