-- RID=50001766 | MENU=13 | ITEM=10 | RQUERY=1 | NAME=STATEMENT OF ACCOUNT | FILE=STATEMENT OF ACCOUNT
SELECT  ic.icid,   ic.icnotransaksi ,   ic.ictgl ,   kc.knama AS iccustomer,   ic.icuraian ,   ic.icmatauang ,   ic.ickurs ,   st.nama AS icstatus,     CASE sumber  	WHEN "SI" then si.sinotransaksi   	WHEN "RP" then rp.rpnotransaksi   	WHEN "IP" then ip.ipnotransaksi   	WHEN "AS" then ass.asnotransaksi   	WHEN "SR" then sr.srnotransaksi   	WHEN "CA" then CONCAT(icd.sumber,"(",coa.cnomor, ")")  END as notransaksi ,  CASE sumber  	WHEN "SI" then si.sitgl   	WHEN "RP" then rp.rptgl  	WHEN "IP" then ip.iptgl  	WHEN "AS" then ass.astgl  	WHEN "SR" then sr.srtgl  	END as tanggal,   icd.sumber ,   icd.matauang ,   icd.kurs ,   icd.totaltransaksi ,   icd.terbayar ,   icd.rencana ,   icd.jmlbayar,   icd.jmlbayarvalas,   CASE sumber  	WHEN "SI" then si.sitermin   	WHEN "RP" then rp.rptermin  	WHEN "IP" then ip.iptermin  	WHEN "AS" then ass.astermin  	WHEN "SR" then sr.srtermin  	END as termin ,   icd.catatan FROM m5_ic ic  JOIN m1_contact kc ON ic.iccustomer = kc.kid  JOIN m0_status st ON ic.icstatus = st.kode    JOIN m5_ic_detail icd ON ic.icid = icd.idic  LEFT JOIN m5_si si ON icd.sumber = si.sisumber AND icd.idtransaksi = si.siid  LEFT JOIN m5_rp rp ON icd.sumber = rp.rpsumber AND icd.idtransaksi = rp.rpid  LEFT JOIN m5_ip ip ON icd.sumber = ip.ipsumber AND icd.idtransaksi = ip.ipid  LEFT JOIN m5_as ass ON icd.sumber = ass.assumber AND icd.idtransaksi = ass.asid  LEFT JOIN m5_sr sr ON icd.sumber = sr.srsumber AND icd.idtransaksi = sr.srid  LEFT JOIN m1_coa coa ON icd.rekhutangpiutang = coa.cnomor ORDER BY ic.ictgl , ic.icid , ic.icnotransaksi , icd.sumber = "SI" DESC , icd.sumber = "RP", icd.sumber = "IP" DESC , icd.sumber = "AS" DESC, icd.sumber = "SR" DESC , icd.sumber = "CA" DESC , icd.urutan;

