-- RID=189 | MENU=14 | ITEM=3 | RQUERY=1 | NAME=Pembayaran Piutang (PV) 1/2 Letter | FILE=PaymentReceiptdetail_new
SELECT    coa.cnomor ,   coa.cnama ,     	pv.pvid,   	pv.pvtgl ,   	pv.pvnotransaksi ,   kc.kkode,   	kc.knama AS pvcustomer,   	pv.pvuraian ,   	pv.pvmatauang ,   	pv.pvkurs ,   	st.nama AS pvstatus,    	CASE sumber  	WHEN "SI" then si.sinotransaksi   	WHEN "RP" then rp.rpnotransaksi   	WHEN "IP" then ip.ipnotransaksi   	WHEN "AS" then ass.asnotransaksi   	WHEN "SR" then sr.srnotransaksi   	WHEN "CA" then CONCAT(pvd.sumber,"(",coa.cnomor, ")")  END as notransaksi ,  CASE sumber  	WHEN "SI" then si.sitgl   	WHEN "RP" then rp.rptgl  	WHEN "IP" then ip.iptgl  	WHEN "AS" then ass.astgl  	WHEN "SR" then sr.srtgl  	END as tanggal,   pvd.sumber ,   pvd.matauang ,   pvd.kurs ,   /*AR = SI , RP , CA  AP =  IP , AS, SR, */  CASE sumber  	WHEN "SI" then pvd.jmlbayar  	WHEN "RP" then pvd.jmlbayar  	WHEN "IP" then (pvd.jmlbayar * -1)  	WHEN "AS" then (pvd.jmlbayar * -1)  	WHEN "SR" then (pvd.jmlbayar * -1)  	WHEN "CA" then pvd.jmlbayar  END as jmlbayar ,  CASE sumber  	WHEN "SI" then pvd.jmlbayarvalas  	WHEN "RP" then pvd.jmlbayarvalas  	WHEN "IP" then (pvd.jmlbayarvalas * -1)  	WHEN "AS" then (pvd.jmlbayarvalas * -1)  	WHEN "SR" then (pvd.jmlbayarvalas * -1)  	WHEN "CA" then pvd.jmlbayarvalas  END as jmlbayarvalas,    CASE sumber  	WHEN "SI" then si.sitermin   	WHEN "RP" then rp.rptermin  	WHEN "IP" then ip.iptermin  	WHEN "AS" then ass.astermin  	WHEN "SR" then sr.srtermin  	END as termin,   CASE sumber  	WHEN "SI" then si.sicatatan  	WHEN "RP" then rp.rpcatatan  	WHEN "IP" then ip.ipcatatan  	WHEN "AS" then asp.catatan  	WHEN "SR" then sr.srcatatan  	END as catatan FROM m5_pv pv  JOIN m1_contact kc ON pv.pvcustomer = kc.kid  JOIN m0_status st ON pv.pvstatus = st.kode    JOIN m5_pv_detail pvd ON pv.pvid = pvd.idpv  LEFT JOIN m5_si si ON pvd.sumber = si.sisumber AND pvd.idtransaksi = si.siid  LEFT JOIN m5_rp rp ON pvd.sumber = rp.rpsumber AND pvd.idtransaksi = rp.rpid  LEFT JOIN m5_ip ip ON pvd.sumber = ip.ipsumber AND pvd.idtransaksi = ip.ipid  LEFT JOIN m5_as ass ON pvd.sumber = ass.assumber AND pvd.idtransaksi = ass.asid  LEFT JOIN m5_as_pay asp ON ass.asid = asp.idas  LEFT JOIN m5_sr sr ON pvd.sumber = sr.srsumber AND pvd.idtransaksi = sr.srid  LEFT JOIN m1_coa coa ON pvd.rekhutangpiutang = coa.cnomor WHERE pvd.sumber <> "CA" ORDER BY pv.pvtgl, pv.pvid , pv.pvnotransaksi , pvd.sumber = "SI" DESC , pvd.sumber = "RP" DESC , pvd.sumber = "IP" DESC , pvd.sumber = "AS" DESC , pvd.sumber = "SR" DESC, pvd.sumber = "CA" DESC  , pvd.urutan;

