ss.asid  LEFT JOIN m5_sr sr ON pvd.sumber = sr.srsumber AND pvd.idtransaksi = sr.srid  LEFT JOIN m1_coa coa ON pvd.rekhutangpiutang = coa.cnomor ORDER BY pv.pvtgl, pv.pvid , pv.pvnotransaksi , pvd.sumber = "SI" DESC , pvd.sumber = "RP" DESC , pvd.sumber = "IP" DESC , pvd.sumber = "AS" DESC , pvd.sumber = "SR" DESC, pvd.sumber = "CA" DESC  , pvd.urutan;

-- RID=203 | MENU=14 | ITEM=5 | RQUERY=1 | NAME=Pembayaran Piutang (PV) Invoice | FILE=PaymentReceiptinvoice
SELECT  	pv.pvnotransaksi,  	pv.pvtgl,  	kc.knama,  	pv.pvcatatan,  	(CASE pv.pvcarabayar  WHEN 0 THEN 'Cash'  WHEN 1 THEN 'Transfer'  WHEN 2 THEN 'Cek/Giro'  ELSE 'Lain-lain'  END) AS ascarabayar,  si.sikurs,  si.sicatatan,  si.sinotransaksi,  si.sitgl,  si.simatauang,  SUM(si.sitotaltransaksi) AS sitotaltransaksi,  pv.pvtglbayar,  pv.pvmatauang,  pv.pvkurs,  pv.pvtotalap,  pv.pvtotalar,  pvd.sumber,  pvd.matauang,  pvd.kurs,  pvd.terbayar,  pvd.jmlbayar,  pvd.jmlbayarvalas   FROM m5_pv pv  JOIN m5_pv_detail pvd ON pv.pvid = pvd.idpv  JOIN m1_contact kc ON pv.pvcustomer = kc.kid  LEFT JOIN m1_contact ks ON pv.pvbagianpenjualan = ks.kid   LEFT JOIN m5_si si ON pvd.idtransaksi = si.siid       WHERE pvd.sumber = 'SI' GROUP BY pv.pvnotransaksi, si.sinotransaksi ORDER BY pv.pvnotransaksi, si.sinotransaksi, pvd.urutan;

-- RID=204 | MENU=14 | ITEM=6 | RQUERY=1 | NAME=Pembayaran Piutang (PV) Retur | FILE=PaymentReceiptretur
SELECT  	pv.pvnotransaksi,  	pv.pvtgl,  	kc.knama,  	pv.pvcatatan,  	(CASE pv.pvcarabayar  WHEN 0 THEN 'Cash'  WHEN 1 THEN 'Transfer'  WHEN 2 THEN 'Cek/Giro'  ELSE 'Lain-lain'  END) AS ascarabayar,  sr.srkurs,  sr.srcatatan,  sr.srnotransaksi,  sr.srtgl,  sr.srmatauang,  sr.srtotaltransaksi,  pv.pvtglbayar,  pv.pvmatauang,  pv.pvkurs,  pv.pvtotalap,  pv.pvtotalar,  pvd.sumber,  pvd.matauang,  pvd.kurs,  pvd.terbayar,  pvd.jmlbayar,  pvd.jmlbayarvalas FROM m5_pv pv  JOIN m5_pv_detail pvd ON pv.pvid = pvd.idpv  JOIN m1_contact kc ON pv.pvcustomer = kc.kid  LEFT JOIN m1_contact ks ON pv.pvbagianpenjualan = ks.kid   LEFT JOIN m5_sr sr ON pvd.idtransaksi = sr.srid     WHERE pvd.sumber = 'SR' GROUP BY pv.pvnotransaksi, sr.srnotransaksi ORDER BY pv.pvnotransaksi, sr.srnotransaksi, pvd.urutan;

-- RID=205 | MENU=14 | ITEM=7 | RQUERY=1 | NAME=Pembayaran Piutang (PV) Cash | FILE=PaymentReceiptcash
SELECT  	pv.pvnotransaksi,  	pv.pvtgl,  	kc.knama,  	pvd.rekhutangpiutang,  	(CASE pv.pvcarabayar  WHEN 0 THEN 'Cash'  WHEN 1 THEN 'Transfer'  WHEN 2 THEN 'Cek/Giro'  ELSE 'Lain-lain'  END) AS carabayar,  pv.pvtglbayar,  pv.pvmatauang,  pv.pvkurs,  (CASE pvd.sumber  WHEN 'SI' THEN  	CASE  	WHEN LEFT(pvd.jmlbayar,1) = '-' THEN REPLACE(pvd.jmlbayar,"-","")  	ELSE pvd.jmlbayar  	END  WHEN 'AS' THEN  	CASE  	WHEN LEFT(pvd.jmlbayar,1) = '-' THEN REPLACE(pvd.jmlbayar,"-","")  	ELSE pvd.jmlbayar  	END  WHEN 'SR' THEN  	CASE  	WHEN LEFT(pvd.jmlbayar,1) = '-' THEN REPLACE(pvd.jmlbayar,"-","")  	ELSE pvd.jmlbayar  	END  WHEN 'CA' THEN pvd.jmlbayar  END) AS asjmlbayar,    pvd.sumber,  pvd.catatan FROM m5_pv pv  JOIN m5_pv_detail pvd ON pv.pvid = pvd.idpv  JOIN m1_contact kc ON pv.pvcustomer = kc.kid      WHERE (pv.pvcarabayar <> 1 OR pv.pvcarabayar <> 2) ORDER BY pv.pvnotransaksi, pvd.urutan;

-- RID=312 | MENU=14 | ITEM=8 | RQUERY=1 | NAME=Pembayaran Piutang (PV) Valas  | FILE=PaymentReceiptdetailvalas
SELECT  	pv.pvnotransaksi,  	pv.pvtgl,  	kc.knama,  	pv.pvcatatan,  	pv.pvtglbayar,  	pv.pvmatauang,  	pv.pvkurs,  	(CASE pvd.sumber  WHEN 'SI' THEN (SELECT si.sinotransaksi FROM m5_si si WHERE si.sisumber = pvd.sumber AND si.siid = pvd.idtransaksi)  WHEN 'AS' THEN (SELECT sa.asnotransaksi FROM m5_as sa WHERE sa.assumber = pvd.sumber AND sa.asid = pvd.idtransaksi)  WHEN 'SR' THEN (SELECT sr.srnotransaksi FROM m5_sr sr WHERE sr.srsumber = pvd.sumber AND sr.srid = pvd.idtransaksi)  WHEN 'IP' THEN (SELECT ip.ipnotransaksi FROM m5_ip ip WHERE ip.ipsumber = pvd.sumber AND ip.ipid = pvd.idtransaksi)  WHEN 'RP' THEN (SELECT rp.rpnotransaksi FROM m5_rp rp WHERE rp.rpsumber = pvd.sumber AND rp.rpid = pvd.idtransaksi)  END) AS tnotransaksi,    (CASE pvd.sumber  WHEN 'SI' THEN (SELECT si.sitgl FROM m5_si si WHERE si.sisumber = pvd.sumber AND si.siid = pvd.idtransaksi)  WHEN 'AS' THEN (SELECT sa.astgl FROM m5_as sa WHERE sa.assumber = pvd.sumber AND sa.asid = pvd.idtransaksi)  WHEN 'SR' THEN (SELECT sr.srtgl FROM m5_sr sr WHERE sr.srsumber = pvd.sumber AND sr.srid = pvd.idtransaksi)  WHEN 'IP' THEN (SELECT ip.iptgl FROM m5_ip ip WHERE ip.ipsumber = pvd.sumber AND ip.ipid = pvd.idtransaksi)  WHEN 'RP' THEN (SELECT rp.rptgl FROM m5_rp rp WHERE rp.rpsumber = pvd.sumber AND rp.rpid = pvd.idtransaksi)  END) AS ttgl,    (CASE pvd.sumber  WHEN 'SI' THEN  	CASE  	WHEN LEFT(pvd.jmlbayar,1) = '-' THEN REPLACE(pvd.jmlbayar,"-","")  	ELSE pvd.jmlbayar  	END  WHEN 'AS' THEN  	CASE  	WHEN LEFT(pvd.jmlbayar,1) = '-' THEN REPLACE(pvd.jmlbayar,"-","")  	ELSE pvd.jmlbayar  	END  WHEN 'SR' THEN  	CASE  	WHEN LEFT(pvd.jmlbayar,1) = '-' THEN REPLACE(pvd.jmlbayar,"-","")  	ELSE pvd.jmlbayar  	END  WHEN 'CA' THEN pvd.jmlbayar  END) AS asjmlbayar,    pvd.sumber,  pvd.matauang,  pvd.kurs,  pvd.terbayar,  pvd.jmlbayar,  pvd.jmlbayarvalas,  pvd.catatan   FROM m5_pv pv  JOIN m5_pv_detail pvd ON pv.pvid = pvd.idpv  JOIN m1_contact kc ON pv.pvcustomer = kc.kid   LEFT JOIN m1_contact ks ON pv.pvbagianpenjualan = ks.kid  left JOIN m5_ic_detail icd ON pvd.idicdetail = icd.idicdetail     WHERE pv.pvmatauang <> "IDR" ORDER BY pv.pvnotransaksi, pvd.urutan;

-- RID=754 | MENU=14 | ITEM=9 | RQUERY=1 | NAME=Pembayaran Piutang (PV) 1 Letter | FILE=PaymentReceiptdetail_new2
SELECT    coa.cnomor ,   coa.cnama ,     	pv.pvid,   	pv.pvtgl ,   	pv.pvnotransaksi ,   kc.kkode,   	kc.knama AS pvcustomer,   	pv.pvuraian ,   	pv.pvmatauang ,   	pv.pvkurs ,   	st.nama AS pvstatus,    	CASE sumber  	WHEN "SI" then si.sinotransaksi   	WHEN "RP" then rp.rpnotransaksi   	WHEN "IP" then ip.ipnotransaksi   	WHEN "AS" then ass.asnotransaksi   	WHEN "SR" then sr.srnotransaksi   	WHEN "CA" then CONCAT(pvd.sumber,"(",coa.cnomor, ")")  END as notransaksi ,  CASE sumber  	WHEN "SI" then si.sitgl   	WHEN "RP" then rp.rptgl  	WHEN "IP" then ip.iptgl  	WHEN "AS" then ass.astgl  	WHEN "SR" then sr.srtgl  	END as tanggal,   pvd.sumber ,   pvd.matauang ,   pvd.kurs ,   /*AR = SI , RP , CA  AP =  IP , AS, SR, */  CASE sumber  	WHEN "SI" then pvd.jmlbayar  	WHEN "RP" then pvd.jmlbayar  	WHEN "IP" then (pvd.jmlbayar * -1)  	WHEN "AS" then (pvd.jmlbayar * -1)  	WHEN "SR" then (pvd.jmlbayar * -1)  	WHEN "CA" then pvd.jmlbayar  END as jmlbayar ,  CASE sumber  	WHEN "SI" then pvd.jmlbayarvalas  	WHEN "RP" then pvd.jmlbayarvalas  	WHEN "IP" then (pvd.jmlbayarvalas * -1)  	WHEN "AS" then (pvd.jmlbayarvalas * -1)  	WHEN "SR" then (pvd.jmlbayarvalas * -1)  	WHEN "CA" then pvd.jmlbayarvalas  END as jmlbayarvalas,    CASE sumber  	WHEN "SI" then si.sitermin   	WHEN "RP" then rp.rptermin  	WHEN "IP" then ip.iptermin  	WHEN "AS" then ass.astermin  	WHEN "SR" then sr.srtermin  	END as termin,   CASE sumber  	WHEN "SI" then si.sicatatan  	WHEN "RP" then rp.rpcatatan  	WHEN "IP" then ip.ipcatatan  	WHEN "AS" then ass.ascatatan  	WHEN "SR" then sr.srcatatan  	END as catatan FROM m5_pv pv  JOIN m1_contact kc ON pv.pvcustomer = kc.kid  JOIN m0_status st ON pv.pvstatus = st.kode    JOIN m5_pv_detail pvd ON pv.pvid = pvd.idpv  LEFT JOIN m5_si si ON pvd.sumber = si.sisumber AND pvd.idtransaksi = si.siid  LEFT JOIN m5_rp rp ON pvd.sumber = rp.rpsumber AND pvd.idtransaksi = rp.rpid  LEFT JOIN m5_ip ip ON pvd.sumber = ip.ipsumber AND pvd.idtransaksi = ip.ipid  LEFT JOIN m5_as ass ON pvd.sumber = ass.assumber AND pvd.idtransaksi = ass.asid  LEFT JOIN m5_sr sr ON pvd.sumber = sr.srsumber AND pvd.idtransaksi = sr.srid  LEFT JOIN m1_coa coa ON pvd.rekhutangpiutang = coa.cnomor WHERE pvd.sumber <> "CA" ORDER BY pv.pvtgl, pv.pvid , pv.pvnotransaksi , pvd.sumber = "SI" DESC , pvd.sumber = "RP" DESC , pvd.sumber = "IP" DESC , pvd.sumber = "AS" DESC , pvd.sumber = "SR" DESC, pvd.sumber = "CA" DESC  , pvd.urutan;

-- RID=1696 | MENU=14 | ITEM=10 | RQUERY=1 | NAME=Daftar Pembayaran Piutang (PV) Global | FILE=ListPaymentReceipt2
SELECT    pv.pvid,   pv.pvtgl ,   pv.pvnotransaksi ,   kc.knama AS pvcustomer,   pv.pvuraian ,   pv.pvmatauang ,   pv.pvkurs ,   st.nama AS pvstatus,    CASE sumber  	WHEN "SI" then si.sinotransaksi   	WHEN "RP" then rp.rpnotransaksi   	WHEN "IP" then ip.ipnotransaksi   	WHEN "AS" then ass.asnotransaksi   	WHEN "SR" then sr.srnotransaksi   	WHEN "CA" then CONCAT(pvd.sumber,"(",coa.cnomor, ")")  END as notransaksi ,  CASE sumber  	WHEN "SI" then si.sitgl   	WHEN "RP" then rp.rptgl  	WHEN "IP" then ip.iptgl  	WHEN "AS" then ass.astgl  	WHEN "SR" then sr.srtgl  	END as tanggal,   pvd.sumber ,   pvd.matauang ,   pvd.kurs ,   pvd.totaltransaksi ,   pvd.terbayar ,   pvd.rencana ,   pvd.jmlbayar,   pvd.jmlbayarvalas,   CASE sumber  	WHEN "SI" then si.sitermin   	WHEN "RP" then rp.rptermin  	WHEN "IP" then ip.iptermin  	WHEN "AS" then ass.astermin  	WHEN "SR" then sr.srtermin  	END as termin FROM m5_pv pv  JOIN m1_contact kc ON pv.pvcustomer = kc.kid  JOIN m0_status st ON pv.pvstatus = st.kode    JOIN m5_pv_detail pvd ON pv.pvid = pvd.idpv  LEFT JOIN m5_si si ON pvd.sumber = si.sisumber AND pvd.idtransaksi = si.siid  LEFT JOIN m5_rp rp ON pvd.sumber = rp.rpsumber AND pvd.idtransaksi = rp.rpid  LEFT JOIN m5_ip ip ON pvd.sumber = ip.ipsumber AND pvd.idtransaksi = ip.ipid  LEFT JOIN m5_as ass ON pvd.sumber = ass.assumber AND pvd.idtransaksi = ass.asid  LEFT JOIN m5_sr sr ON pvd.sumber = sr.srsumber AND pvd.idtransaksi = sr.srid  LEFT JOIN m1_coa coa ON pvd.rekhutangpiutang = coa.cnomor ORDER BY pv.pvtgl, pv.pvid , pv.pvnotransaksi , pvd.urutan;

-- RID=5015 | MENU=14 | ITEM=11 | RQUERY=1 | NAME=Pembayaran Piutang (PV) 1/2 Letter Makmur | FILE=PaymentReceiptdetail_new_makmur
SELECT      	pv.pvid,   	pv.pvtgl ,   	pv.pvnotransaksi ,   	kc.knama AS pvcustomer,   	pv.pvuraian ,   	pv.pvmatauang ,   	pv.pvkurs ,   	st.nama AS pvstatus,    	CASE sumber  	WHEN "SI" then si.sinotransaksi   	WHEN "RP" then rp.rpnotransaksi   	WHEN "IP" then ip.ipnotransaksi   	WHEN "AS" then ass.asnotransaksi   	WHEN "SR" then sr.srnotransaksi   	WHEN "CA" then CONCAT(pvd.sumber,"(",coa.cnomor, ")")  END as notransaksi ,  CASE sumber  	WHEN "SI" then si.sitgl   	WHEN "RP" then rp.rptgl  	WHEN "IP" then ip.iptgl  	WHEN "AS" then ass.astgl  	WHEN "SR" then sr.srtgl  	END as tanggal,   pvd.sumber ,   pvd.matauang ,   pvd.kurs ,   /*AR = SI , RP , CA  AP =  IP , AS, SR, */  pvd.totaltransaksi ,   pvd.terbayar ,   CASE sumber  	WHEN "SI" then pvd.jmlbayar  	WHEN "RP" then pvd.jmlbayar  	WHEN "IP" then (pvd.jmlbayar * -1)  	WHEN "AS" then (pvd.jmlbayar * -1)  	WHEN "SR" then (pvd.jmlbayar * -1)  	WHEN "CA" then pvd.jmlbayar  END as jmlbayar ,  CASE sumber  	WHEN "SI" then pvd.jmlbayarvalas  	WHEN "RP" then pvd.jmlbayarvalas  	WHEN "IP" then (pvd.jmlbayarvalas * -1)  	WHEN "AS" then (pvd.jmlbayarvalas * -1)  	WHEN "SR" then (pvd.jmlbayarvalas * -1)  	WHEN "CA" then pvd.jmlbayarvalas  END as jmlbayarvalas,    CASE sumber  	WHEN "SI" then si.sitermin   	WHEN "RP" then rp.rptermin  	WHEN "IP" then ip.iptermin  	WHEN "AS" then ass.astermin  	WHEN "SR" then sr.srtermin  	END as termin,   CASE sumber  	WHEN "SI" then si.sicatatan  	WHEN "RP" then rp.rpcatatan  	WHEN "IP" then ip.ipcatatan  	WHEN "AS" then ass.ascatatan  	WHEN "SR" then sr.srcatatan  	END as catatan      FROM m5_pv pv  JOIN m1_contact kc ON pv.pvcustomer = kc.kid  JOIN m0_status st ON pv.pvstatus = st.kode    JOIN m5_pv_detail pvd ON pv.pvid = pvd.idpv  LEFT JOIN m5_si si ON pvd.sumber = si.sisumber AND pvd.idtransaksi = si.siid  LEFT JOIN m5_rp rp ON pvd.sumber = rp.rpsumber AND pvd.idtransaksi = rp.rpid  LEFT JOIN m5_ip ip ON pvd.sumber = ip.ipsumber AND pvd.idtransaksi = ip.ipid  LEFT JOIN m5_as ass ON pvd.sumber = ass.assumber AND pvd.idtransaksi = ass.asid  LEFT JOIN m5_sr sr ON pvd.sumber = sr.srsumber AND pvd.idtransaksi = sr.srid  LEFT JOIN m1_coa coa ON pvd.rekhutangpiutang = coa.cnomor ORDER BY pv.pvtgl, pv.pvid , pv.pvnotransaksi , pvd.sumber = "SI" DESC , pvd.sumber = "RP" DESC , pvd.sumber = "IP" DESC , pvd.sumber = "AS" DESC , pvd.sumber = "SR" DESC, pvd.sumber = "CA" DESC  , pvd.urutan;

-- RID=5016 | MENU=14 | ITEM=12 | RQUERY=1 | NAME=Pembayaran Piutang (PV) 1 Letter Makmur | FILE=PaymentReceiptdetail1_new_makmur
SELECT      	pv.pvid,   	pv.pvtgl ,   	pv.pvnotransaksi ,   	kc.knama AS pvcustomer,   	pv.pvuraian ,   	pv.pvmatauang ,   	pv.pvkurs ,   	st.nama AS pvstatus,    	CASE sumber  	WHEN "SI" then si.sinotransaksi   	WHEN "RP" then rp.rpnotransaksi   	WHEN "IP" then ip.ipnotransaksi   	WHEN "AS" then ass.asnotransaksi   	WHEN "SR" then sr.srnotransaksi   	WHEN "CA" then CONCAT(pvd.sumber,"(",coa.cnomor, ")")  END as notransaksi ,  CASE sumber  	WHEN "SI" then si.sitgl   	WHEN "RP" then rp.rptgl  	WHEN "IP" then ip.iptgl  	WHEN "AS" then ass.astgl  	WHEN "SR" then sr.srtgl  	END as tanggal,   pvd.sumber ,   pvd.matauang ,   pvd.kurs ,   /*AR = SI , RP , CA  AP =  IP , AS, SR, */  pvd.totaltransaksi ,   pvd.terbayar ,   CASE sumber  	WHEN "SI" then pvd.jmlbayar  	WHEN "RP" then pvd.jmlbayar  	WHEN "IP" then (pvd.jmlbayar * -1)  	WHEN "AS" then (pvd.jmlbayar * -1)  	WHEN "SR" then (pvd.jmlbayar * -1)  	WHEN "CA" then pvd.jmlbayar  END as jmlbayar ,  CASE sumber  	WHEN "SI" then pvd.jmlbayarvalas  	WHEN "RP" then pvd.jmlbayarvalas  	WHEN "IP" then (pvd.jmlbayarvalas * -1)  	WHEN "AS" then (pvd.jmlbayarvalas * -1)  	WHEN "SR" then (pvd.jmlbayarvalas * -1)  	WHEN "CA" then pvd.jmlbayarvalas  END as jmlbayarvalas,    CASE sumber  	WHEN "SI" then si.sitermin   	WHEN "RP" then rp.rptermin  	WHEN "IP" then ip.iptermin  	WHEN "AS" then ass.astermin  	WHEN "SR" then sr.srtermin  	END as termin,   CASE sumber  	WHEN "SI" then si.sicatatan  	WHEN "RP" then rp.rpcatatan  	WHEN "IP" then ip.ipcatatan  	WHEN "AS" then ass.ascatatan  	WHEN "SR" then sr.srcatatan  	END as catatan      FROM m5_pv pv  JOIN m1_contact kc ON pv.pvcustomer = kc.kid  JOIN m0_status st ON pv.pvstatus = st.kode    JOIN m5_pv_detail pvd ON pv.pvid = pvd.idpv  LEFT JOIN m5_si si ON pvd.sumber = si.sisumber AND pvd.idtransaksi = si.siid  LEFT JOIN m5_rp rp ON pvd.sumber = rp.rpsumber AND pvd.idtransaksi = rp.rpid  LEFT JOIN m5_ip ip ON pvd.sumber = ip.ipsumber AND pvd.idtransaksi = ip.ipid  LEFT JOIN m5_as ass ON pvd.sumber = ass.assumber AND pvd.idtransaksi = ass.asid  LEFT JOIN m5_sr sr ON pvd.sumber = sr.srsumber AND pvd.idtransaksi = sr.srid  LEFT JOIN m1_coa coa ON pvd.rekhutangpiutang = coa.cnomor ORDER BY pv.pvtgl, pv.pvid , pv.pvnotransaksi , pvd.sumber = "SI" DESC , pvd.sumber = "RP" DESC , pvd.sumber = "IP" DESC , pvd.sumber = "AS" DESC , pvd.sumber = "SR" DESC, pvd.sumber = "CA" DESC  , pvd.urutan;

-- RID=50001658 | MENU=14 | ITEM=13 | RQUERY=1 | NAME=Transaksi PV | FILE=M5PV
SELECT     pvid , pvcabang , pvlokasi , pvgudang , pvsumber , pvautonotransaksi , pvnotransaksi , pvtgl , pvkodepa , pvcustomer , pvcustomerkontak , pv1alamat1 , pv1alamat2 ,   pv1alamat3 , pv2alamat1 , pv2alamat2 , pv2alamat3 , pvbagianpenjualan , pvbagianterima , pvuraian , pvcatatan , pvnoref , pvtgl , pvcarabayar , pvtglbayar , pvmatauang ,   pvkurs , pvtotalap , pvtotalapvalas , pvtotalar , pvtotalarvalas , pvbayar , pvbayarvalas , pvselisihkurs , pvrekselisihkurs , pvdiskontermin , pvdiskonterminvalas ,   pvrekdiskontermin , pvidic , pvstatus , pvstatussebelumnya , pvjmlrevisi , pvcetakanke , pvinputuser , pvinputtgl , pvmodifikasiuser , pvmodifikasitgl , pvposting , pvpostingtgl ,   pvisclose , idpvdetail , idpv , sumber , idtransaksi , matauang , kurs , totaltransaksi , terbayar ,rencana , sisa , jmlbayar , jmlbayarvalas , diskontermin , jmldiskontermin ,   jmldiskonterminvalas , nogiro , rekhutangpiutang , catatan , costcenter , divisi , subdivisi , proyek , idicdetail , urutan , isclose   FROM m5_pv pv  JOIN m5_pv_detail pvd ON pv.pvid = pvd.idpv ORDER BY pv.pvtgl ASC , pv.pvid ASC , pvd. idpv ASC;

-- RID=1717 | MENU=16 | ITEM=16 | RQUERY=1 | NAME=Sales Retur (SR) Valas 1 Letter | FILE=salesreturdetail_valas2
SELECT    	sr.srid ,   	sr.srnotransaksi,   	sr.srtgl ,   	kc.knama AS srcustomer,   	ks.knama AS srbagianpenjualan ,   	w.wnama AS srgudang,   	st.nama AS srstatus ,   	sr.sruraian,   	sr.srmatauang ,   	sr.srkurs ,   	sr.srdiskonpersen , sr.srjmldiskon ,   	sr.srbiayalain ,   	sr.srtotalpajak1detail,     	b.bkode ,   	srd.namabarang,   	si.sinotransaksi,   	srd.jml ,   	srd.satuan ,   	srd.harga,   	(srd.harga * srd.kurs) AS hargavalas ,   	srd.hpp ,   	srd.diskon ,   	((srd.jml * srd.harga) - srd.jmldiskon) AS total ,  ((srd.jml * (srd.harga * srd.kurs)) - (srd.jmldiskon * srd.kurs)) AS totalvalas FROM m5_sr sr   JOIN m1_contact kc ON sr.srcustomer = kc.kid  JOIN m1_contact ks ON sr.srbagianpenjualan = ks.kid  JOIN m1_warehouse w ON sr.srgudang = w.wkode  JOIN m0_status st ON sr.srstatus = st.kode    JOIN m5_sr_detail srd ON sr.srid = srd.idsr  JOIN m1_item b ON srd.idbarang = b.bid  LEFT JOIN m5_si_detail sid ON srd.idsidetail = sid.idsidetail   LEFT JOIN m5_si si ON sid.idsi = si.siid WHERE (sr.srmatauang <> "IDR" AND sr.srmatauang <> "RP") GROUP BY sr.srtgl , sr.srid , sr.srnotransaksi , srd.urutan;

-- RID=197 | MENU=26 | ITEM=1 | RQUERY=1 | NAME=Assembly | FILE=Assembly
SELECT FROM coba WHERE coba ORDER BY coba;

-- RID=455 | MENU=41 | ITEM=1 | RQUERY=1 | NAME=Daftar Piutang Ongkos Kirim (RP) | FILE=daftarpiutangongkoskirim
SELECT    rp.rpid ,   rp.rptgl ,   rp.rpnotransaksi ,   kc.knama AS rpkontak ,   rp.rpnorek ,   c.cnama ,   rp.rpuraian ,   rp.rpmatauang ,   rp.rpkurs ,   st.nama AS rpstatus ,     pm.nama AS carabayar ,   CASE carabayar   	WHEN 2 THEN rpp.rekgiro  	ELSE rpp.rekbank   END AS noakun,   CASE carabayar   WHEN 2 THEN coaa.cnama   ELSE coa.cnama   END AS namaakun,   rpp.jumlah ,   rpp.jumlahvalas ,   rpp.bank ,   rpp.nogiro,   rpp.tgljt ,   rpp.noacbank FROM m5_rp rp   join m1_contact kc ON rp.rpkontak = kc.kid  JOIN m1_coa c ON rp.rpnorek = c.cnomor   JOIN m0_status st ON rp.rpstatus = st.kode    JOIN m5_rp_pay rpp ON rp.rpid = rpp.idrp  JOIN m0_payment_method pm ON rpp.carabayar  = pm.kode  LEFT JOIN m1_coa coa ON rpp.rekbank = coa.cnomor   LEFT JOIN m1_coa coaa ON rpp.rekgiro = coaa.cnomor ORDER BY rp.rptgl , rp.rpid , rp.rpnotransaksi , rpp.urutan;

-- RID=456 | MENU=41 | ITEM=2 | RQUERY=1 | NAME=Piutang Ongkos Kirim (RP) 1/2 Letter | FILE=piutangongkoskirimdetail
SELECT    	rp.rpid ,   	rp.rptgl ,   	rp.rpnotransaksi ,   	kc.knama AS rpkontak ,   	rp.rpnorek ,   	c.cnama ,   	rp.rpuraian ,   	rp.rpmatauang ,   	rp.rpkurs ,   	st.nama AS rpstatus ,     	pm.nama AS carabayar ,   	CASE carabayar   	WHEN 2 THEN rpp.rekgiro  	ELSE rpp.rekbank   END AS noakun,   CASE carabayar   WHEN 2 THEN coaa.cnama   ELSE coa.cnama   END AS namaakun,   rpp.jumlah ,   rpp.jumlahvalas ,   rpp.bank ,   rpp.nogiro,   rpp.tgljt ,   rpp.noacbank, rpp.matauang FROM m5_rp rp   join m1_contact kc ON rp.rpkontak = kc.kid  JOIN m1_coa c ON rp.rpnorek = c.cnomor   JOIN m0_status st ON rp.rpstatus = st.kode    JOIN m5_rp_pay rpp ON rp.rpid = rpp.idrp  JOIN m0_payment_method pm ON rpp.carabayar  = pm.kode  LEFT JOIN m1_coa coa ON rpp.rekbank = coa.cnomor   LEFT JOIN m1_coa coaa ON rpp.rekgiro = coaa.cnomor ORDER BY rp.rptgl , rp.rpid , rp.rpnotransaksi , rpp.urutan;

