-- RID=585 | MENU=50 | ITEM=1 | RQUERY=1 | NAME=Penjualan Per Customer | FILE=penjualanpercustomer
SELECT    	kc.kkode AS kodecustomer ,   	kc.knama AS sicustomer ,     	si.sinotransaksi ,   	si.sitgl ,   	ks.kkode AS kodesalesman ,   	ks.knama AS sibagianpenjualan ,   	si.sikurs ,   	si.simatauang ,   	SUM((sid.jml * sid.harga) - sid.jmldiskon) AS total ,     	si.sijmldiskon ,   	(si.sitotalpajak1detail + si.sitotalpajak2detail) AS sitotalpajak1detail  ,   	si.sibiayalain ,   	si.sitotaltransaksi ,  SUM(sid.jml) as jml,  sid.satuan   FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi   JOIN m1_contact kc ON si.sicustomer = kc.kid   JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid WHERE (si.sistatus  = 2 OR si.sistatus = 3 OR si.sistatus = 4 OR si.sistatus  = 7 ) GROUP BY kc.kkode  ASC, si.sicustomer ASC , si.sitgl ASC , si.siid ASC ORDER BY kc.kkode  ASC, si.sicustomer ASC , si.sitgl ASC , si.siid ASC;

-- RID=586 | MENU=50 | ITEM=2 | RQUERY=1 | NAME=Penjualan Per Salesman | FILE=penjualanpersales
SELECT        CASE si.sihargatermasukpajak  	WHEN 0 THEN (si.sitotalpajak1detail * 0)  	WHEN 1 THEN (si.sitotalpajak1detail * 1)   END AS pengurangansubt ,     si.sihargatermasukpajak ,   CASE si.sihargatermasukpajak   	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS caption ,     	si.sibagianpenjualan AS grup ,   	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	si.sitermin ,     si.sitgljatuhtempo,  	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen ,     si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,     CASE si.sihargatermasukpajak  	WHEN 0 THEN (si.sitotalpajak1detail * 1)  	WHEN 1 THEN (si.sitotalpajak1detail * 0)   END AS pajak ,     	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   CASE b.bjenis  	WHEN "P" THEN      CASE when b.bkategori <> "JS" then sid.jml     else 0 end  	WHEN "J" THEN 0  END AS jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total ,    (CASE si.sihargatermasukpajak     WHEN 0 THEN si.sitotal - si.sijmldiskon + si.sitotalpajak1detail + si.sitotalpajak2detail + si.sibiayalain    ELSE si.sitotal - si.sijmldiskon + si.sibiayalain    END) as sitotalnew,    si.sijmluangmuka,    si.sijmlbayar - si.sijmlkembali as sijmlbayar,  	si.sitotaltransaksi - si.sijmlbayar + si.sijmlkembali as sisisa,    si.sitotaltransaksi,     CASE simatauang   	WHEN "USD" THEN (sitotaltransaksi * 1)    ELSE 0  END AS "TOTALUSD" ,     CASE simatauang   	WHEN "RMB" THEN (sitotaltransaksi * 1)    ELSE 0  END AS "TOTALRMB" ,     CASE simatauang   	WHEN "IDR" THEN (sitotaltransaksi * 1 )   	ELSE  (sitotaltransaksi * sikurs)   END AS "TOTALRP" FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid WHERE (si.sistatus  = 2 OR si.sistatus = 3 OR si.sistatus = 4 OR si.sistatus  = 7 ) ORDER BY si.sibagianpenjualan , si.sitgl , si.siid, si.sinotransaksi , sid.urutan;

-- RID=587 | MENU=50 | ITEM=3 | RQUERY=1 | NAME=Penjualan Per Produk | FILE=penjualanperproduk
SELECT    	CASE si.sihargatermasukpajak  	WHEN 0 THEN (sid.jmlpajak1 * 0)  	WHEN 1 THEN (sid.jmlpajak1 * 1)   END AS pengurangansubt ,     si.sihargatermasukpajak ,   CASE si.sihargatermasukpajak   	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS caption ,     CASE si.sihargatermasukpajak  	WHEN 0 THEN (sid.jmlpajak1 * 1)  	WHEN 1 THEN (sid.jmlpajak1 * 0)   END AS pajak ,     	sid.idbarang AS grup ,     	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	si.sitermin ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,     	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total  ,    sid.jmlpajak1 FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid WHERE (si.sistatus  = 2 OR si.sistatus = 3 OR si.sistatus = 4 OR si.sistatus  = 7 ) ORDER BY sid.idbarang , b.bkode , sid.namabarang ,  si.sitgl , si.siid, si.sinotransaksi , sid.urutan;

-- RID=1172 | MENU=50 | ITEM=4 | RQUERY=1 | NAME=Penjualan Per Customer Detail | FILE=penjualanpercustomer_detail
SELECT    si.sihargatermasukpajak ,   CASE si.sihargatermasukpajak   	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS caption ,   	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,  CASE si.sihargatermasukpajak  	WHEN 0 THEN (si.sitotalpajak1detail * 1)  	WHEN 1 THEN (si.sitotalpajak1detail * 0)   END AS pajak ,     	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total    FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid WHERE (si.sistatus  = 2 OR si.sistatus = 3 OR si.sistatus = 4 OR si.sistatus  = 7 ) ORDER BY si.sicustomer , si.sitgl ,si.sinotransaksi , sid.urutan;

-- RID=1601 | MENU=50 | ITEM=5 | RQUERY=1 | NAME=Penjualan Per Kategori Barang | FILE=pernjualanperkategoribarang
SELECT    CASE si.sihargatermasukpajak  	WHEN 0 THEN (sid.jmlpajak1 * 0)  	WHEN 1 THEN (sid.jmlpajak1 * 1)   END AS pengurangansubt ,     si.sihargatermasukpajak ,   CASE si.sihargatermasukpajak   	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS caption ,     CASE si.sihargatermasukpajak  	WHEN 0 THEN (sid.jmlpajak1 * 1)  	WHEN 1 THEN (sid.jmlpajak1 * 0)   END AS pajak ,       	sid.idbarang AS grup ,     	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	si.sitermin ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,     b.bkategori ,  ic.icnama AS kategori,   	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total ,   sid.jmlpajak1 FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid      JOIN m1_item_category ic ON b.bkategori = ic.ickode WHERE (si.sistatus  = 2 OR si.sistatus = 3 OR si.sistatus = 4 OR si.sistatus  = 7 ) ORDER BY b.bkategori, sid.idbarang , b.bkode , sid.namabarang ,  si.sitgl , si.siid, si.sinotransaksi , sid.urutan;

-- RID=1620 | MENU=50 | ITEM=6 | RQUERY=1 | NAME=Penjualan Per Produk Per Area | FILE=laporanpenjualan_Perproduk_Perarea
SELECT    	si.siid , si.sicustomtext2 ,   	a.anama , sid.idbarang , b.bkode  , b.bnama  , SUM(sid.jmlbarang) / b.bjmllapangan AS jumlah ,   	MONTH(si.sitgl) AS bulan FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b ON sid.idbarang = b.bid   LEFT JOIN m1_area a ON si.sicustomtext2 = a.akode GROUP BY b.bkode ASC, sicustomtext2 ASC , MONTH(si.sitgl) ASC ORDER BY b.bkode ASC, sicustomtext2 ASC , MONTH(si.sitgl) ASC;

-- RID=1621 | MENU=50 | ITEM=7 | RQUERY=1 | NAME=Penjualan Per Area All Produk | FILE=laporanpenjualan_PerArea_AllProduk
SELECT    	si.siid , si.sicustomtext2 ,   	a.anama , sid.idbarang , b.bkode  , b.bnama  ,  SUM(sid.jmlbarang) / b.bjmllapangan AS jumlah ,   	MONTH(si.sitgl) AS bulan FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b ON sid.idbarang = b.bid   LEFT JOIN m1_area a ON si.sicustomtext2 = a.akode GROUP BY sicustomtext2 ASC , b.bkode ASC, MONTH(si.sitgl) ASC ORDER BY sicustomtext2 ASC , b.bkode ASC, MONTH(si.sitgl) ASC;

-- RID=50000 | MENU=50 | ITEM=8 | RQUERY=2 | NAME=Penjualan Per Kota Per Produk | FILE=Penjualan_Per_Kota_Per_Produk
SELECT   idlogin,   idmsmq,   userid ,   sitgl ,   sinotransaksi ,   kkode ,   knama ,   kodekota,   kota ,   kodepropinsi ,   propinsi ,   namabarang ,   bkode ,   SUM(jml) AS jml,   satuan ,   harga ,   jmldiskon ,   total ,   sitotalpajak1detail ,   sitotalpajak2detail ,   sibiayalain ,   sijmldiskon ,   sijmluangmuka,   sitotaltransaksi,    tjml  ,   (SUM(jml) / tjml) * 100 AS persen FROM m2r_penjualan GROUP BY kota , bkode ORDER BY kota , bkode;

