SELECT   	idlogin,   	idmsmq,   	userid ,   	sitgl ,   	sinotransaksi ,   	kkode ,   	knama ,   	kota ,   	propinsi ,   	namabarang ,   	bkode ,   	SUM(jml) AS jml,   	satuan ,   	harga ,   	jmldiskon ,   	SUM(total) AS total ,   	sitotalpajak1detail ,   	sitotalpajak2detail ,   	sibiayalain ,   	sijmldiskon ,   	sijmluangmuka,   	sitotaltransaksi,    	tjml  ,   	(SUM(jml) / tjml) * 100 AS persen FROM m2r_penjualan GROUP BY bkode, kkode ORDER BY bkode;

-- RID=50006 | MENU=50 | ITEM=14 | RQUERY=1 | NAME=Penjualan Per Customer (Periode Tgl) | FILE=Penjualan_Per_Customer_Periode_Tgl
SELECT    si.sicustomer ,    k.kkode ,   si.simatauang,    k.knama ,   sum(sid.jml) as jml,  sid.satuan , sid.urutan ,    sum(((sid.jml * sid.harga) - sid.jmldiskon) * si.sikurs) AS total,    sum((si.sitotalpajak1detail + sitotalpajak2detail) * si.sikurs) AS pajak ,     si.sihargatermasukpajak ,  CASE si.sihargatermasukpajak 	  WHEN 0 THEN "Belum Termasuk Pajak" 	WHEN 1 THEN "Sudah Termasuk Pajak" END AS "caption" ,     CASE si.sihargatermasukpajak 	  WHEN 0 THEN   sum((((sid.jml * sid.harga) - sid.jmldiskon) + (si.sitotalpajak1detail + sitotalpajak2detail)) * si.sikurs )	  WHEN 1 THEN sum(((sid.jml * sid.harga) - sid.jmldiskon) * si.sikurs) END   AS tataltransaksi ,    sum(si.sitotaltransaksi * si.sikurs) as sitotaltransaksi FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi   JOIN m1_contact k ON si.sicustomer = k.kid WHERE si.sistatus in(2,3,4,7) GROUP BY si.sicustomer ASC , sid.urutan ASC;

