-- RID=50010 | MENU=50 | ITEM=18 | RQUERY=2 | NAME=Penjualan Per Customer (Nilai) (4 Bulan Terakhir) | FILE=m2r_Penjualan_Per_Customer_Nilai_4BulanTerakhir
SELECT   	idlogin,   	idmsmq,   	userid , 	  	sitgl ,   	sinotransaksi ,   	bulan,   	tahun,   	kkode ,   	knama ,   	kota ,   	propinsi ,   	namabarang ,   	bkode ,   	(jml) AS jml,   	satuan ,   	harga ,   	jmldiskon ,   	(total) AS total ,   	sitotalpajak1detail ,   	sitotalpajak2detail ,   	sibiayalain ,   	sijmldiskon ,   	sijmluangmuka,   	sitotaltransaksi,    	tjml  ,   	((jml) / tjml) * 100 AS persen ,   	((total) / (jml)) AS rata2 ,   	SUM(bulan1) AS bulan1,   	SUM(bulan2) AS bulan2,   	SUM(bulan3) AS bulan3 ,   	SUM(bulan4) AS bulan4,     	SUM(qtybulan1) AS qtybulan1,   	SUM(qtybulan2) AS qtybulan2,   	SUM(qtybulan3) AS qtybulan3 ,   	SUM(qtybulan4) AS qtybulan4,     	CASE dbulan - 3   	WHEN 1 THEN "Januari"  	WHEN 2 THEN "Februari"  	WHEN 3 THEN "Maret"  	WHEN 4 THEN "April"  	WHEN 5 THEN "Mei"  	WHEN 6 THEN "Juni"  	WHEN 7 THEN "Juli"  	WHEN 8 THEN "Agustus"  	WHEN 9 THEN "September"  	WHEN 10 THEN "Oktober"  	WHEN 11 THEN "November"  	WHEN 12 THEN "Desember"  	WHEN 0 THEN "Desember"  	WHEN "-1" THEN "November"  	WHEN "-2" THEN "Oktober"  END AS b1 ,  CASE dbulan - 2  	WHEN 1 THEN "Januari"  	WHEN 2 THEN "Februari"  	WHEN 3 THEN "Maret"  	WHEN 4 THEN "April"  	WHEN 5 THEN "Mei"  	WHEN 6 THEN "Juni"  	WHEN 7 THEN "Juli"  	WHEN 8 THEN "Agustus"  	WHEN 9 THEN "September"  	WHEN 10 THEN "Oktober"  	WHEN 11 THEN "November"  	WHEN 12 THEN "Desember"  	WHEN 0 THEN "Desember"  	WHEN "-1" THEN "November"  	WHEN "-2" THEN "Oktober"  END AS b2 ,  CASE dbulan - 1  	WHEN 1 THEN "Januari"  	WHEN 2 THEN "Februari"  	WHEN 3 THEN "Maret"  	WHEN 4 THEN "April"  	WHEN 5 THEN "Mei"  	WHEN 6 THEN "Juni"  	WHEN 7 THEN "Juli"  	WHEN 8 THEN "Agustus"  	WHEN 9 THEN "September"  	WHEN 10 THEN "Oktober"  	WHEN 11 THEN "November"  	WHEN 12 THEN "Desember"  	WHEN 0 THEN "Desember"  	WHEN "-1" THEN "November"  	WHEN "-2" THEN "Oktober"  END AS b3 ,     CASE dbulan   	WHEN 1 THEN "Januari"  	WHEN 2 THEN "Februari"  	WHEN 3 THEN "Maret"  	WHEN 4 THEN "April"  	WHEN 5 THEN "Mei"  	WHEN 6 THEN "Juni"  	WHEN 7 THEN "Juli"  	WHEN 8 THEN "Agustus"  	WHEN 9 THEN "September"  	WHEN 10 THEN "Oktober"  	WHEN 11 THEN "November"  	WHEN 12 THEN "Desember"  END AS dbulan FROM m2r_penjualan_per4bulan GROUP BY kkode ORDER BY kkode;

