6 THEN "Juni"  	WHEN 7 THEN "Juli"  	WHEN 8 THEN "Agustus"  	WHEN 9 THEN "September"  	WHEN 10 THEN "Oktober"  	WHEN 11 THEN "November"  	WHEN 12 THEN "Desember"  END AS dbulan FROM m2r_penjualan_per4bulan GROUP BY bkode ORDER BY bkode;

-- RID=50013 | MENU=50 | ITEM=21 | RQUERY=2 | NAME=Penjualan Per Produk (Nilai) (4 Bulan Terakhir) | FILE=Penjualan_Per_Produk_Nominal_4BulanTerakhir
SELECT   	idlogin,   	idmsmq,   	userid , 	  	sitgl ,   	sinotransaksi ,   	bulan,   	tahun,   	kkode ,   	knama ,   	kota ,   	propinsi ,   	namabarang ,   	bkode ,   	(jml) AS jml,   	satuan ,   	harga ,   	jmldiskon ,   	(total) AS total ,   	sitotalpajak1detail ,   	sitotalpajak2detail ,   	sibiayalain ,   	sijmldiskon ,   	sijmluangmuka,   	sitotaltransaksi,    	tjml  ,   	((jml) / tjml) * 100 AS persen ,   	((total) / (jml)) AS rata2 ,   	SUM(bulan1) AS bulan1,   	SUM(bulan2) AS bulan2,   	SUM(bulan3) AS bulan3 ,   	SUM(bulan4) AS bulan4,     	SUM(qtybulan1) AS qtybulan1,   	SUM(qtybulan2) AS qtybulan2,   	SUM(qtybulan3) AS qtybulan3 ,   	SUM(qtybulan4) AS qtybulan4,     	CASE dbulan - 3   	WHEN 1 THEN "Januari"  	WHEN 2 THEN "Februari"  	WHEN 3 THEN "Maret"  	WHEN 4 THEN "April"  	WHEN 5 THEN "Mei"  	WHEN 6 THEN "Juni"  	WHEN 7 THEN "Juli"  	WHEN 8 THEN "Agustus"  	WHEN 9 THEN "September"  	WHEN 10 THEN "Oktober"  	WHEN 11 THEN "November"  	WHEN 12 THEN "Desember"  	WHEN 0 THEN "Desember"  	WHEN "-1" THEN "November"  	WHEN "-2" THEN "Oktober"  END AS b1 ,  CASE dbulan - 2  	WHEN 1 THEN "Januari"  	WHEN 2 THEN "Februari"  	WHEN 3 THEN "Maret"  	WHEN 4 THEN "April"  	WHEN 5 THEN "Mei"  	WHEN 6 THEN "Juni"  	WHEN 7 THEN "Juli"  	WHEN 8 THEN "Agustus"  	WHEN 9 THEN "September"  	WHEN 10 THEN "Oktober"  	WHEN 11 THEN "November"  	WHEN 12 THEN "Desember"  	WHEN 0 THEN "Desember"  	WHEN "-1" THEN "November"  	WHEN "-2" THEN "Oktober"  END AS b2 ,  CASE dbulan - 1  	WHEN 1 THEN "Januari"  	WHEN 2 THEN "Februari"  	WHEN 3 THEN "Maret"  	WHEN 4 THEN "April"  	WHEN 5 THEN "Mei"  	WHEN 6 THEN "Juni"  	WHEN 7 THEN "Juli"  	WHEN 8 THEN "Agustus"  	WHEN 9 THEN "September"  	WHEN 10 THEN "Oktober"  	WHEN 11 THEN "November"  	WHEN 12 THEN "Desember"  	WHEN 0 THEN "Desember"  	WHEN "-1" THEN "November"  	WHEN "-2" THEN "Oktober"  END AS b3 ,     CASE dbulan   	WHEN 1 THEN "Januari"  	WHEN 2 THEN "Februari"  	WHEN 3 THEN "Maret"  	WHEN 4 THEN "April"  	WHEN 5 THEN "Mei"  	WHEN 6 THEN "Juni"  	WHEN 7 THEN "Juli"  	WHEN 8 THEN "Agustus"  	WHEN 9 THEN "September"  	WHEN 10 THEN "Oktober"  	WHEN 11 THEN "November"  	WHEN 12 THEN "Desember"  END AS dbulan FROM m2r_penjualan_per4bulan GROUP BY bkode ORDER BY bkode;

-- RID=500014 | MENU=50 | ITEM=22 | RQUERY=1 | NAME=Penjualan Per Customer Detail | FILE=penjualan_per_customer_detail
SELECT    	si.sicustomer ,   	k.kkode ,   	k.knama ,     	si.sitgl ,   	si.sinotransaksi ,   	si.siid ,   	si.simatauang ,   	si.sikurs ,     	b.bkode ,   	b.bnama ,   	sid.namabarang ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.jmldiskon ,     	(sid.jml * sid.harga) - sid.jmldiskon AS total ,   	CASE b.bkp  	   WHEN 0 THEN ((sid.jml * sid.harga) - sid.jmldiskon) 	  WHEN 1 THEN ((((sid.jml * sid.harga) - sid.jmldiskon) / 11) * 10)    END AS DPP ,     CASE b.bkp  	   WHEN 0 THEN 0  	  WHEN 1 THEN (((sid.jml * sid.harga) - sid.jmldiskon) / 11)    END as pajaak ,       ((CASE b.bkp  	  WHEN 0 THEN 0  	  WHEN 1 THEN (((sid.jml * sid.harga) - sid.jmldiskon) / 11)   END) + (CASE b.bkp  	  WHEN 0 THEN ((sid.jml * sid.harga) - sid.jmldiskon) 	  WHEN 1 THEN ((((sid.jml * sid.harga) - sid.jmldiskon) / 11) * 10)   END)) AS hasil FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi   JOIN m1_contact k ON si.sicustomer = k.kid   JOIN m1_item b ON sid.idbarang = b.bid ORDER BY si.sicustomer ASC , si.sitgl ASC, si.siid ASC, si.sinotransaksi ASC;

-- RID=5000015 | MENU=50 | ITEM=23 | RQUERY=1 | NAME=Penjualan Per Salesman Per Customer Per Barang | FILE=SI_persales_percustomer_perbarang
SELECT    	d.dpnama AS bdepartemen ,     k.kkode as kodesalesman ,   k.knama AS sibagianpenjualan ,   kc.kkode AS kodecustomer ,   kc.knama AS sicustomer ,     si.sitgl ,   si.sinotransaksi ,   kc.k1alamat1 ,     sid.idbarang ,   b.bkode ,   b.bnama ,   SUM(sid.jml) jml ,   sid.harga ,   SUM(sid.jmldiskon) AS jmldiskon ,   SUM((sid.harga-(sid.jmldiskon / sid.jml))* sid.jml ) AS total FROM m5_si si  JOIN m5_si_detail sid ON si.siid = sid.idsi   JOIN m1_contact k ON si.sibagianpenjualan = k.kid  JOIN m1_contact kc ON si.sicustomer = kc.kid   JOIN m1_item b ON sid.idbarang = b.bid   JOIN m1_department d ON b.bdepartemen = d.dpkode GROUP BY b.bdepartemen , si.sibagianpenjualan ASC, si.sicustomer ASC, si.siid ASC , sid.idbarang ASC ORDER BY b.bdepartemen , si.sibagianpenjualan ASC, si.sicustomer ASC, si.siid ASC , sid.idbarang ASC;

-- RID=50000543 | MENU=50 | ITEM=24 | RQUERY=1 | NAME=Omset Penjualan Per Salesman (Penjualan dan Retur) | FILE=penjualanpersales_2
SELECT * FROM (    (SELECT    	si.siid ,     	k.kkode AS grup ,   	k.knama AS sibagianpenjualan ,   	si.sinotransaksi , si.sitgl ,   	c.knama AS sicustomer  ,   	si.simatauang ,   	si.sikurs ,   	SUM(CASE si.sihargatermasukpajak   	WHEN 0 THEN ((sid.jml * sid.harga) - sid.jmldiskon)  	WHEN 1 THEN ((sid.jml * sid.harga) - sid.jmldiskon) - sid.jmlpajak1  END) AS total ,   si.sidiskonpersen ,   si.sibiayalain ,   si.sitotalpajak1detail ,   si.sitotaltransaksi    FROM m5_si si   JOIN m1_contact k ON si.sibagianpenjualan = k.kid  JOIN m1_contact c ON si.sicustomer = c.kid  JOIN m5_si_detail sid ON si.siid = sid.idsi     GROUP BY si.sibagianpenjualan ASC , si.sitgl ASC , si.siid ASC  ORDER BY si.sibagianpenjualan ASC , si.sitgl ASC , si.siid ASC)    UNION ALL     (SELECT    	sr.srid AS siid ,   	k.kkode AS grup ,   	k.knama AS sibagianpenjualan ,   	sr.srnotransaksi AS sinotransaksi , sr.srtgl AS sitgl ,   	c.knama AS sicustomer  ,   	sr.srmatauang AS simatauang ,   	sr.srkurs AS sikurs ,   	SUM(CASE sr.srhargatermasukpajak   	WHEN 0 THEN ((srd.jml * srd.harga) - srd.jmldiskon)  	WHEN 1 THEN ((srd.jml * srd.harga) - srd.jmldiskon) - srd.jmlpajak1  END) * -1  AS total ,   (sr.srdiskonpersen * -1) AS sidiskonpersen ,   (sr.srbiayalain * -1) AS sibiayalain ,   (sr.srtotalpajak1detail * -1) AS sitotalpajak1detail ,   (sr.srtotaltransaksi * -1) AS sitotaltransaksi    FROM m5_sr sr  JOIN m1_contact k ON sr.srbagianpenjualan = k.kid  JOIN m1_contact c ON sr.srcustomer = c.kid  JOIN m5_sr_detail srd ON sr.srid = srd.idsr     GROUP BY sr.srbagianpenjualan ASC , sr.srtgl ASC , sr.srid ASC  ORDER BY sr.srbagianpenjualan ASC , sr.srtgl ASC , sr.srid ASC)    ) AS penjualan ORDER BY sibagianpenjualan ASC , sitgl ASC , siid ASC;

-- RID=50000596 | MENU=50 | ITEM=25 | RQUERY=1 | NAME=Penjualan Per Salesman Per Produk | FILE=Penjualan Per Salesman Per Produk
SELECT   	idlogin,   	idmsmq,   	userid ,   	sitgl ,   	sinotransaksi ,   	kkode ,   	knama ,   	kota ,   	propinsi ,   	namabarang ,   	bkode ,   	SUM(jml) AS jml,   	satuan ,   	harga ,   	jmldiskon ,   	SUM(total) AS total ,   	sitotalpajak1detail ,   	sitotalpajak2detail ,   	sibiayalain ,   	sijmldiskon ,   	sijmluangmuka,   	sitotaltransaksi,    	tjml  ,   	(SUM(jml) / tjml) * 100 AS persen FROM m2r_penjualan GROUP BY kkode, bkode ORDER BY kkode;

-- RID=50000610 | MENU=50 | ITEM=26 | RQUERY=1 | NAME=Rekap Penjualan Salesman | FILE=penjualanpersales_rekap
SELECT    	k.kkode ,   	k.knama ,   	SUM(si.sitotaltransaksi) AS total    FROM m5_si si   JOIN m1_contact k ON si.sibagianpenjualan = k.kid    GROUP BY si.sibagianpenjualan ASC ORDER BY si.sibagianpenjualan ASC;

-- RID=50000611 | MENU=50 | ITEM=27 | RQUERY=1 | NAME=Penjualan Per Item Per Pelanggan | FILE=penjualan per item per pelanggan
SELECT    	b.bkode ,  	b.bnama ,   	si.sitgl ,   	si.sinotransaksi ,   	k.knama ,   	SUM(sid.jml) AS jml ,   	sid.satuan ,   	sid.harga ,   	SUM(sid.jml * sid.harga) AS total FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi     JOIN m1_item b ON sid.idbarang = b.bid  JOIN m1_contact k ON si.sicustomer = k.kid   GROUP BY b.bnama ASC , si.sicustomer ASC , si.sitgl ASC , si.sinotransaksi ASC ORDER BY b.bnama ASC , si.sicustomer ASC , si.sitgl ASC , si.sinotransaksi ASC;

-- RID=1015 | MENU=54 | ITEM=1 | RQUERY=1 | NAME=Daftar Penyesuaian Poin Penjualan (SPA) | FILE=SPA
SELECT    	spa.spaid ,   	spa.spatgl ,   	spa.spanotransaksi ,   	st.nama ,   	spa.spauraian ,   	c.kkode ,   	c.knama ,   	spad.poinlama ,   	spad.poinmasuk ,   	spad.poinkeluar ,   	spad.poinbaru ,   	spad.catatan FROM m5_spa spa   JOIN m5_spa_detail spad ON spa.spaid = spad.idspa   JOIN m0_status st ON spa.spastatus = st.kode  JOIN m1_contact c ON spad.kontak = c.kid ORDER BY spa.spaid , spad.urutan;

-- RID=1016 | MENU=54 | ITEM=2 | RQUERY=1 | NAME=Penyesuaian Poin Penjualan (SPA) 1/2 Letter | FILE=SPADETAIL1
SELECT    	spa.spaid ,   	spa.spatgl ,   	spa.spanotransaksi ,   	st.nama ,   	spa.spauraian ,   	c.kkode ,   	c.knama ,   	spad.poinlama ,   	spad.poinmasuk ,   	spad.poinkeluar ,   	spad.poinbaru ,   	spad.catatan FROM m5_spa spa   JOIN m5_spa_detail spad ON spa.spaid = spad.idspa   JOIN m0_status st ON spa.spastatus = st.kode  JOIN m1_contact c ON spad.kontak = c.kid ORDER BY spa.spaid , spad.urutan;

-- RID=1017 | MENU=54 | ITEM=3 | RQUERY=1 | NAME=Penyesuaian Poin Penjualan (SPA) 1 Letter | FILE=SPADETAIL2
SELECT    	spa.spaid ,   	spa.spatgl ,   	spa.spanotransaksi ,   	st.nama ,   	spa.spauraian ,   	c.kkode ,   	c.knama ,   	spad.poinlama ,   	spad.poinmasuk ,   	spad.poinkeluar ,   	spad.poinbaru ,   	spad.catatan FROM m5_spa spa   JOIN m5_spa_detail spad ON spa.spaid = spad.idspa   JOIN m0_status st ON spa.spastatus = st.kode  JOIN m1_contact c ON spad.kontak = c.kid ORDER BY spa.spaid , spad.urutan;

-- RID=50001664 | MENU=54 | ITEM=4 | RQUERY=1 | NAME=Transaksi SPA | FILE=M5SPA
SELECT     spaid , spacabang , spalokasi , spasumber , spaautonotransaksi , spanotransaksi , spatgl , spakodepa , spakontakperson , spauraian , spacatatan , spastatus , spastatussebelumnya ,   spajmlrevisi , spacetakanke , spaisclose , spainputuser , spainputtgl , spamodifikasiuser , spamodifikasitgl , spaposting , spapostingtgl , idspadetail , idspa ,   kontak , poinlama , poinkeluar , poinbaru , catatan , urutan , isclose   FROM m5_spa spa  JOIN m5_spa_detail spad ON spa.spaid = spad.idspa ORDER BY spa.spatgl ASC , spa.spaid ASC , spad. idspa ASC;

-- RID=1006 | MENU=57 | ITEM=1 | RQUERY=1 | NAME=Laporan Poin Salesman | FILE=LaporanPoinSalesman
SELECT    	k.kkode , k.knama  ,   	sc.scnama , a.anama ,   	k.kkomisipenjualan FROM m1_contact k  JOIN m1_salesman_category sc ON k.kkategorisalesman = sc.sckode  JOIN m1_area a ON k.karea = a.akode   JOIN m1_contact_category cc ON k.kkategori = cc.cckode ORDER BY k.kkode , k.kkategorisalesman , k.karea;

-- RID=1013 | MENU=57 | ITEM=2 | RQUERY=2 | NAME=Laporan Poin Salesman (Global) | FILE=LaporanPoinSalesmanGlobal
SELECT    	sp.salesmankode , sp.salesmannama ,   	sp.namapoin , sp.jumlahpoin , sp.kategorisalesmannama , sp.areasalesmannama , spp.spcatatan FROM m2r_salesman_point sp   LEFT JOIN m1_selling_point spp ON sp.idpoin = spp.spid ORDER BY sp.salesman , sp.namapoin;

-- RID=1014 | MENU=57 | ITEM=3 | RQUERY=2 | NAME=Laporan Poin Salesman (Detail) | FILE=LaporanPoinSalesmanDetail
SELECT    	sp.salesmankode , sp.salesmannama ,   	sp.idpoin,sp.namapoin ,   	sp.idinvoice , sp.tglinvoice , sp.notransaksi ,   	sp.customernama , sp.kodebarang , sp.namabarang , sp.jmlbarang ,   	sp.jmlbarangpoin , sp.nilaipoin , sp.satuanbarang ,   	sp.kategorisalesmannama , sp.areasalesmannama FROM m2r_salesman_point sp ORDER BY sp.salesman , sp.namapoin, sp.tglinvoice, sp.idinvoice;

-- RID=1018 | MENU=57 | ITEM=4 | RQUERY=2 | NAME=Laporan Rebate Salesman (Global) | FILE=RebateGLOBAL
SELECT    	sp.salesmankode , sp.salesmannama ,   	sp.namapoin , sp.jumlahpoin , sp.kategorisalesmannama , sp.areasalesmannama , sp.nilaipoin FROM m2r_salesman_point sp ORDER BY sp.salesman , sp.idpoin;

-- RID=1019 | MENU=57 | ITEM=5 | RQUERY=2 | NAME=Laporan Rebate Salesman (Detail) | FILE=RebateDETAIL
SELECT * FROM m2r_salesman_point sp;

-- RID=1098 | MENU=57 | ITEM=6 | RQUERY=1 | NAME=Laporan Komisi Salesman (Global) | FILE=KomisiGlobal
SELECT  	si.sibagianpenjualan,  	c.kkode as sibagianpenjualankode,  	c.knama as sibagianpenjualannama,  	s.snilai as simatauang,  	s2.snilai as sikurs,  	SUM(si.sikurs * si.sitotaltransaksi) as sitotaltransaksifungsional,  	kmd.kmdkodekomisi,  	SUM(  	(CASE kmd.kmdkriterianilai  WHEN 0 THEN  (CASE kmd.kmdoperator  WHEN 0 THEN (kmd.kmdnilai)  WHEN 1 THEN (kmd.kmdnilai)  WHEN 2 THEN (FLOOR((si.sikurs * si.sitotaltransaksi) / kmd.kmdjml1)) * (kmd.kmdnilai)  ELSE 0  END)  ELSE   (CASE kmd.kmdoperator  WHEN 0 THEN ((kmd.kmdnilai/100) * (si.sikurs * si.sitotaltransaksi))  WHEN 1 THEN ((kmd.kmdnilai/100) * (si.sikurs * si.sitotaltransaksi))  WHEN 2 THEN (FLOOR((si.sikurs * si.sitotaltransaksi) / kmd.kmdjml1)) * ((kmd.kmdnilai/100) * (si.sikurs * si.sitotaltransaksi))  ELSE 0  END)  END)  ) as komisi FROM m5_si si  JOIN m1_contact c ON si.sibagianpenjualan = c.kid  JOIN m1_contact cust ON si.sicustomer = cust.kid  JOIN m1_commission km ON c.kkomisikode = km.kmkode  JOIN m1_commission_detail kmd ON km.kmkode = kmd.kmdkodekomisi  JOIN m0_setting s ON s.smodule = '0' AND s.sgrup = 'accounting' AND s.skode = 'MataUangFungsional'  JOIN m0_setting s2 ON s2.smodule = '0' AND s2.sgrup = 'accounting' AND s2.skode = 'Kurs'  AND   (CASE   WHEN kmd.kmdoperator = 0   THEN (kmd.kmdjml1 <= si.sikurs * si.sitotaltransaksi AND si.sikurs * si.sitotaltransaksi <= kmd.kmdjml2)   WHEN kmd.kmdoperator = 1  THEN (si.sikurs * si.sitotaltransaksi >= kmd.kmdjml1)   WHEN kmd.kmdoperator = 2  THEN ((si.sikurs * si.sitotaltransaksi) / kmd.kmdjml1 >= 1)   ELSE kmd.kmdkodekomisi = ''  END) WHERE si.sistatus IN(2,3,4,7) GROUP BY c.kid ORDER BY c.kkode, si.sitgl, si.siid;

-- RID=1099 | MENU=57 | ITEM=7 | RQUERY=1 | NAME=Laporan Komisi Salesman (Detail) | FILE=KomisiDetail
SELECT  	si.sibagianpenjualan,  	c.kkode as sibagianpenjualankode,  	c.knama as sibagianpenjualannama,  	si.siid,  	si.sinotransaksi,  	si.sitgl,  	si.sicustomer,  	cust.kkode as sicustomerkode,  	cust.knama as sicustomernama,  	si.simatauang,  	si.sikurs,  	si.sitotaltransaksi,  	si.sikurs * si.sitotaltransaksi as sitotaltransaksifungsional,  	kmd.kmdkodekomisi,  	kmd.kmdoperator,    	(CASE kmd.kmdoperator   	WHEN 0 THEN 'Between'   	WHEN 1 THEN '>='   	WHEN 2 THEN 'Multiple'   	ELSE 'Unknown' END) as kmdoperatornama,    kmd.kmdjml1,  kmd.kmdjml2,  kmd.kmdkriterianilai,    (CASE kmd.kmdkriterianilai   	WHEN 0 THEN 'Nominal'   	WHEN 1 THEN 'Percent'   	ELSE 'Unknown' END) as kmdkriterianilainama,    kmd.kmdnilai,    (CASE kmd.kmdkriterianilai  	WHEN 0 THEN (CASE kmd.kmdoperator  								WHEN 0 THEN (kmd.kmdnilai)  								WHEN 1 THEN (kmd.kmdnilai)  								WHEN 2 THEN (FLOOR((si.sikurs * si.sitotaltransaksi) / kmd.kmdjml1)) * (kmd.kmdnilai)  								ELSE 0 END)  	ELSE (CASE kmd.kmdoperator  				WHEN 0 THEN ((kmd.kmdnilai/100) * (si.sikurs * si.sitotaltransaksi))  				WHEN 1 THEN ((kmd.kmdnilai/100) * (si.sikurs * si.sitotaltransaksi))  				WHEN 2 THEN (FLOOR((si.sikurs * si.sitotaltransaksi) / kmd.kmdjml1)) * ((kmd.kmdnilai/100) * (si.sikurs * si.sitotaltransaksi))  				ELSE 0 END)  END) as komisi FROM m5_si si  JOIN m1_contact c ON si.sibagianpenjualan = c.kid  JOIN m1_contact cust ON si.sicustomer = cust.kid  JOIN m1_commission km ON c.kkomisikode = km.kmkode  JOIN m1_commission_detail kmd ON km.kmkode = kmd.kmdkodekomisi AND (CASE WHEN kmd.kmdoperator = 0 THEN (kmd.kmdjml1 <= si.sikurs * si.sitotaltransaksi AND si.sikurs * si.sitotaltransaksi <= kmd.kmdjml2)   																																				 WHEN kmd.kmdoperator = 1 THEN (si.sikurs * si.sitotaltransaksi >= kmd.kmdjml1)   																																				 WHEN kmd.kmdoperator = 2 THEN ((si.sikurs * si.sitotaltransaksi) / kmd.kmdjml1 >= 1)   																																				 ELSE kmd.kmdkodekomisi = '' END) WHERE si.sistatus IN(2,3,4,7) ORDER BY c.kkode, si.sitgl, si.siid;

-- RID=50000565 | MENU=57 | ITEM=8 | RQUERY=1 | NAME=Komisi Salesman Limoplast (Global) | FILE=komisi_limoplast
SELECT  	c.kid,  	c.kkode,  	c.knama,  	DATEDIFF(pv.pvtgl,IFNULL(si.sitgl, sr.srtgl)) as jarak,  	SUM(  		(  			CASE  			WHEN pvd.sumber = 'SI' THEN  				pvd.jmlbayar  			ELSE  				0  			END  		)  	) AS invoice,  	sc.sckomisi1,  	SUM(  		(  			CASE  			WHEN pvd.sumber = 'SI'  			AND DATEDIFF(  				pv.pvtgl,  				IFNULL(si.sitgl, sr.srtgl)  			) <= 30 THEN  				pvd.jmlbayar  			ELSE  				0  			END  		)  	) AS 0_30,  	sc.sckomisi2,  	SUM(  		(  			CASE  			WHEN pvd.sumber = 'SI'  			AND DATEDIFF(  				pv.pvtgl,  				IFNULL(si.sitgl, sr.srtgl)  			) > 30  			AND DATEDIFF(  				pv.pvtgl,  				IFNULL(si.sitgl, sr.srtgl)  			) <= 60 THEN  				pvd.jmlbayar  			ELSE  				0  			END  		)  	) AS 31_60,  	sc.sckomisi3,  	SUM(  		(  			CASE  			WHEN pvd.sumber = 'SI'  			AND DATEDIFF(  				pv.pvtgl,  				IFNULL(si.sitgl, sr.srtgl)  			) > 60  			AND DATEDIFF(  				pv.pvtgl,  				IFNULL(si.sitgl, sr.srtgl)  			) <= 90 THEN  				pvd.jmlbayar  			ELSE  				0  			END  		)  	) AS 61_90,  	sc.sckomisi4,  	SUM(  		(  			CASE  			WHEN pvd.sumber = 'SI'  			AND DATEDIFF(  				pv.pvtgl,  				IFNULL(si.sitgl, sr.srtgl)  			) > 90  			AND DATEDIFF(  				pv.pvtgl,  				IFNULL(si.sitgl, sr.srtgl)  			) <= 120 THEN  				pvd.jmlbayar  			ELSE  				0  			END  		)  	) AS 91_120,  	sc.sckomisi5,  	SUM(  		(  			CASE  			WHEN pvd.sumber = 'SI'  			AND DATEDIFF(  				pv.pvtgl,  				IFNULL(si.sitgl, sr.srtgl)  			) > 120  			AND DATEDIFF(  				pv.pvtgl,  				IFNULL(si.sitgl, sr.srtgl)  			) <= 180 THEN  				pvd.jmlbayar  			ELSE  				0  			END  		)  	) AS 121_180,  	sc.sckomisi6,  	SUM(  		(  			CASE  			WHEN pvd.sumber = 'SI'  			AND DATEDIFF(  				pv.pvtgl,  				IFNULL(si.sitgl, sr.srtgl)  			) > 180 THEN  				pvd.jmlbayar  			ELSE  				0  			END  		)  	) AS 181_x,  	SUM(  		(  			CASE  			WHEN pvd.sumber = 'SI'  			AND DATEDIFF(  				pv.pvtgl,  				IFNULL(si.sitgl, sr.srtgl)  			) > 180 THEN  				(sc.sckomisi6 / 100) * pvd.jmlbayar * (DATEDIFF(pv.pvtgl,IFNULL(si.sitgl, sr.srtgl)) - 180)  			ELSE  				0  			END  		)   	)as komisi181_x,  	sc.sckomisi7,  	SUM(  		(  			CASE  			WHEN pvd.sumber = 'SR' THEN  				pvd.jmlbayar * -1  			ELSE  				0  			END  		)  	) AS retur   FROM 	m5_pv pv  JOIN m5_pv_detail pvd ON pv.pvid = pvd.idpv  AND pv.pvstatus IN (2, 3, 4, 7)  AND pvd.sumber IN ('SI', 'SR')  LEFT JOIN m5_si si ON pvd.sumber = si.sisumber  AND pvd.idtransaksi = si.siid  LEFT JOIN m5_sr sr ON pvd.sumber = sr.srsumber  AND pvd.idtransaksi = sr.srid  LEFT JOIN m1_contact c ON IFNULL(  	si.sibagianpenjualan,  	sr.srbagianpenjualan  ) = c.kid  LEFT JOIN m1_salesman_commission sc ON c.kid = sc.scidkontak GROUP BY c.kid ORDER BY 	c.kkode,  	pv.pvtgl,  	pv.pvnotransaksi,  	pv.pvid,  	IFNULL(si.sitgl, sr.srtgl),  	IFNULL(  		si.sinotransaksi,  		sr.srnotransaksi  	),  	IFNULL(si.siid, sr.srid),  	pvd.idpvdetail;

-- RID=50000566 | MENU=57 | ITEM=9 | RQUERY=2 | NAME=Komisi Salesman Limoplast (Detail) | FILE=komisi_limoplast_detail
SELECT  kl.idlogin,  kl.idsalesman,  kl.kodesalesman,  kl.namasalesman,  kl.idtransaksi,  kl.tgltransaksi,  kl.notransaksi,  kl.idcustomer,  kl.kodecustomer,  kl.namacustomer,  kl.tgljatuhtempo,  kl.totaltransaksi,  kl.sisa,  kl.komisi1,  kl.jml1,  (kl.komisi1 / 100) * kl.jml1 as jmlkomisi1,  kl.komisi2,  kl.jml2,  (kl.komisi2 / 100) * kl.jml2 as jmlkomisi2,  kl.komisi3,  kl.jml3,  (kl.komisi3 / 100) * kl.jml3 as jmlkomisi3,  kl.komisi4,  kl.jml4,  (kl.komisi4 / 100) * kl.jml4 as jmlkomisi4,  kl.komisi5,  kl.jml5,  (kl.komisi5 / 100) * kl.jml5 as jmlkomisi5,  kl.komisi6,  kl.jml6,  kl.jmlkomisi6,  kl.komisi7,  kl.retur,  (kl.komisi7 / 100) * kl.retur as jmlkomisi7,  kl.saldo,  kl.saldo1,  kl.saldo2,  kl.idmsmq,  kl.userid FROM m2r_komisi_limo kl ORDER BY kl.kodesalesman,  kl.tgltransaksi,  kl.notransaksi,  kl.idtransaksi,  kl.tglpelunasan,  kl.nopelunasan,  kl.idpelunasan;

-- RID=1720 | MENU=60 | ITEM=1 | RQUERY=1 | NAME=Per Customer | FILE=penjualanpercustomer
SELECT    	kc.kkode AS kodecustomer ,   	kc.knama AS sicustomer ,     	si.sinotransaksi ,   	si.sitgl ,   	ks.kkode AS kodesalesman ,   	kc.knama AS sibagianpenjualan ,   	si.sikurs ,   	si.simatauang ,   	SUM((sid.jml * sid.harga) - sid.jmldiskon) AS total ,     	si.sijmldiskon ,   	(si.sitotalpajak1detail + si.sitotalpajak2detail) AS sitotalpajak1detail  ,   	si.sibiayalain ,   	si.sitotaltransaksi    FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi   JOIN m1_contact kc ON si.sicustomer = kc.kid   JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid WHERE (si.sistatus  = 2 OR si.sistatus = 3 OR si.sistatus = 4 OR si.sistatus  = 7 ) ORDER BY si.sicustomer ASC , si.sitgl ASC , si.siid ASC;

-- RID=1740 | MENU=60 | ITEM=2 | RQUERY=1 | NAME=Per Customer Detail | FILE=penjualanpercustomer_detail
SELECT    si.sitotaltransaksi ,     si.sihargatermasukpajak ,   CASE si.sihargatermasukpajak   	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS caption ,   	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,  CASE si.sihargatermasukpajak  	WHEN 0 THEN (si.sitotalpajak1detail * 1)  	WHEN 1 THEN (si.sitotalpajak1detail * 0)   END AS pajak ,     	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total    FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid WHERE (si.sistatus  = 2 OR si.sistatus = 3 OR si.sistatus = 4 OR si.sistatus  = 7 ) ORDER BY si.sicustomer , si.sitgl ,si.sinotransaksi , sid.urutan;

-- RID=1721 | MENU=60 | ITEM=3 | RQUERY=1 | NAME=Per Customer Per Kategori Barang | FILE=penjualanpercustomer_Perkategoribarang2
SELECT    	ic.icnama AS kategori,   	  	si.sitotaltransaksi ,     	si.sihargatermasukpajak ,   	CASE si.sihargatermasukpajak   	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS caption ,   	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	sid.urutan ,   	kc.kkode AS kodecustomer ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,  CASE si.sihargatermasukpajak  	WHEN 0 THEN (si.sitotalpajak1detail * 1)  	WHEN 1 THEN (si.sitotalpajak1detail * 0)   END AS pajak ,     	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total      FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid    LEFT JOIN m1_item_category ic ON b.bkategori = ic.ickode WHERE (si.sistatus  = 2 OR si.sistatus = 3 OR si.sistatus = 4 OR si.sistatus  = 7 ) ORDER BY si.sicustomer , b.bkategori ASC , b.bkode ASC , si.sitgl , si.sinotransaksi ,  sid.urutan;

-- RID=1722 | MENU=60 | ITEM=4 | RQUERY=1 | NAME=Per Customer Per Barang | FILE=penjualanpercustomer_PerBarang2
SELECT    	si.sitotaltransaksi ,     	si.sihargatermasukpajak ,   	CASE si.sihargatermasukpajak   	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS caption ,   	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	sid.urutan ,   	kc.kkode AS kodecustomer ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,  CASE si.sihargatermasukpajak  	WHEN 0 THEN (si.sitotalpajak1detail * 1)  	WHEN 1 THEN (si.sitotalpajak1detail * 0)   END AS pajak ,     	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total    FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid WHERE (si.sistatus  = 2 OR si.sistatus = 3 OR si.sistatus = 4 OR si.sistatus  = 7 ) ORDER BY si.sicustomer , b.bkode ASC , si.sitgl , si.sinotransaksi ,  sid.urutan;

-- RID=1723 | MENU=61 | ITEM=1 | RQUERY=1 | NAME=Per Salesman | FILE=penjualanpersales
SELECT        CASE si.sihargatermasukpajak  	WHEN 0 THEN (si.sitotalpajak1detail * 0)  	WHEN 1 THEN (si.sitotalpajak1detail * 1)   END AS pengurangansubt ,     si.sihargatermasukpajak ,   CASE si.sihargatermasukpajak   	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS caption ,     	si.sibagianpenjualan AS grup ,   	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	si.sitermin ,     si.sitgljatuhtempo,  	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen ,     si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,     CASE si.sihargatermasukpajak  	WHEN 0 THEN (si.sitotalpajak1detail * 1)  	WHEN 1 THEN (si.sitotalpajak1detail * 0)   END AS pajak ,     	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   CASE b.bjenis  	WHEN "P" THEN      CASE when b.bkategori <> "JS" then sid.jml     else 0 end  	WHEN "J" THEN 0  END AS jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total ,    (CASE si.sihargatermasukpajak     WHEN 0 THEN si.sitotal - si.sijmldiskon + si.sitotalpajak1detail + si.sitotalpajak2detail + si.sibiayalain    ELSE si.sitotal - si.sijmldiskon + si.sibiayalain    END) as sitotalnew,    si.sijmluangmuka,    si.sijmlbayar - si.sijmlkembali as sijmlbayar,  	si.sitotaltransaksi - si.sijmlbayar + si.sijmlkembali as sisisa,    si.sitotaltransaksi,     CASE simatauang   	WHEN "USD" THEN (sitotaltransaksi * 1)    ELSE 0  END AS "TOTALUSD" ,     CASE simatauang   	WHEN "RMB" THEN (sitotaltransaksi * 1)    ELSE 0  END AS "TOTALRMB" ,     CASE simatauang   	WHEN "IDR" THEN (sitotaltransaksi * 1 )   	ELSE  (sitotaltransaksi * sikurs)   END AS "TOTALRP" FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid WHERE (si.sistatus  = 2 OR si.sistatus = 3 OR si.sistatus = 4 OR si.sistatus  = 7 ) ORDER BY si.sibagianpenjualan , si.sitgl , si.siid, si.sinotransaksi , sid.urutan;

-- RID=1724 | MENU=61 | ITEM=2 | RQUERY=1 | NAME=Per Salesman Per Customer | FILE=penjualanpersales_percustomer2
SELECT    	si.sitotaltransaksi ,     	CASE si.sihargatermasukpajak  	WHEN 0 THEN (si.sitotalpajak1detail * 0)  	WHEN 1 THEN (si.sitotalpajak1detail * 1)   END AS pengurangansubt ,     si.sihargatermasukpajak ,   CASE si.sihargatermasukpajak   	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS caption ,     	si.sibagianpenjualan AS grup ,   	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	si.sitermin ,     si.sitgljatuhtempo,  	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen ,     si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,     CASE si.sihargatermasukpajak  	WHEN 0 THEN (si.sitotalpajak1detail * 1)  	WHEN 1 THEN (si.sitotalpajak1detail * 0)   END AS pajak ,     	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total ,    (CASE si.sihargatermasukpajak     WHEN 0 THEN si.sitotal - si.sijmldiskon + si.sitotalpajak1detail + si.sitotalpajak2detail + si.sibiayalain    ELSE si.sitotal - si.sijmldiskon + si.sibiayalain    END) as sitotalnew,    si.sijmluangmuka,    si.sijmlbayar - si.sijmlkembali as sijmlbayar,  	si.sitotaltransaksi - si.sijmlbayar + si.sijmlkembali as sisisa FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid WHERE (si.sistatus  = 2 OR si.sistatus = 3 OR si.sistatus = 4 OR si.sistatus  = 7 ) ORDER BY si.sibagianpenjualan , si.sicustomer , si.sitgl , si.siid, si.sinotransaksi , sid.urutan, sid.idsidetail;

-- RID=1725 | MENU=61 | ITEM=3 | RQUERY=1 | NAME=Per Salesman Per Kategori Barang | FILE=penjualanpersales_Perkategoribarang2
SELECT    	ic.icnama AS kategori,   	  	si.sitotaltransaksi ,     	si.sihargatermasukpajak ,   	CASE si.sihargatermasukpajak   	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS caption ,   	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	sid.urutan ,   	kc.kkode AS kodecustomer ,   	kc.knama AS sicustomer ,   	ks.kkode AS sibagianpenjualankode ,   	ks.knama AS sibagianpenjualan  ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,  CASE si.sihargatermasukpajak  	WHEN 0 THEN (si.sitotalpajak1detail * 1)  	WHEN 1 THEN (si.sitotalpajak1detail * 0)   END AS pajak ,     	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid    LEFT JOIN m1_item_category ic ON b.bkategori = ic.ickode WHERE (si.sistatus  = 2 OR si.sistatus = 3 OR si.sistatus = 4 OR si.sistatus  = 7 ) ORDER BY si.sibagianpenjualan , b.bkategori ASC , b.bkode ASC , si.sitgl , si.sinotransaksi ,  sid.urutan;

-- RID=1726 | MENU=61 | ITEM=4 | RQUERY=1 | NAME=Per Salesman Per Barang | FILE=penjualanpersales_PerBarang
SELECT    	si.sitotaltransaksi ,     	si.sihargatermasukpajak ,   	CASE si.sihargatermasukpajak   	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS caption ,   	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	sid.urutan ,   	kc.kkode AS kodecustomer ,   	kc.knama AS sicustomer ,   	ks.kkode AS sibagianpenjualankode,   	ks.knama AS sibagianpenjualan  ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,  CASE si.sihargatermasukpajak  	WHEN 0 THEN (si.sitotalpajak1detail * 1)  	WHEN 1 THEN (si.sitotalpajak1detail * 0)   END AS pajak ,     	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid WHERE (si.sistatus  = 2 OR si.sistatus = 3 OR si.sistatus = 4 OR si.sistatus  = 7 ) ORDER BY si.sibagianpenjualan, b.bkode ASC , si.sitgl , si.sinotransaksi , sid.urutan;

-- RID=1727 | MENU=62 | ITEM=1 | RQUERY=1 | NAME=Per Barang | FILE=penjualanperproduk
SELECT    	CASE si.sihargatermasukpajak  	WHEN 0 THEN (sid.jmlpajak1 * 0)  	WHEN 1 THEN (sid.jmlpajak1 * 1)   END AS pengurangansubt ,     si.sihargatermasukpajak ,   CASE si.sihargatermasukpajak   	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS caption ,     CASE si.sihargatermasukpajak  	WHEN 0 THEN (sid.jmlpajak1 * 1)  	WHEN 1 THEN (sid.jmlpajak1 * 0)   END AS pajak ,     	sid.idbarang AS grup ,     	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	si.sitermin ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,     	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total  ,    sid.jmlpajak1 FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid WHERE (si.sistatus  = 2 OR si.sistatus = 3 OR si.sistatus = 4 OR si.sistatus  = 7 ) ORDER BY sid.idbarang , b.bkode , sid.namabarang ,  si.sitgl , si.siid, si.sinotransaksi , sid.urutan;

-- RID=1728 | MENU=62 | ITEM=2 | RQUERY=1 | NAME=Per Barang Per Customer | FILE=penjualanperproduk_percustomer
SELECT    	CASE si.sihargatermasukpajak  	WHEN 0 THEN (sid.jmlpajak1 * 0)  	WHEN 1 THEN (sid.jmlpajak1 * 1)   END AS pengurangansubt ,     si.sihargatermasukpajak ,   CASE si.sihargatermasukpajak   	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS caption ,     CASE si.sihargatermasukpajak  	WHEN 0 THEN (sid.jmlpajak1 * 1)  	WHEN 1 THEN (sid.jmlpajak1 * 0)   END AS pajak ,     	sid.idbarang AS grup ,     	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	si.sitermin ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,     	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total  ,    sid.jmlpajak1 FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid WHERE (si.sistatus  = 2 OR si.sistatus = 3 OR si.sistatus = 4 OR si.sistatus  = 7 ) ORDER BY sid.idbarang , b.bkode , sid.namabarang ,  si.sicustomer , si.sitgl , si.siid, si.sinotransaksi , sid.urutan;

-- RID=17288 | MENU=62 | ITEM=3 | RQUERY=1 | NAME=Rekap Penjualan Per Barang | FILE=rekap_penjualan_perbarang_alamindo
SELECT    b.bgudang ,   w.wnama ,   dp.dpnama AS bdepartemen ,   sdp.sdpnama AS bsubdepartemen ,   b.bkode ,   b.bnama ,   SUM(sid.jml) AS jml ,   (Sum(sid.jml * un.unilai) - (Sum(sid.jml * un.unilai) MOD unit.unilai)) / unit.unilai As KRT ,   ((Sum(sid.jml * un.unilai) MOD unit.unilai ) - (Sum(sid.jml * un.unilai) MOD unit.unilai)  mod 12) / 12  AS LSN ,   (Sum(sid.jml * un.unilai) MOD unit.unilai)  mod 12 AS PCS  ,       unit.unilai 	,   b.bcustom2 ,     SUM((sid.jml * un.unilai) * (harga - (jmldiskon / (sid.jml * un.unilai)))) AS total ,   SUM(sid.harga) AS harga ,   sum(sid.jmldiskon) AS jmldiskon FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi   JOIN m1_item b ON sid.idbarang = b.bid   JOIN m1_department dp ON b.bdepartemen = dp.dpkode   JOIN m1_subdepartment sdp ON b.bsubdepartemen = sdp.sdpkode   LEFT JOIN m1_unit unit ON b.bcustom2 = unit.ukode   JOIN m1_unit un ON sid.satuan = un.ukode   LEFT JOIN m1_warehouse w ON b.bgudang = w.wkode WHERE si.sistatus IN(2,3,4,7) GROUP BY b.bgudang ASC , b.bdepartemen ASC , b.bsubdepartemen , sid.idbarang ASC ORDER BY b.bgudang ASC , b.bdepartemen ASC , b.bsubdepartemen , sid.idbarang ASC;

-- RID=1729 | MENU=63 | ITEM=1 | RQUERY=1 | NAME=Per Proyek | FILE=penjualan_Perproyek
SELECT    p.pkode AS cckode , p.pnama as ccnama ,     	CASE si.sihargatermasukpajak  	WHEN 0 THEN (sid.jmlpajak1 * 0)  	WHEN 1 THEN (sid.jmlpajak1 * 1)   END AS pengurangansubt ,     si.sihargatermasukpajak ,   CASE si.sihargatermasukpajak   	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS caption ,     CASE si.sihargatermasukpajak  	WHEN 0 THEN (sid.jmlpajak1 * 1)  	WHEN 1 THEN (sid.jmlpajak1 * 0)   END AS pajak ,     	sid.idbarang AS grup ,     	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	si.sitermin ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,     	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total  ,    sid.jmlpajak1 FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid    JOIN m1_project p ON sid.proyek = p.pkode   WHERE (si.sistatus  = 2 OR si.sistatus = 3 OR si.sistatus = 4 OR si.sistatus  = 7 ) ORDER BY sid.proyek,  si.sitgl , si.siid, si.sinotransaksi , sid.idbarang , b.bkode , sid.namabarang ,sid.urutan;

