-- RID=1735 | MENU=65 | ITEM=1 | RQUERY=1 | NAME=Per Cost Center | FILE=penjualan_percostcenter
SELECT    cc.cckode ,   cc.ccnama ,   si.sinotransaksi , si.sitgl ,   k.kkode , k.knama ,   b.bkode ,   b.bnama ,   sid.jml , sid.satuan ,   sid.harga ,   sid.diskon ,   (sid.jmlpajak1 + sid.jmlpajak2) AS pajak ,   CASE si.sihargatermasukpajak   	WHEN 0 THEN ((sid.jml * sid.harga) - sid.jmldiskon) + (sid.jmlpajak1 + sid.jmlpajak2)  	WHEN 1 THEN ((sid.jml * sid.harga) - sid.jmldiskon)   END AS total FROM m5_si si   JOIN m5_si_detail sid ON si.siid = sid.idsi   JOIN m1_item b ON sid.idbarang = b.bid   LEFT JOIN m1_cost_center cc ON sid.costcenter = cc.cckode   JOIN m1_contact k ON si.sicustomer = k.kid WHERE (si.sistatus  = 2 OR si.sistatus = 3 OR si.sistatus = 4 OR si.sistatus  = 7 ) ORDER BY cc.cckode ASC, si.sitgl ASC;

