SELECT    cc.cckode , cc.ccnama ,     	CASE si.sihargatermasukpajak  	WHEN 0 THEN (sid.jmlpajak1 * 0)  	WHEN 1 THEN (sid.jmlpajak1 * 1)   END AS pengurangansubt ,     si.sihargatermasukpajak ,   CASE si.sihargatermasukpajak   	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS caption ,     CASE si.sihargatermasukpajak  	WHEN 0 THEN (sid.jmlpajak1 * 1)  	WHEN 1 THEN (sid.jmlpajak1 * 0)   END AS pajak ,     	sid.idbarang AS grup ,     	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	si.sitermin ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,     	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total  ,    sid.jmlpajak1 FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid    JOIN m1_cost_center cc ON sid.costcenter = cc.cckode WHERE (si.sistatus  = 2 OR si.sistatus = 3 OR si.sistatus = 4 OR si.sistatus  = 7 ) ORDER BY sid.costcenter , sid.idbarang , b.bkode , sid.namabarang ,  si.sitgl , si.siid, si.sinotransaksi , sid.urutan;

-- RID=1738 | MENU=66 | ITEM=1 | RQUERY=1 | NAME=Per Kategori Barang | FILE=pernjualanperkategoribarang
SELECT    CASE si.sihargatermasukpajak  	WHEN 0 THEN (sid.jmlpajak1 * 0)  	WHEN 1 THEN (sid.jmlpajak1 * 1)   END AS pengurangansubt ,     si.sihargatermasukpajak ,   CASE si.sihargatermasukpajak   	WHEN 0 THEN "Belum Termasuk Pajak"  	WHEN 1 THEN "Sudah Termasuk Pajak"  END AS caption ,     CASE si.sihargatermasukpajak  	WHEN 0 THEN (sid.jmlpajak1 * 1)  	WHEN 1 THEN (sid.jmlpajak1 * 0)   END AS pajak ,       	sid.idbarang AS grup ,     	si.siid ,   	si.sitgl ,   	si.sinotransaksi ,   	kc.knama AS sicustomer ,   	ks.knama AS sibagianpenjualan  ,   	si.sitermin ,   	st.nama AS sistatus ,  	si.siuraian ,  	si.simatauang ,   	si.sikurs ,   	si.sidiskonpersen , si.sijmldiskon,   	si.sibiayalain ,   	si.sitotalpajak1detail,     b.bkategori ,  ic.icnama AS kategori,   	b.bkode ,   	sid.namabarang ,   	sid.catatan ,   	sid.jml ,   	sid.satuan ,   	sid.harga ,   	sid.diskon ,   	((sid.jml * sid.harga) - sid.jmldiskon) AS total ,   sid.jmlpajak1 FROM m5_si si  JOIN m1_contact kc ON si.sicustomer = kc.kid  JOIN m1_contact ks ON si.sibagianpenjualan = ks.kid  JOIN m0_status st on si.sistatus = st.kode    JOIN m5_si_detail sid ON si.siid = sid.idsi  JOIN m1_item b on sid.idbarang = b.bid      JOIN m1_item_category ic ON b.bkategori = ic.ickode WHERE (si.sistatus  = 2 OR si.sistatus = 3 OR si.sistatus = 4 OR si.sistatus  = 7 ) ORDER BY b.bkategori, sid.idbarang , b.bkode , sid.namabarang ,  si.sitgl , si.siid, si.sinotransaksi , sid.urutan;

-- RID=7777 | MENU=67 | ITEM=1 | RQUERY=2 | NAME=Komisi Salesman Global | FILE=komisi_salesman_abd[cb]
SELECT    	komisi.nourut,     	CASE komisi.nourut  	WHEN 1 THEN 1  	ELSE 2  END AS "SUM" ,     komisi.idlogin , komisi.idmsmq , komisi.userid , komisi.salesmankode , komisi.salesmannama , komisi.tgl , komisi.notransaksi , komisi.sumber ,   	CASE komisi.sumber  	WHEN "SI" THEN "Total Penjualan"  	WHEN "SR" THEN "Total Retur Penjualan"  END AS caption ,   komisi.customerkode , komisi.customernama ,   komisi.barangkode , komisi.barangnama , komisi.kategorikode , komisi.kategoribarang , komisi.grupkode , komisi.grup,  SUM(komisi.jumlah) as jumlah ,     CONCAT(komisi.sumber,"-",komisi.grup) as a ,     SUM(CASE komisi.sumber  	WHEN "SI" THEN (komisi.jumlah * 1)  	WHEN "SR" THEN (komisi.jumlah * -1)  END) AS total ,       (IFNULL(paku.snilai,0) * 1) AS komisipaku,   (IFNULL(kawat.snilai,0)* 1) AS komisikawat,   (IFNULL(lain.snilai,0)* 1) AS komisilain FROM m2r_komisi_abd komisi   LEFT JOIN m0_setting paku ON paku.sgrup = 'komisi' AND paku.skode = CONCAT('paku-',komisi.salesmankode)  LEFT JOIN m0_setting kawat ON kawat.sgrup = 'komisi' AND kawat.skode = CONCAT('kawat-',komisi.salesmankode)  LEFT JOIN m0_setting lain ON lain.sgrup = 'komisi' AND lain.skode = CONCAT('lain-',komisi.salesmankode) GROUP BY komisi.salesmankode , komisi.sumber , komisi.grup ORDER BY komisi.salesmankode , komisi.nourut, komisi.sumber , komisi.grup;

-- RID=7771 | MENU=67 | ITEM=2 | RQUERY=2 | NAME=Komisi Salesman Detail | FILE=komisi_salesman_abd[cb2]
SELECT    	komisi.nourut,     	CASE komisi.nourut  	WHEN 1 THEN 1  	ELSE 2  END AS "SUM" ,     komisi.idlogin , komisi.idmsmq , komisi.userid , komisi.salesmankode , komisi.salesmannama , komisi.tgl , komisi.notransaksi , komisi.sumber ,   	CASE komisi.sumber  	WHEN "SI" THEN "Penjualan"  	WHEN "SR" THEN "Retur Penjualan"  END AS caption ,   komisi.customerkode , komisi.customernama ,   komisi.barangkode , komisi.barangnama , komisi.kategorikode , komisi.kategoribarang , komisi.grupkode , komisi.grup,  SUM(komisi.jumlah) as jumlah ,     CONCAT(komisi.sumber,"-",komisi.grup) as a ,     SUM(CASE komisi.sumber  	WHEN "SI" THEN (komisi.jumlah * 1)  	WHEN "SR" THEN (komisi.jumlah * -1)  END )AS total ,       (IFNULL(paku.snilai,0) * 1) AS komisipaku,   (IFNULL(kawat.snilai,0)* 1) AS komisikawat,   (IFNULL(lain.snilai,0)* 1) AS komisilain FROM m2r_komisi_abd komisi   LEFT JOIN m0_setting paku ON paku.sgrup = 'komisi' AND paku.skode = CONCAT('paku-',komisi.salesmankode)  LEFT JOIN m0_setting kawat ON kawat.sgrup = 'komisi' AND kawat.skode = CONCAT('kawat-',komisi.salesmankode)  LEFT JOIN m0_setting lain ON lain.sgrup = 'komisi' AND lain.skode = CONCAT('lain-',komisi.salesmankode) GROUP BY komisi.salesmankode , komisi.sumber , komisi.tgl, komisi.notransaksi ,  komisi.grup ORDER BY komisi.salesmankode , komisi.sumber , komisi.tgl, komisi.notransaksi ,  komisi.grup;

-- RID=500051 | MENU=68 | ITEM=1 | RQUERY=1 | NAME=Tukar Faktur Penjualan (SIE) 1/2 Letter | FILE=sie
SELECT  sie.sieid ,   sie.sienotransaksi ,   sie.sietgl ,   sie.sieuraian ,   sie.siecatatan ,   	st.nama as piestatusnama,  	c.kkode as supplierkode,  	c.knama as supppliernama,  	c.k1alamat1 as alamat,  	c.k1alamat2 as alamat2,  	sied.sumber,  	sied.idtransaksi,  	(CASE sied.sumber WHEN 'SI' THEN si.sinotransaksi WHEN 'SR' THEN sr.srnotransaksi ELSE '' END) as notransaksi,  (CASE sied.sumber WHEN 'SI' THEN si.sitgl WHEN 'SR' THEN sr.srtgl ELSE '1900-01-01' END) as tgl,  (CASE sied.sumber WHEN 'SI' THEN si.simatauang WHEN 'SR' THEN sr.srmatauang ELSE '' END) as matauang,  (CASE sied.sumber WHEN 'SI' THEN si.sikurs WHEN 'SR' THEN sr.srkurs ELSE '' END) as kurs,  (CASE sied.sumber WHEN 'SI' THEN si.sitotaltransaksi WHEN 'SR' THEN sr.srtotaltransaksi * -1 ELSE '0' END) as totaltransaksi,  (CASE sied.sumber WHEN 'v' THEN si.sitermin WHEN 'SR' THEN sr.srtermin ELSE '' END) as termin,  (CASE sied.sumber WHEN 'v' THEN si.siuraian WHEN 'SR' THEN sr.sruraian ELSE '' END) as uraian,  IFNULL(tr.trharijatuhtempo,0) as harijatuhtempo,  (CASE sied.sumber WHEN 'SI' THEN si.sitgljatuhtempo WHEN 'SR' THEN sr.srtgljatuhtempo ELSE '1900-01-01' END) as tgljatuhtempo,  catatan,  urutan,  isclose,  customtext1,  customtext2,  customtext3,  customdbl1,  customdbl2,  customdbl3,  customdate1,  customdate2,  customdate3 FROM m5_sie sie  JOIN m5_sie_detail sied ON sie.sieid = sied.idsie  JOIN m0_status st ON sie.siestatus = st.kode  LEFT JOIN m5_si si ON sied.sumber = si.sisumber AND sied.idtransaksi = si.siid  LEFT JOIN m5_sr sr ON sied.sumber = sr.srsumber AND sied.idtransaksi = sr.srid    LEFT JOIN m1_contact c ON IFNULL(si.sicustomer,sr.srcustomer) = c.kid  LEFT JOIN m1_terms tr ON IFNULL(si.sitermin,sr.srtermin) = tr.trkode ORDER BY sie.sietgl , sieid, sie.sienotransaksi, sied.urutan;

-- RID=500052 | MENU=68 | ITEM=2 | RQUERY=1 | NAME=Tukar Faktur Penjualan (SIE) 1 Letter | FILE=sie2
SELECT  sie.sieid ,   sie.sienotransaksi ,   sie.sietgl ,   sie.sieuraian ,   sie.siecatatan ,   	st.nama as piestatusnama,  	c.kkode as supplierkode,  	c.knama as supppliernama,  	c.k1alamat1 as alamat,  	c.k1alamat2 as alamat2,  	sied.sumber,  	sied.idtransaksi,  	(CASE sied.sumber WHEN 'SI' THEN si.sinotransaksi WHEN 'SR' THEN sr.srnotransaksi ELSE '' END) as notransaksi,  (CASE sied.sumber WHEN 'SI' THEN si.sitgl WHEN 'SR' THEN sr.srtgl ELSE '1900-01-01' END) as tgl,  (CASE sied.sumber WHEN 'SI' THEN si.simatauang WHEN 'SR' THEN sr.srmatauang ELSE '' END) as matauang,  (CASE sied.sumber WHEN 'SI' THEN si.sikurs WHEN 'SR' THEN sr.srkurs ELSE '' END) as kurs,  (CASE sied.sumber WHEN 'SI' THEN si.sitotaltransaksi WHEN 'SR' THEN sr.srtotaltransaksi * -1 ELSE '0' END) as totaltransaksi,  (CASE sied.sumber WHEN 'v' THEN si.sitermin WHEN 'SR' THEN sr.srtermin ELSE '' END) as termin,  (CASE sied.sumber WHEN 'v' THEN si.siuraian WHEN 'SR' THEN sr.sruraian ELSE '' END) as uraian,  IFNULL(tr.trharijatuhtempo,0) as harijatuhtempo,  (CASE sied.sumber WHEN 'SI' THEN si.sitgljatuhtempo WHEN 'SR' THEN sr.srtgljatuhtempo ELSE '1900-01-01' END) as tgljatuhtempo,  catatan,  urutan,  isclose,  customtext1,  customtext2,  customtext3,  customdbl1,  customdbl2,  customdbl3,  customdate1,  customdate2,  customdate3 FROM m5_sie sie  JOIN m5_sie_detail sied ON sie.sieid = sied.idsie  JOIN m0_status st ON sie.siestatus = st.kode  LEFT JOIN m5_si si ON sied.sumber = si.sisumber AND sied.idtransaksi = si.siid  LEFT JOIN m5_sr sr ON sied.sumber = sr.srsumber AND sied.idtransaksi = sr.srid    LEFT JOIN m1_contact c ON IFNULL(si.sicustomer,sr.srcustomer) = c.kid  LEFT JOIN m1_terms tr ON IFNULL(si.sitermin,sr.srtermin) = tr.trkode ORDER BY sie.sietgl , sieid, sie.sienotransaksi, sied.urutan;

-- RID=50001665 | MENU=68 | ITEM=3 | RQUERY=1 | NAME=Transaksi SIE | FILE=M5SIE
SELECT     sieid , siecabang , sielokasi , siesumber , sieautonotransaksi , sienotransaksi , sietgl , siekodepa , siekontak , siekontakperson , sie1alamat1 , sie1alamat2 , sie2alamat3 ,   sie2alamat1 , sie2alamat2 , sie2alamat3 , sieuraian , siecatatan , sienoref , siestatus , siestatussebelumnya , siejmlrevisi , siecetakanke , sieinputuser , sieinputtgl ,   siemodifikasiuser , siemodifikasitgl , sieposting , siepostingtgl , sieisclose , idsiedetail , idsie , sumber , idtransaksi , catatan , urutan , isclose FROM m5_sie sie  JOIN m5_sie_detail sied ON sie.sieid = sied.idsie ORDER BY sie.sietgl ASC , sie.sieid ASC , sied.idsie ASC;

