-- RID=50003781 | MENU=75 | ITEM=1 | RQUERY=1 | NAME=Sales Contract Report | FILE=kontrak_jual
SELECT   sfnotransaksi,  k.kkode as customerkode,  k.knama AS customernama,  sfd.divisi,  sfd.catatan,  sfd.jml - sfd.jmlrealisasi as jml,  sfd.harga,  sf.sfuraian,  CASE divisi WHEN "BR" THEN (jml  - sfd.jmlrealisasi)* 1 ELSE 0	END AS totalbr,  CASE divisi WHEN "BW" THEN (jml  - sfd.jmlrealisasi)*  1 ELSE 0	END AS totalbw FROM m5_sf sf JOIN m5_sf_detail sfd ON sf.sfid = sfd.idsf  JOIN m1_contact k ON sf.sfcustomer = k.kid WHERE sf.sfstatus in(2,3,4)    and sfd.jml - sfd.jmlrealisasi > 0 ORDER BY sf.sftgl ASC , sf.sfid ASC , sfd.urutan ASC;

-- RID=50003800 | MENU=75 | ITEM=2 | RQUERY=1 | NAME=Sales Booking Outstanding | FILE=listsalescontractoutstanding
SELECT   sfid,  sftgl,  sfnotransaksi,  k.kkode as customerkode,  k.knama AS customernama,  m.kkode as salesmankode,  m.knama AS salesmannama,  sf.sfmatauang,    sfd.divisi,  sfd.catatan,  sfd.jml,  sfd.jmlrealisasi,  sfd.jml - sfd.jmlrealisasi as jmlsisa,  sfd.harga,  sfd.satuan,    sf.sfuraian FROM m5_sf sf JOIN m5_sf_detail sfd ON sf.sfid = sfd.idsf  JOIN m1_contact k ON sf.sfcustomer = k.kid  join m1_contact m on sf.sfbagianpenjualan = m.kid WHERE sf.sfstatus in(2,3,4)    and sfd.jml - sfd.jmlrealisasi > 0 ORDER BY m.knama asc, sf.sftgl asc;

-- RID=50003768 | MENU=81 | ITEM=1 | RQUERY=2 | NAME=Daily Sales | FILE=Daily Sales
SELECT   	idlogin,  	idmsmq,  	tgl,  	notransaksi,  	salesmankode,  	salesmannama,  	sumber,  	divisi,  	customtext1,  	customtext2,  	customtext3,  	customtext4,  	customtext5,  	lrcustomint1,  	lrcustomint2,  	lrcustomint3,  	lrcustomint4,  	lrcustomint5,  	pkcustomdbl1,  	pkcustomdbl2,  	(pkcustomdbl3 * pkcustomdbl7) AS pkcustomdbl3 ,  	(pkcustomdbl4 * pkcustomdbl7) AS pkcustomdbl4 ,  	pkcustomdbl5,  	pkcustomdbl6,  	lrcustomdate1,   	pkcustomdbl7,     CASE sumber 	WHEN "SO" THEN CASE divisi  WHEN "BR" THEN (pkcustomdbl1 - pkcustomdbl2) * 1 ELSE 0	END ELSE 0 END AS SOBR ,     CASE sumber 	WHEN "SO" THEN CASE WHEN divisi <> "BR" THEN (pkcustomdbl1 - pkcustomdbl2) * 1 ELSE 0	END ELSE 0 END AS SOBW ,     CASE sumber 	WHEN "SI" THEN CASE divisi  WHEN "BR" THEN (pkcustomdbl1 - pkcustomdbl2) * 1 ELSE 0 END ELSE 0 END AS SIBR ,     CASE sumber 	WHEN "SI" THEN CASE divisi  WHEN "BW" THEN (pkcustomdbl1 - pkcustomdbl2) * 1 ELSE 0 END ELSE 0 END AS SIBW FROM m2r_daily_sales ORDER BY salesmankode asc;

-- RID=50003840 | MENU=81 | ITEM=2 | RQUERY=2 | NAME=Daily Sales (New) | FILE=DailySales2
SELECT   	idlogin,  	idmsmq,  	tgl,  	notransaksi,  	salesmankode,  	salesmannama,  	sumber,  	divisi,  	customtext1,  	customtext2,  	customtext3,  	customtext4,  	customtext5,  	lrcustomint1,  	lrcustomint2,  	lrcustomint3,  	lrcustomint4,  	lrcustomint5,  	pkcustomdbl1,  	pkcustomdbl2,  	(pkcustomdbl3 * pkcustomdbl7) AS pkcustomdbl3 ,  	(pkcustomdbl4 * pkcustomdbl7) AS pkcustomdbl4 ,  	pkcustomdbl5,  	pkcustomdbl6,  	lrcustomdate1,   	pkcustomdbl7,   CASE sumber 	WHEN "SO" THEN CASE divisi  WHEN "BR" THEN (pkcustomdbl1 - pkcustomdbl2) * 1 ELSE 0	END ELSE 0 END AS SOBR ,     CASE sumber 	WHEN "SO" THEN CASE WHEN divisi <> "BR" THEN (pkcustomdbl1 - pkcustomdbl2) * 1 ELSE 0	END ELSE 0 END AS SOBW ,     CASE sumber 	WHEN "SI" THEN CASE divisi  WHEN "BR" THEN (pkcustomdbl1 - pkcustomdbl2) * 1 ELSE 0 END ELSE 0 END AS SIBR ,     CASE sumber 	WHEN "SI" THEN CASE divisi  WHEN "BW" THEN (pkcustomdbl1 - pkcustomdbl2) * 1 ELSE 0 END ELSE 0 END AS SIBW ,  pkcustomdbl5 * 11 as bryear,  pkcustomdbl6 * 11 as bwyear,  ytdbr,  ytdbw,  ytdnilai FROM m2r_daily_sales_new ORDER BY salesmankode asc;

-- RID=50003774 | MENU=82 | ITEM=1 | RQUERY=1 | NAME=Customer OEM Status | FILE=RI_SI PCI
SELECT  a.tgl as tgl,  GROUP_CONCAT(DISTINCT a.notransaksi) as notransaksi,  SUM(a.jmlri) - SUM(a.jmlsi) as jml,  a.sumber as sumber,  SUM(a.jmlri) as jmlri,  SUM(a.jmlsi) as jmlsi,  a.satuan as satuan,  a.idsupplier as idsupplier,  a.kodesupplier as kodesupplier,  CONCAT(a.kodesupplier,' - ',a.namasupplier) as namasupplier,  a.idcustomer as idcustomer,  a.kodecustomer as kodecustomer,  CONCAT(a.kodecustomer,' - ',a.namacustomer) as namacustomer,  a.idsalesman as idsalesman,  sl.kkode as kodesalesman,  CONCAT(sl.kkode,' - ',sl.knama) as namasalesman,  a.statuss as statuss     FROM   (SELECT  ri.ritgl as tgl,  GROUP_CONCAT(DISTINCT ri.rinotransaksi) as notransaksi,  0 as jml,  ri.risumber as sumber,  SUM(rid.jml) as jmlri,  0 as jmlsi,  rid.satuan,  s.kid as idsupplier,  s.kkode as kodesupplier,  s.knama as namasupplier,  c.kid as idcustomer,  c.kkode as kodecustomer,  c.knama as namacustomer,  c.ksalesman as idsalesman,  ri.ristatus as statuss    FROM  m1_contact s  JOIN m1_contact c ON s.kcustomtext6 = c.kkode  JOIN m4_ri ri ON s.kid = ri.risupplier  JOIN m4_ri_detail rid ON ri.riid = rid.idri AND ri.ristatus IN(2,3,4,7) AND rid.harga = 0  GROUP BY s.kkode ASC, s.kid ASC, ri.ritgl ASC    UNION ALL    SELECT  si.sitgl as tgl,  GROUP_CONCAT(DISTINCT si.sinotransaksi) as notransaksi,  0 as jml,  si.sisumber as sumber,  0 as jmlri,  SUM(sid.jml) as jmlsi,  sid.satuan,  s.kid as idsupplier,  s.kkode as kodesupplier,  s.knama as namasupplier,  c.kid as idcustomer,  c.kkode as kodecustomer,  c.knama as namacustomer,  c.ksalesman as idsalesman,  si.sistatus as statuss    FROM  m1_contact s  JOIN m1_contact c ON s.kcustomtext6 = c.kkode  JOIN m5_si si ON c.kid = si.sicustomer  JOIN m5_si_detail sid ON si.siid = sid.idsi AND si.sistatus IN(2,3,4,7) AND sid.harga = 0  GROUP BY s.kkode ASC, s.kid ASC, si.sitgl ASC) as a  LEFT JOIN m1_contact sl ON a.idsalesman = sl.kid   GROUP BY a.kodesupplier ASC, a.idsupplier ASC, a.tgl ASC ORDER BY a.kodesupplier ASC, a.idsupplier ASC, a.tgl ASC;

-- RID=50003791 | MENU=84 | ITEM=1 | RQUERY=1 | NAME=Order Tracking | FILE=order_tracking
sql FROM sql;
